INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aec215a-e781-43a8-86ca-c59393482f24', '長安人爲宋清語（題擬）', '长安人爲宋清語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["人有義聲，賣藥宋清。","（同前卷中）。"]', '["人有義声，賣藥宋清。","（同前卷中）。"]', '诗', 'shi', '', NULL, '長安人爲宋清語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c36c695d-b476-4e58-a963-64eccb41a38e', '峽中舊語（題擬）', '峽中旧語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["五月下峽，死而不弔。","（同前卷下）。"]', '["五月下峽，死而不弔。","（同前卷下）。"]', '诗', 'shi', '', NULL, '峽中舊語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b79e6bd-c8da-490d-ae5c-40030000b3d7', '江湖語', '江湖語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["水不載萬。","（同前）（〖1〗《國史補》云此言「大船不過八九千石」。","）。"]', '["水不載万。","（同前）（〖1〗《国史補》云此言「大船不過八九千石」。","）。"]', '诗', 'shi', '', NULL, '江湖語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5bd6c54-d5bd-4ec0-9165-c8768e6224d8', '時人爲兔褐語（題從《古謠諺》卷五八）', '时人爲兔褐語（題從《古謠諺》卷五八）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["兔褐真不如假。","（同前）。"]', '["兔褐真不如假。","（同前）。"]', '诗', 'shi', '', NULL, '時人爲兔褐語（題從《古謠諺》卷五八） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07212746-cd2a-430a-b195-636def9c70c6', '鎮海軍壯兒語（題擬）', '鎮海軍壯兒語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["壯兒過大梁，如上龍門。","（《雲溪友議》卷上）。"]', '["壯兒過大梁，如上龙门。","（《云溪友議》卷上）。"]', '诗', 'shi', '', NULL, '鎮海軍壯兒語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad97344-b2f8-41df-924d-45c8688fd460', '歷城土人爲光政寺磬語（題擬）', '歷城土人爲光政寺磬語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["磬神聖，戀光政。","（《酉陽雜俎》卷三）。"]', '["磬神聖，戀光政。","（《酉陽杂俎》卷三）。"]', '诗', 'shi', '', NULL, '歷城土人爲光政寺磬語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('facbaca3-b3e1-49e6-960f-c1fbaabc65ad', '齊人爲妬婦津語（題擬）', '齊人爲妬婦津語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["欲求好婦，立在津口。","婦立水傍，好醜自彰。","（同前卷十六）。"]', '["欲求好婦，立在津口。","婦立水傍，好醜自彰。","（同前卷十六）。"]', '诗', 'shi', '', NULL, '齊人爲妬婦津語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0df7b0d-b967-4eda-9e18-d08c6681f6ff', '文宗時舉場中語（題擬）', '文宗时舉場中語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["鄉貢進士，不博上州刺史。","（《太平廣記》卷一八一引《盧氏雜說》）。"]', '["乡貢進士，不博上州刺史。","（《太平廣記》卷一八一引《盧氏杂说》）。"]', '诗', 'shi', '', NULL, '文宗時舉場中語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa1d33a-afe1-45dd-99cb-0ced2bb39459', '京師語', '京師語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["丑侯䁸䁸，多用半裝。","（《續談助》卷三引《牛羊日曆》引）。"]', '["丑侯䁸䁸，多用半裝。","（《續談助》卷三引《牛羊日曆》引）。"]', '诗', 'shi', '', NULL, '京師語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ba6315-9ae4-4617-a02d-376be81fc091', '會昌中長安人語', '會昌中长安人語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["今年長安人喫人。","（《入唐求法巡禮行記》卷四）。"]', '["今年长安人喫人。","（《入唐求法巡禮行記》卷四）。"]', '诗', 'shi', '', NULL, '會昌中長安人語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57829cc1-4068-4cdd-b61c-ed97faff18a8', '里語', '里語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["當時婦棄夫，今日夫棄婦。","若不逞丹青，空房應獨守。","（見《雲溪友議》卷上）。"]', '["當时婦棄夫，今日夫棄婦。","若不逞丹青，空房應独守。","（见《云溪友議》卷上）。"]', '诗', 'shi', '', NULL, '里語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69d08894-410e-48ad-935b-4f6ae2649b65', '時人爲劉師貞語', '时人爲劉師貞語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["孝於何，通神明。","漢有丁蘭，唐有師貞。"]', '["孝於何，通神明。","漢有丁蘭，唐有師貞。"]', '诗', 'shi', '', NULL, '時人爲劉師貞語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e0437f-d1ea-444e-adae-a3f3a6bc914d', '俚語', '俚語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["騎虎者，勢不得下。"]', '["騎虎者，勢不得下。"]', '诗', 'shi', '', NULL, '俚語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ba709d-46ff-4afa-aba9-600112dc4db1', '人爲分香蓮語（題擬）', '人爲分香蓮語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一事南無，折却長鬚。"]', '["一事南無，折却长鬚。"]', '诗', 'shi', '', NULL, '人爲分香蓮語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee533a91-ca8e-4ac6-9757-4a7c6d453887', '宣州人爲弘農王語（題擬）', '宣州人爲弘農王語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["何獨後予，徯其來蘇。"]', '["何独後予，徯其来蘇。"]', '诗', 'shi', '', NULL, '宣州人爲弘農王語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5209b0-0081-448b-bf77-a19f95f7fbb2', '崔淙引俚語', '崔淙引俚語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["川壅則潰，月盈則匡，善敗由己，吉凶何嘗。","（見《全唐文》卷四五九崔淙《登姑蘇臺賦》引）。"]', '["川壅則潰，月盈則匡，善敗由己，吉凶何嘗。","（见《全唐文》卷四五九崔淙《登姑蘇台賦》引）。"]', '诗', 'shi', '', NULL, '崔淙引俚語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('055dc8fc-22dc-4db9-919b-f97e535deb56', '丹州俗語', '丹州俗語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["丹州白室，胡頭漢舌。"]', '["丹州白室，胡头漢舌。"]', '诗', 'shi', '', NULL, '丹州俗語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d28376-c404-4219-b530-b1cc81069ed4', '戶牖俗語（題擬）', '戶牖俗語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["二十三，日正南。","二十五，日當戶。","（見《國史補》卷中）。"]', '["二十三，日正南。","二十五，日當戶。","（见《国史補》卷中）。"]', '诗', 'shi', '', NULL, '戶牖俗語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c37f43-aff4-4783-a385-8ae304e058cb', '金榆山土人言（題擬）', '金榆山土人言（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["金驢一鳴，天下太平。"]', '["金驢一鳴，天下太平。"]', '诗', 'shi', '', NULL, '金榆山土人言（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fbf603b-ff16-4682-86ca-adb8a389eef7', '俗語', '俗語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["王母甘桃，食之解勞。","（見前書卷十）。"]', '["王母甘桃，食之解勞。","（见前书卷十）。"]', '诗', 'shi', '', NULL, '俗語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d00d5c-5b9b-476c-a9ca-3438c460c4d1', '時人爲沈警語', '时人爲沈警語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["玄機在席，顛倒賓客。"]', '["玄機在席，顛倒賓客。"]', '诗', 'shi', '', NULL, '時人爲沈警語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b39ea59-9525-453f-a3c3-89df5e39f635', '蜀人爲南詔語', '蜀人爲南詔語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["西戎尚可，南蠻殘我。","（見《新唐書》卷二一五引）。"]', '["西戎尚可，南蠻殘我。","（见《新唐书》卷二一五引）。"]', '诗', 'shi', '', NULL, '蜀人爲南詔語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e484c9-8b09-41d8-8000-7317e83578e1', '乾符中人稱蔣凝語', '乾符中人稱蔣凝語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["臼頭花鈿滿面，不若徐妃增妝。","（見《唐摭言》卷十。","《釵小志》作諺）。"]', '["臼头花鈿满面，不若徐妃增妝。","（见《唐摭言》卷十。","《釵小志》作諺）。"]', '诗', 'shi', '', NULL, '乾符中人稱蔣凝語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a841a856-8d16-4bc7-9939-afd567c93e37', '唐時人爲秘書省太常寺官語（題從《古謠諺》卷六七）', '唐时人爲秘书省太常寺官語（題從《古謠諺》卷六七）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["正字校書，詠詩騎驢。","奉禮太祝，輕裘食肉。","（見《翰苑新書前集》卷二十四引《雍洛靈異記》）。"]', '["正字校书，詠诗騎驢。","奉禮太祝，轻裘食肉。","（见《翰苑新书前集》卷二十四引《雍洛靈異記》）。"]', '诗', 'shi', '', NULL, '唐時人爲秘書省太常寺官語（題從《古謠諺》卷六七） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05765325-1d9b-4d5e-939c-51ab4db42f08', '風流箭語', '风流箭語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["風流箭，風流人人願。","（見《說郛》卷六一引《清異錄》）（〖1〗《清異錄》：「寶曆中，帝造紙箭，竹皮弓紙間密貯龍麝末香。","每宮嬪羣聚，帝躬射之，中者濃香，觸體了無痛楚，名風流箭。","爲之語曰〖略〗。","」）。"]', '["风流箭，风流人人願。","（见《说郛》卷六一引《清異錄》）（〖1〗《清異錄》：「寶曆中，帝造紙箭，竹皮弓紙间密貯龙麝末香。","每宮嬪羣聚，帝躬射之，中者濃香，觸體了無痛楚，名风流箭。","爲之語曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '風流箭語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69b95491-a064-413c-8151-7b57533096fc', '韓鄂引俗語 一', '韓鄂引俗語 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一年計樹之以穀，十年計樹之以木。"]', '["一年計樹之以穀，十年計樹之以木。"]', '诗', 'shi', '', NULL, '韓鄂引俗語 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec725194-c398-4386-97e6-82c23c153dae', '韓鄂引俗語 二', '韓鄂引俗語 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一日之之計在一晨，一年之計在一春。"]', '["一日之之計在一晨，一年之計在一春。"]', '诗', 'shi', '', NULL, '韓鄂引俗語 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddcf30b9-68bb-4abf-80fa-dd32bf567b3b', '韓鄂引俗語 三', '韓鄂引俗語 三', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["以時及澤爲上策。","（均見《四時纂要》卷一）。"]', '["以时及澤爲上策。","（均见《四时纂要》卷一）。"]', '诗', 'shi', '', NULL, '韓鄂引俗語 三 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e69bbe65-095c-4ddb-b75b-238bf87282dc', '韓鄂引俗語 四', '韓鄂引俗語 四', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["八月雨班闌，高低盡可憐。","（同前卷三）。"]', '["八月雨班闌，高低尽可怜。","（同前卷三）。"]', '诗', 'shi', '', NULL, '韓鄂引俗語 四 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737198b5-ef01-40ad-ba55-409ebe4c7807', '人爲太白山橫雲語（題擬）', '人爲太白山橫云語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["南山瀑布，非朝則暮。","（見宋敏求《長安志》卷十四）。"]', '["南山瀑布，非朝則暮。","（见宋敏求《长安志》卷十四）。"]', '诗', 'shi', '', NULL, '人爲太白山橫雲語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34db2fa2-e221-4e25-b4e7-c4a478e34b2a', '清豐故老傳語（題擬）', '清豐故老傳語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["金堤頭，上有秦女樓。","（見《太平寰宇記》卷五七）。"]', '["金堤头，上有秦女楼。","（见《太平寰宇記》卷五七）。"]', '诗', 'shi', '', NULL, '清豐故老傳語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a0376d-be53-49f7-8c2c-9792baa6e71f', '人爲吳道子曹仲達語', '人爲吳道子曹仲達語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["吳帶當風，曹衣出水。","（見《圖畫見聞志》卷一）。"]', '["吳带當风，曹衣出水。","（见《圖畫见闻志》卷一）。"]', '诗', 'shi', '', NULL, '人爲吳道子曹仲達語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7cadc7-c876-4f2a-9d96-f8b7af16a5ea', '梁時人爲吳道子劉彦齐语（题拟）', '梁时人爲吳道子劉彦齐语（题拟）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["唐朝吳道子手，梁朝劉彥齊眼。","（《圖書見聞志》卷五）。"]', '["唐朝吳道子手，梁朝劉彥齊眼。","（《圖书见闻志》卷五）。"]', '诗', 'shi', '', NULL, '梁時人爲吳道子劉彦齐语（题拟） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c5a9849-8cbd-444a-8cc9-8dbadbd3158e', '揚州人爲彭玕語（題從《古謠諺》卷二四）', '揚州人爲彭玕語（題從《古謠諺》卷二四）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["十金易一筆，百金易一篇。","（《十國春秋》卷七三《彭玕傳》）。"]', '["十金易一笔，百金易一篇。","（《十国春秋》卷七三《彭玕傳》）。"]', '诗', 'shi', '', NULL, '揚州人爲彭玕語（題從《古謠諺》卷二四） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b507b7-cba9-4973-9bb6-9756bf4c3510', '蘇州耆舊語（題擬）', '蘇州耆旧語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["燕山石鼓，鳴則有兵。","（《太平寰宇記》卷七十）。"]', '["燕山石鼓，鳴則有兵。","（《太平寰宇記》卷七十）。"]', '诗', 'shi', '', NULL, '蘇州耆舊語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('791231bd-14bb-4a24-8b0e-658ab52f9ac0', '南溪故老傳語（題擬）', '南溪故老傳語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["東石從西，乞子將歸。","（《太平寰宇記》卷七九）。"]', '["东石從西，乞子將归。","（《太平寰宇記》卷七九）。"]', '诗', 'shi', '', NULL, '南溪故老傳語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1559318-67a5-488e-a8d7-24e5eaf66cbb', '贊寧引語', '贊寧引語', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["利不百，不變格。","（《宋高僧傳》卷十《唐新吳百丈山懷海傳》）。"]', '["利不百，不变格。","（《宋高僧傳》卷十《唐新吳百丈山懷海傳》）。"]', '诗', 'shi', '', NULL, '贊寧引語 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('582f4f2b-d970-48ce-a194-db56b1640a01', '宋城民爲祝天貺和甄語（題擬）', '宋城民爲祝天貺和甄語（題擬）', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["去了裹頭冰，却得一段著脚琉璃。","（《說郛》卷六一引《清異錄》）。"]', '["去了裹头冰，却得一段著脚琉璃。","（《说郛》卷六一引《清異錄》）。"]', '诗', 'shi', '', NULL, '宋城民爲祝天貺和甄語（題擬） 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b975b7-91ae-4340-9ba9-c5c31640c86b', '《灌畦暇語》引常言', '《灌畦暇語》引常言', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["一作一止，知人表裏。","（《灌畦暇語》）。"]', '["一作一止，知人表裏。","（《灌畦暇語》）。"]', '诗', 'shi', '', NULL, '《灌畦暇語》引常言 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5a4d249-8176-4d51-8789-c8829e8eb9c7', '《酉陽雜俎》引語 一', '《酉陽杂俎》引語 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["買魚得鱮，不如食茹。"]', '["買鱼得鱮，不如食茹。"]', '诗', 'shi', '', NULL, '《酉陽雜俎》引語 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc9b730-759e-490c-aa06-6a767b02d439', '《酉陽雜俎》引語 二', '《酉陽杂俎》引語 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["寧去累世宅，不去{制/多}魚額。"]', '["寧去累世宅，不去{制/多}鱼額。"]', '诗', 'shi', '', NULL, '《酉陽雜俎》引語 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4010ac7b-65b2-46b8-a7cc-ce3d3a83fcbb', '《酉陽雜俎》引語 三', '《酉陽杂俎》引語 三', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["洛鯉伊魴，貴於牛羊。"]', '["洛鯉伊魴，貴於牛羊。"]', '诗', 'shi', '', NULL, '《酉陽雜俎》引語 三 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aacd7e86-d55b-4cf9-bf7d-acd216a95ad6', '《酉陽雜俎》引語 四', '《酉陽杂俎》引語 四', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["得合瀾蠾，雖不足豪，亦足以高。"]', '["得合瀾蠾，雖不足豪，亦足以高。"]', '诗', 'shi', '', NULL, '《酉陽雜俎》引語 四 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0493ffca-f66f-4124-a27b-38e735561c31', '《酉陽雜俎》引語 五', '《酉陽杂俎》引語 五', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["檳榔扶留，可以忘憂。"]', '["檳榔扶留，可以忘憂。"]', '诗', 'shi', '', NULL, '《酉陽雜俎》引語 五 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea86983f-c8f8-4d69-85d5-33a6f2f62708', '《酉陽雜俎》引語 六', '《酉陽杂俎》引語 六', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["白馬甜榴，一實直牛。"]', '["白马甜榴，一實直牛。"]', '诗', 'shi', '', NULL, '《酉陽雜俎》引語 六 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0200d5e-174e-44c2-ab8b-768d9cecf3df', '《酉陽雜俎》引語 七', '《酉陽杂俎》引語 七', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["草木暉暉，蒼黃亂飛。","（均見《酉陽雜俎前集》卷十六《廣動植》）。"]', '["草木暉暉，蒼黄亂飞。","（均见《酉陽杂俎前集》卷十六《廣动植》）。"]', '诗', 'shi', '', NULL, '《酉陽雜俎》引語 七 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d45b422-6c6b-4a9c-ae0b-46c87b937905', '舉場舊話 一', '舉場旧話 一', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["聞多見少，跡靜心勤。","（省閑遊，事知己也）卷頭有眼，（投謁必其地也）肚裏沒嗔。","（得失算命，羣居用和）。"]', '["闻多见少，跡静心勤。","（省闲游，事知己也）卷头有眼，（投謁必其地也）肚裏沒嗔。","（得失算命，羣居用和）。"]', '诗', 'shi', '', NULL, '舉場舊話 一 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658345b1-0107-44f9-9f46-fc9690dfcc78', '舉場舊話 二', '舉場旧話 二', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["貌謹氣和，見面少，聞名多。","（古人有言。","見多成醜之謂也。","凡後進遊歷前達之門，或慮進趨揖讓，偶有蹶失，則雖有烜赫之文，終負生疎之謂。","故文藝既至，第要投謁及時，不必孜孜求見也。","如其深知己下歲寒之契，師友則不然也）。"]', '["貌謹氣和，见面少，闻名多。","（古人有言。","见多成醜之謂也。","凡後進游歷前達之门，或慮進趨揖讓，偶有蹶失，則雖有烜赫之文，終負生疎之謂。","故文藝既至，第要投謁及时，不必孜孜求见也。","如其深知己下歲寒之契，師友則不然也）。"]', '诗', 'shi', '', NULL, '舉場舊話 二 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbd0219-d73e-4311-bf47-0ddb456254a5', '舉場舊話 三', '舉場旧話 三', 'a002968d-fb03-407c-9a25-eae63a182674', '唐', '["上等舉人，應同人舉。","（推公共也）中等舉人，應丞郎舉。","（計通塞也）下等舉人，應宰相舉。","（均見《唐摭言》卷十五。","此承湯華泉同志見告）。"]', '["上等舉人，應同人舉。","（推公共也）中等舉人，應丞郎舉。","（計通塞也）下等舉人，應宰相舉。","（均见《唐摭言》卷十五。","此承湯华泉同志见告）。"]', '诗', 'shi', '', NULL, '舉場舊話 三 佚名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8ab068-999b-4820-b930-4d7ea359e948', '四相詩 生相', '四相诗 生相', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["識託浮泡起，生從愛欲來。","昔時曾長大，今日復嬰孩。","星眼隨人轉，朱脣向乳開。","爲迷真法性，還却受輪迴。"]', '["識託浮泡起，生從愛欲来。","昔时曾长大，今日复嬰孩。","星眼隨人轉，朱脣向乳开。","爲迷真法性，還却受輪迴。"]', '诗', 'shi', '', NULL, '四相詩 生相 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('971c3759-9297-4ef8-a2ec-34fe59b4d9c0', '老相', '老相', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["覽鏡容顏改，登階氣力衰。","咄哉今已老，趨拜禮還虧。","身似臨崖樹，心如念水龜。","尚猶躭有漏，不肯學無爲。"]', '["覽镜容顏改，登階氣力衰。","咄哉今已老，趨拜禮還虧。","身似臨崖樹，心如念水龟。","尚猶躭有漏，不肯学無爲。"]', '诗', 'shi', '', NULL, '老相 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e900e6-52b1-4122-a134-5fae76753597', '病相', '病相', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["忽染沈疴疾，因成臥病身。","妻兒愁不語，朋友厭相親。","楚痛抽千脈，呻吟徹四鄰。","不知前路險，猶向恣貪嗔。","。"]', '["忽染沈疴疾，因成臥病身。","妻兒愁不語，朋友厭相親。","楚痛抽千脈，呻吟徹四鄰。","不知前路險，猶向恣貪嗔。","。"]', '诗', 'shi', '', NULL, '病相 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('677b9072-4069-40b8-b85d-04a420715365', '死相', '死相', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["精魄辭生路，遊魂入死關。","只聞千萬去，不見一人還。","寶馬空嘶立，庭花永絕攀。","早求無上道，應免四方山。"]', '["精魄辞生路，游魂入死关。","只闻千万去，不见一人還。","寶马空嘶立，庭花永絕攀。","早求無上道，應免四方山。"]', '诗', 'shi', '', NULL, '死相 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3117c38b-53e1-4fff-81f1-2a125fd83a2b', '頌 一', '頌 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["遍參四大海，觀尋五陰山。","如來行道處，靈智甚清閑。","實殿明珠曜，花座美玉鮮。","心王明教法，敷揚般若蓮。","浄土菩提子，蓋得天中天。"]', '["遍參四大海，观尋五陰山。","如来行道处，靈智甚清闲。","實殿明珠曜，花座美玉鲜。","心王明教法，敷揚般若蓮。","浄土菩提子，蓋得天中天。"]', '诗', 'shi', '', NULL, '頌 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('789febea-62fd-4b95-88b5-d59b74526604', '頌 二', '頌 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["觀此色身中，心王般若空。","聖智安居處，凡夫路不同。","出入無門戶，觀尋不見蹤。","大體寬無際，小心塵不容。","欲得登彼岸，高張智慧篷。"]', '["观此色身中，心王般若空。","聖智安居处，凡夫路不同。","出入無门戶，观尋不见蹤。","大體寬無際，小心塵不容。","欲得登彼岸，高張智慧篷。"]', '诗', 'shi', '', NULL, '頌 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a8e029f-6c89-404f-8ce7-bb404d47cb6c', '頌 三', '頌 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["清淨明珠戒，莊嚴佛道塲。","身作如來相，心爲般若王。","願早登蓮座，口放大圓光。","廣照無邊界，爲佛作橋梁。","開大毘尼藏，名傳戒定香。"]', '["清淨明珠戒，莊嚴佛道塲。","身作如来相，心爲般若王。","願早登蓮座，口放大圓光。","廣照無邊界，爲佛作橋梁。","开大毘尼藏，名傳戒定香。"]', '诗', 'shi', '', NULL, '頌 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959c1c55-aedf-447d-bec5-ab057557ac57', '頌 四', '頌 四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["觀達無生智，空中誰往來？永超三界獄，不染四魔胎。","遊戲蓮華上，安居法性臺。","天上悉瞻仰，冥空讚善哉！有緣逢廣化，般若妙門開。"]', '["观達無生智，空中誰往来？永超三界獄，不染四魔胎。","游戲蓮华上，安居法性台。","天上悉瞻仰，冥空讚善哉！有緣逢廣化，般若妙门开。"]', '诗', 'shi', '', NULL, '頌 四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14001c68-fb08-4944-af48-97d2af35e974', '頌 五', '頌 五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["夜夜抱佛眠，朝朝還共起。","行住鎮相隨，坐臥同居止。","分毫不相離，如身影相似。","欲知佛何在，只這語聲是。"]', '["夜夜抱佛眠，朝朝還共起。","行住鎮相隨，坐臥同居止。","分毫不相離，如身影相似。","欲知佛何在，只這語声是。"]', '诗', 'shi', '', NULL, '頌 五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5070a276-85b5-4b16-b4ac-0d2d3eb82208', '頌 六', '頌 六', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["寂是法王根，動是法王苗。","湼槃既不遠，常住亦非遙。","迴心名浄土，煩惱應時消。","欲過三塗海，勤修六度橋。","定當成正覺，喻若待來潮。","。"]', '["寂是法王根，动是法王苗。","湼槃既不远，常住亦非遙。","迴心名浄土，煩惱應时消。","欲過三塗海，勤修六度橋。","定當成正覺，喻若待来潮。","。"]', '诗', 'shi', '', NULL, '頌 六 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('897ea8ec-430b-476b-87c3-8875c4a67849', '頌 七', '頌 七', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["伏藏不離體，珠在內身中。","但向心邊會，莫遠外於空。"]', '["伏藏不離體，珠在內身中。","但向心邊會，莫远外於空。"]', '诗', 'shi', '', NULL, '頌 七 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f7e4b8-aa1d-49db-ad56-db2e01e7279e', '頌 八', '頌 八', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["萬類同真性，千般體一如。","若人解此法，何用苦尋渠。","四生同一體，六趣會歸余。","無明即是佛，煩惱不須除。"]', '["万類同真性，千般體一如。","若人解此法，何用苦尋渠。","四生同一體，六趣會归余。","無明即是佛，煩惱不須除。"]', '诗', 'shi', '', NULL, '頌 八 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f39105-2dac-4627-a46b-c0bde3dd040b', '貪嗔癡 一', '貪嗔癡 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["不須貪，看取遊魚戲碧潭。","只是愛他鈎下餌，一條線向口中含。"]', '["不須貪，看取游鱼戲碧潭。","只是愛他鈎下餌，一條線向口中含。"]', '诗', 'shi', '', NULL, '貪嗔癡 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e8c4738-2eba-4035-90c6-d248da1d01ec', '貪嗔癡 二', '貪嗔癡 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["不須瞋，瞋則能招地獄因。","但將定力降風火，便是端嚴紫磨身。"]', '["不須瞋，瞋則能招地獄因。","但將定力降风火，便是端嚴紫磨身。"]', '诗', 'shi', '', NULL, '貪嗔癡 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6835d01-da7e-4eb6-9ef5-e5143bdc5fdc', '貪嗔癡 三', '貪嗔癡 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["不須癡，癡被無明六賊欺。","惡業自身心所造，愚迷披却畜生皮。"]', '["不須癡，癡被無明六賊欺。","惡業自身心所造，愚迷披却畜生皮。"]', '诗', 'shi', '', NULL, '貪嗔癡 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b956d58b-8c35-429a-a6ac-33e0d7104bf4', '十勸 一', '十勸 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君一，專心常念波羅密。","勤修六度向菩提，五濁三塗自然出。"]', '["勸君一，專心常念波羅密。","勤修六度向菩提，五濁三塗自然出。"]', '诗', 'shi', '', NULL, '十勸 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cedc8460-9e71-4547-8b86-f863314eaf13', '十勸 二', '十勸 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君二，夫人處世莫求利。","縱然求得蹔時間，須臾不久歸蒿里。"]', '["勸君二，夫人处世莫求利。","縱然求得蹔时间，須臾不久归蒿里。"]', '诗', 'shi', '', NULL, '十勸 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdbb88d-75cb-4423-b09e-684690a21bed', '十勸 三', '十勸 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君三，人身難得大須慙。","晝夜六時常念佛，勤修三寶向伽藍。"]', '["勸君三，人身难得大須慙。","晝夜六时常念佛，勤修三寶向伽藍。"]', '诗', 'shi', '', NULL, '十勸 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13c48f5f-6ce0-4e69-a670-7143499c8a10', '十勸 四', '十勸 四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君四，努力經營修善事。","莫言少壯好光容，未委前程是何處。"]', '["勸君四，努力經營修善事。","莫言少壯好光容，未委前程是何处。"]', '诗', 'shi', '', NULL, '十勸 四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee138d36-7810-4498-b739-87d749858d01', '十勸 五', '十勸 五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君五，尋思地獄真成苦。","眼前富貴逞容儀，須臾不久還歸土。"]', '["勸君五，尋思地獄真成苦。","眼前富貴逞容儀，須臾不久還归土。"]', '诗', 'shi', '', NULL, '十勸 五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fad426e-e26e-4182-8f37-4d9557926aae', '十勸 六', '十勸 六', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君六，第一莫喫衆生肉。","若非菩薩化身來，便是生前親眷屬。"]', '["勸君六，第一莫喫衆生肉。","若非菩薩化身来，便是生前親眷屬。"]', '诗', 'shi', '', NULL, '十勸 六 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e852543-d049-4461-ab35-83561a2f0610', '十勸 七', '十勸 七', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君七，萬事無過須的實。","朝三暮四不爲人，此理安身終不吉。"]', '["勸君七，万事無過須的實。","朝三暮四不爲人，此理安身終不吉。"]', '诗', 'shi', '', NULL, '十勸 七 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde694c1-c976-4ef9-ba74-b2cc2f1ec186', '十勸 八', '十勸 八', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君八，喫肉之人真羅剎。","今生若也殺他身，來生還被他人殺。","。"]', '["勸君八，喫肉之人真羅剎。","今生若也殺他身，来生還被他人殺。","。"]', '诗', 'shi', '', NULL, '十勸 八 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceebdb1e-6ad9-46a6-b910-372bd9110b98', '十勸 九', '十勸 九', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君九，天堂地獄分明有。","莫將酒肉勸僧人，五百生中無脚手。"]', '["勸君九，天堂地獄分明有。","莫將酒肉勸僧人，五百生中無脚手。"]', '诗', 'shi', '', NULL, '十勸 九 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4eb1ffe-f046-47bd-b943-c1da618d254b', '十勸 十', '十勸 十', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["勸君十，相勸修行須在急。","一朝命盡入黃泉，父娘妻子徒勞泣。"]', '["勸君十，相勸修行須在急。","一朝命尽入黄泉，父娘妻子徒勞泣。"]', '诗', 'shi', '', NULL, '十勸 十 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3831c0c-b3f1-4512-a3cd-c01cd94c6353', '頌二首 一', '頌二首 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["空手把鋤頭，步行騎水牛。","人從橋上過，橋流水不流。"]', '["空手把鋤头，步行騎水牛。","人從橋上過，橋流水不流。"]', '诗', 'shi', '', NULL, '頌二首 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('886a5736-c2db-4287-a54b-a7bca43e93e0', '頌二首 二', '頌二首 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["有物先天地，無形本寂寥。","能爲萬象主，不逐四時彫。","（延壽《心賦注》引此首）。"]', '["有物先天地，無形本寂寥。","能爲万象主，不逐四时彫。","（延壽《心賦注》引此首）。"]', '诗', 'shi', '', NULL, '頌二首 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d65c392-986d-482c-8950-35c89bce536c', '還源詩十二章 一', '還源诗十二章 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，生死湼槃齊。","由心不平等，法性有高低。"]', '["還源去，生死湼槃齊。","由心不平等，法性有高低。"]', '诗', 'shi', '', NULL, '還源詩十二章 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e3fea91-b53f-4200-9aa9-dfd7ed570d06', '還源詩十二章 二', '還源诗十二章 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，說易運心難。","般若無形相，教君若爲觀。"]', '["還源去，说易運心难。","般若無形相，教君若爲观。"]', '诗', 'shi', '', NULL, '還源詩十二章 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('558230a8-ade4-45af-9c14-17969ab75aaa', '還源詩十二章 三', '還源诗十二章 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，欲求般若易。","但息是非心，自然成大智。"]', '["還源去，欲求般若易。","但息是非心，自然成大智。"]', '诗', 'shi', '', NULL, '還源詩十二章 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb60a701-2d8d-48bd-8786-6fb5ed9c6312', '還源詩十二章 四', '還源诗十二章 四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還溴去，觸處可幽棲。","湼槃生死是，煩惱即菩提。"]', '["還溴去，觸处可幽棲。","湼槃生死是，煩惱即菩提。"]', '诗', 'shi', '', NULL, '還源詩十二章 四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79eb6040-0e2b-4d6d-bc59-1a71963a6352', '還源詩十二章 五', '還源诗十二章 五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，依理莫隨情。","法性無增減，妄說有虧盈。"]', '["還源去，依理莫隨情。","法性無增減，妄说有虧盈。"]', '诗', 'shi', '', NULL, '還源詩十二章 五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6e2fa0b-6cfe-4a3e-b4f1-ae4844d610cb', '還源詩十二章 六', '還源诗十二章 六', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，何須更遠尋。","欲求真解脫，端坐自觀心。"]', '["還源去，何須更远尋。","欲求真解脫，端坐自观心。"]', '诗', 'shi', '', NULL, '還源詩十二章 六 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125741b1-60dc-4901-a31f-c3eaf6b5da42', '還源詩十二章 七', '還源诗十二章 七', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，心性不思議。","志小無爲大，芥子納須彌。"]', '["還源去，心性不思議。","志小無爲大，芥子納須彌。"]', '诗', 'shi', '', NULL, '還源詩十二章 七 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('539ed122-d457-4e88-8b59-df6634074c70', '還源詩十二章 八', '還源诗十二章 八', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，解脫無邊際。","和光與物同，如空不染世。"]', '["還源去，解脫無邊際。","和光與物同，如空不染世。"]', '诗', 'shi', '', NULL, '還源詩十二章 八 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca374e33-3165-46d9-ac0d-750d103b19f5', '還源詩十二章 九', '還源诗十二章 九', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，何須次第求。","法性無前後，一念一時修。","（此首見《宗鏡錄》卷十四）。"]', '["還源去，何須次第求。","法性無前後，一念一时修。","（此首见《宗镜錄》卷十四）。"]', '诗', 'shi', '', NULL, '還源詩十二章 九 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc425ace-d76a-4895-8445-54c6555b26a5', '還源詩十二章 十', '還源诗十二章 十', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，心性不沈浮。","安住三（《宗鏡錄》卷二七作「王」）三昧，萬行悉圓收。","。"]', '["還源去，心性不沈浮。","安住三（《宗镜錄》卷二七作「王」）三昧，万行悉圓收。","。"]', '诗', 'shi', '', NULL, '還源詩十二章 十 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b1b86c2-b96d-4d0f-9be6-6e688e843b66', '還源詩十二章 十一', '還源诗十二章 十一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，生死本紛淪。","橫計虛爲實，六情常自昏。"]', '["還源去，生死本紛淪。","橫計虛爲實，六情常自昏。"]', '诗', 'shi', '', NULL, '還源詩十二章 十一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d96093-9997-4257-9e63-af289709ee0c', '還源詩十二章 十二', '還源诗十二章 十二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["還源去，般若酒澄清。","能治煩惱病，自飲勸衆生。"]', '["還源去，般若酒澄清。","能治煩惱病，自饮勸衆生。"]', '诗', 'shi', '', NULL, '還源詩十二章 十二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1047d611-f354-4533-bf3c-e5e008ae6007', '浮漚歌', '浮漚歌', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見驟雨近着庭際流，水上隨生無數漚。","一滴初成一滴破，幾回銷盡幾回浮。","浮漚聚散無窮已，大小殊形色相似。","有時忽起名浮漚，銷盡還同本來水。","浮漚自有還自無，象空象實總名虛。","究竟還同幻化影，愚人喚作半邊珠。","此時感歎閑居士，一見浮漚悟生死。","皇皇人世總名虛，蹔借浮漚以相比。","念念人間多盛衰，逝水東注永無期。"]', '["君不见驟雨近着庭際流，水上隨生無數漚。","一滴初成一滴破，幾回銷尽幾回浮。","浮漚聚散無窮已，大小殊形色相似。","有时忽起名浮漚，銷尽還同本来水。","浮漚自有還自無，象空象實總名虛。","究竟還同幻化影，愚人喚作半邊珠。","此时感歎闲居士，一见浮漚悟生死。","皇皇人世總名虛，蹔借浮漚以相比。","念念人间多盛衰，逝水东注永無期。"]', '诗', 'shi', '', NULL, '浮漚歌 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c45d47-7819-439a-bbd1-479ce71d0760', '獨自詩二十章 一', '独自诗二十章 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自山，茅茨草屋安。","熊羆撩人戲，飛鳥共來飱。"]', '["独自山，茅茨草屋安。","熊羆撩人戲，飞鸟共来飱。"]', '诗', 'shi', '', NULL, '獨自詩二十章 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08416fb9-40df-4689-a99a-5e477eba75f7', '獨自詩二十章 二', '独自诗二十章 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自居，何意此勤劬。","翹心尋本性，節志服真如。"]', '["独自居，何意此勤劬。","翹心尋本性，節志服真如。"]', '诗', 'shi', '', NULL, '獨自詩二十章 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef2bfa7f-43ee-495e-9e04-ff1826f0dd86', '獨自詩二十章 三', '独自诗二十章 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自眠，寂寞好思玄。","休息攀緣境，不著有無邊。"]', '["独自眠，寂寞好思玄。","休息攀緣境，不著有無邊。"]', '诗', 'shi', '', NULL, '獨自詩二十章 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62f2742b-e9d4-408b-96a4-d910250beed9', '獨自詩二十章 四', '独自诗二十章 四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自坐，靜思觀無我。","調直箇身心，慈悲成薩埵。"]', '["独自坐，静思观無我。","調直箇身心，慈悲成薩埵。"]', '诗', 'shi', '', NULL, '獨自詩二十章 四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb4d180-761f-48b6-aec3-06dbd3f0cccf', '獨自詩二十章 五', '独自诗二十章 五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自處，本誓如應語。","示道在經中，扣破無明主。"]', '["独自处，本誓如應語。","示道在經中，扣破無明主。"]', '诗', 'shi', '', NULL, '獨自詩二十章 五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57233cb5-3472-4da5-9588-bf55be512d89', '獨自詩二十章 六', '独自诗二十章 六', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自行，見色恰如盲。","輕軀同類化，蠕動未曾驚。"]', '["独自行，见色恰如盲。","轻軀同類化，蠕动未曾驚。"]', '诗', 'shi', '', NULL, '獨自詩二十章 六 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f04ac5c-13ce-4606-b5ed-db2ed38c1e3a', '獨自詩二十章 七', '独自诗二十章 七', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自戲，問我心中有何爲？","若見無記在心中，急斷令還般若義。"]', '["独自戲，问我心中有何爲？","若见無記在心中，急斷令還般若義。"]', '诗', 'shi', '', NULL, '獨自詩二十章 七 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706acacb-4996-4ea4-bc4b-5bba140da979', '獨自詩二十章 八', '独自诗二十章 八', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自往，觸處隨緣皆妄想。","妄想心內富馳求，即此馳求亦非往。","。"]', '["独自往，觸处隨緣皆妄想。","妄想心內富驰求，即此驰求亦非往。","。"]', '诗', 'shi', '', NULL, '獨自詩二十章 八 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa94de8-ab68-4358-963c-f754b1df8eca', '獨自詩二十章 九', '独自诗二十章 九', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自歸，登山度嶺何所依。","比至所依無定實，熟觀此境竟何為。"]', '["独自归，登山度嶺何所依。","比至所依無定實，熟观此境竟何為。"]', '诗', 'shi', '', NULL, '獨自詩二十章 九 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e60deebd-2a89-46e5-913c-a376db1b4784', '獨自詩二十章 十', '独自诗二十章 十', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自作，問我心中何所著？推檢四運併無生，千端萬緒何能縛？"]', '["独自作，问我心中何所著？推檢四運併無生，千端万緒何能縛？"]', '诗', 'shi', '', NULL, '獨自詩二十章 十 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1127e5df-3f80-42e0-9945-4b0f62123779', '獨自詩二十章 十一', '独自诗二十章 十一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自語。問我心中何所取？","照了巧說並皆空，咽喉唇舌誰為主。"]', '["独自語。问我心中何所取？","照了巧说並皆空，咽喉唇舌誰為主。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69bace86-eecb-4051-8d18-1df196947947', '獨自詩二十章 十二', '独自诗二十章 十二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自精，其實離聲名。","三觀一心融萬品，荊蕀叢林何處生？"]', '["独自精，其實離声名。","三观一心融万品，荊蕀叢林何处生？"]', '诗', 'shi', '', NULL, '獨自詩二十章 十二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d65e85-d7ec-4b28-aec7-d4bec6976451', '獨自詩二十章 十三', '独自诗二十章 十三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自美，迢迢棄朝市。","追昔本願證無生，不得無生終不止。"]', '["独自美，迢迢棄朝市。","追昔本願證無生，不得無生終不止。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6660fac1-4747-4528-ad1a-8d08c4cea681', '獨自詩二十章 十四', '独自诗二十章 十四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自佳，禪味朝飱不同蝦。","弊此摶食如應與，假借五陰以爲家。"]', '["独自佳，禪味朝飱不同蝦。","弊此摶食如應與，假借五陰以爲家。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a61fd56-01cd-4879-ab29-37a23b534246', '獨自詩二十章 十五', '独自诗二十章 十五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自樂，但欲求無學。","急斷三界繩，得免泥犂惡。"]', '["独自乐，但欲求無学。","急斷三界繩，得免泥犂惡。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a68159d7-08fa-472f-a30f-9d650639bafd', '獨自詩二十章 十六', '独自诗二十章 十六', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自好，決求菩薩道。","萬行爲衆生，未取泥洹寶。"]', '["独自好，決求菩薩道。","万行爲衆生，未取泥洹寶。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十六 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721cf007-a113-4f74-a0af-9dfb830f5aa0', '獨自詩二十章 十七', '独自诗二十章 十七', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自歡，試取世緣看。","捉此無常境，一理向心觀。"]', '["独自歡，試取世緣看。","捉此無常境，一理向心观。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十七 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a4be5f7-ec29-4b99-89f3-c904ecfd3ff2', '獨自詩二十章 十八', '独自诗二十章 十八', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自奇，正是學無爲。","迴首多許念，運向湼槃池。"]', '["独自奇，正是学無爲。","迴首多許念，運向湼槃池。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十八 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a8db7ba-686b-474e-aace-5f5b6c411fbb', '獨自詩二十章 十九', '独自诗二十章 十九', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自足，願心無限局。","怨親法界語圓真，始得應身化羣育。"]', '["独自足，願心無限局。","怨親法界語圓真，始得應身化羣育。"]', '诗', 'shi', '', NULL, '獨自詩二十章 十九 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d023ae12-3540-42cd-ab8e-0c98c765a34e', '獨自詩二十章 二十', '独自诗二十章 二十', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["獨自宿，意裏心儲蓄。","爲作良友繫衣珠，歷劫彌生根會熟。"]', '["独自宿，意裏心儲蓄。","爲作良友繫衣珠，歷劫彌生根會熟。"]', '诗', 'shi', '', NULL, '獨自詩二十章 二十 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9502ffc2-3fc8-4880-a3b7-ff8b9ae6123f', '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 一', '爾时大士語諸弟子晝夜思維观察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章词曰 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["一更始，心香遍界起。","敬禮無上尊，心心已無已。"]', '["一更始，心香遍界起。","敬禮無上尊，心心已無已。"]', '诗', 'shi', '', NULL, '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b21aa4b-9300-4c1f-b5e6-6ca1de3ba4a1', '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 二', '爾时大士語諸弟子晝夜思維观察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章词曰 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["二更至，跏趺靜禪思。","通達無彼我，真如一不二。"]', '["二更至，跏趺静禪思。","通達無彼我，真如一不二。"]', '诗', 'shi', '', NULL, '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599c27ce-f091-4948-bcbe-1b2d687be92b', '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 三', '爾时大士語諸弟子晝夜思維观察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章词曰 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["三更中，觀法空不空。","無起無生滅，體一真如同。"]', '["三更中，观法空不空。","無起無生滅，體一真如同。"]', '诗', 'shi', '', NULL, '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7bb867a-0c68-4dde-8f14-3c6bbd941109', '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 四', '爾时大士語諸弟子晝夜思維观察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章词曰 四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["四更前，觀法緣無緣。","真如四句絕，百非寧復煎。"]', '["四更前，观法緣無緣。","真如四句絕，百非寧复煎。"]', '诗', 'shi', '', NULL, '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1269120-c901-43a6-8ed8-e674cc08424d', '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 五', '爾时大士語諸弟子晝夜思維观察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章词曰 五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["五更初，稽首禮如如。","歸依無新故，不實亦不虛。"]', '["五更初，稽首禮如如。","归依無新故，不實亦不虛。"]', '诗', 'shi', '', NULL, '爾時大士語諸弟子晝夜思維觀察自心生而不生滅而不滅止息攀緣人法相寂是爲解脫乃作五章詞曰 五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e45de93d-7643-44ab-9344-88e445988952', '行路難二十篇（幷序） 第一章明心非斷常', '行路难二十篇（幷序） 第一章明心非斷常', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見自心非斷亦非常，普在諸方不入方。","亦復不依前後際，又復非圓非短長。","湛然無生亦無滅，非白非黑非青黃。","雖復念慮知諸法，而實不住念中央。","衆生入而無所入，雖取六境無所傷。","智者分明了知此，是故號曰法中王。","自悟知此非知法，因爾智慧等金剛。","不藉外緣資內府，戒定慧品自閑防。","安住普超三昧頂，憶想顛倒永消亡。","覺諸煩惱真如相，稱此空名爲道塲。","爲衆班宣演常教，如此妙義未曾彰。","行路難，路難微妙甚難行。","若以無知照知法，現前證得本無生。"]', '["君不见自心非斷亦非常，普在諸方不入方。","亦复不依前後際，又复非圓非短长。","湛然無生亦無滅，非白非黑非青黄。","雖复念慮知諸法，而實不住念中央。","衆生入而無所入，雖取六境無所傷。","智者分明了知此，是故號曰法中王。","自悟知此非知法，因爾智慧等金剛。","不藉外緣資內府，戒定慧品自闲防。","安住普超三昧頂，憶想顛倒永消亡。","覺諸煩惱真如相，稱此空名爲道塲。","爲衆班宣演常教，如此妙義未曾彰。","行路难，路难微妙甚难行。","若以無知照知法，現前證得本無生。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第一章明心非斷常 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91379edf-08ad-4922-8783-f752fbb560fd', '行路難二十篇（幷序） 第二章明真照無照', '行路难二十篇（幷序） 第二章明真照無照', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見真照分明性無照，通鑒坦蕩復無平。","安住無明知明照，了達明照之無明。","一心永斷於諸行，始復勤行於不行。","一心非心亦非一，無一無心行不生。","識心即是無生法，非離生法有無生。","若知諸緣性無起，隨心顛倒任縱橫。","解了空心無隔礙，世間言論不庸爭。","若復苦欲爭言論，方爲貪癡之所盲。","是故經說樂知見，五陰塵勞隨復生。","若能專心復本際，自得正道坦然平。","性正心平無有正，假設平正引羣生。","行路難，路難常居五陰山。","湼槃虛玄不爲寂，雖有生死獨清閑。"]', '["君不见真照分明性無照，通鑒坦蕩复無平。","安住無明知明照，了達明照之無明。","一心永斷於諸行，始复勤行於不行。","一心非心亦非一，無一無心行不生。","識心即是無生法，非離生法有無生。","若知諸緣性無起，隨心顛倒任縱橫。","解了空心無隔礙，世间言論不庸爭。","若复苦欲爭言論，方爲貪癡之所盲。","是故經说乐知见，五陰塵勞隨复生。","若能專心复本際，自得正道坦然平。","性正心平無有正，假設平正引羣生。","行路难，路难常居五陰山。","湼槃虛玄不爲寂，雖有生死独清闲。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第二章明真照無照 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27606767-0134-4c4c-a767-a67e068598ac', '行路難二十篇（幷序） 第三章明心相實相', '行路难二十篇（幷序） 第三章明心相實相', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見心相微細最奇精，非作非緣非色名。","雖復恬然非有相，若凡若聖己之靈。","此靈無形而常應，雖復常應實無形。","心性無來亦無去，緣慮流轉實無停。","正覺此之（《宗鏡錄》卷二九作「覺此」）真常覺，方便鹿苑制尊經。","爲度妄想諸邪見，令知寂滅得安甯。","廣說菩提與諸行，而此二法即音聲。","了達音聲處非處，三毒煩惱不虧盈。","又達五陰皆空寂，正慧無生制六情。","於茲六情隨念滅，即是真了湼槃城。","行路難，路難無往復無還。","貪嗔不在於內外，亦復的不在中間。"]', '["君不见心相微細最奇精，非作非緣非色名。","雖复恬然非有相，若凡若聖己之靈。","此靈無形而常應，雖复常應實無形。","心性無来亦無去，緣慮流轉實無停。","正覺此之（《宗镜錄》卷二九作「覺此」）真常覺，方便鹿苑制尊經。","爲度妄想諸邪见，令知寂滅得安甯。","廣说菩提與諸行，而此二法即音声。","了達音声处非处，三毒煩惱不虧盈。","又達五陰皆空寂，正慧無生制六情。","於茲六情隨念滅，即是真了湼槃城。","行路难，路难無往复無還。","貪嗔不在於內外，亦复的不在中间。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第三章明心相實相 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b9facc-bf9a-4004-b6eb-f630b8682f91', '行路難二十篇（幷序） 第四章明無相虛融', '行路难二十篇（幷序） 第四章明無相虛融', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見決定法中無決定，虛妄顛倒是菩提。","若心分別菩提法，分別菩提還復迷。","若了此迷無分別，迷與分別即菩提。","分別菩提非一異，恒一同體不相離。","安住性空真實性，空性無空亦不齊。","同體大悲含一切，故知真性不乖迷。","只此昏迷即無性，亦復不論齊不齊。","若捨塵勞更無法，喻若蓮花生淤泥。","如來法身無別處，普通三界苦泥犁。","三界泥犁本非有，微妙誰復得見蹊？","行路難，路難本自是泥洹。"]', '["君不见決定法中無決定，虛妄顛倒是菩提。","若心分別菩提法，分別菩提還复迷。","若了此迷無分別，迷與分別即菩提。","分別菩提非一異，恒一同體不相離。","安住性空真實性，空性無空亦不齊。","同體大悲含一切，故知真性不乖迷。","只此昏迷即無性，亦复不論齊不齊。","若捨塵勞更無法，喻若蓮花生淤泥。","如来法身無別处，普通三界苦泥犁。","三界泥犁本非有，微妙誰复得见蹊？","行路难，路难本自是泥洹。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第四章明無相虛融 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fbb4847-d7be-48b4-930f-ccccaa0fa314', '行路難二十篇（幷序） 第五章明凡聖非一非二', '行路难二十篇（幷序） 第五章明凡聖非一非二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見煩惱茫然非是一，雖復非一亦非多。","若能照知其本際，即是真身盧舍那。","入於微塵亦無礙，無礙體寂遍娑婆。","凡聖兩途非二處，生死涅槃常共和。","雖復強立名和字，只箇愛癡真佛陀。","般若深空智非智，以無心意制衆魔。","余既誠心學此術，聊抽拙抱作斯歌。","行路難，路難心性實極寬。","貪欲本來常寂滅，智者於此可盤桓。"]', '["君不见煩惱茫然非是一，雖复非一亦非多。","若能照知其本際，即是真身盧舍那。","入於微塵亦無礙，無礙體寂遍娑婆。","凡聖兩途非二处，生死涅槃常共和。","雖复強立名和字，只箇愛癡真佛陀。","般若深空智非智，以無心意制衆魔。","余既誠心学此術，聊抽拙抱作斯歌。","行路难，路难心性實極寬。","貪欲本来常寂滅，智者於此可盤桓。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第五章明凡聖非一非二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('050e1428-a89e-45f5-9d72-46249d375657', '行路難二十篇（幷序） 第六章明心性無染', '行路难二十篇（幷序） 第六章明心性無染', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見智人求心不求佛，諸法寂滅即貪淫。","愛欲貪淫從心起，我亦徵心於無心。","若也求心復不得，自然無處起貪淫。","貪淫無起亦無滅，顛倒非淺亦非深。","又亦不得非貪欲，無得不得妙難尋。","三毒性中恒如此，具足常同堅固林。","余事貪淫爲佛事，更無三毒橫相侵。","若求出離還沉沒，分別出沒還復沈。","諸佛善得於三毒，衆生虛妄不能任。","我亦勤修三毒性，更不願求諸佛心。","行路難，路難心中本無物。","無物即是淨菩提，無見心中常見佛。"]', '["君不见智人求心不求佛，諸法寂滅即貪淫。","愛欲貪淫從心起，我亦徵心於無心。","若也求心复不得，自然無处起貪淫。","貪淫無起亦無滅，顛倒非淺亦非深。","又亦不得非貪欲，無得不得妙难尋。","三毒性中恒如此，具足常同堅固林。","余事貪淫爲佛事，更無三毒橫相侵。","若求出離還沉沒，分別出沒還复沈。","諸佛善得於三毒，衆生虛妄不能任。","我亦勤修三毒性，更不願求諸佛心。","行路难，路难心中本無物。","無物即是淨菩提，無见心中常见佛。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第六章明心性無染 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dab5692-0485-40d1-857b-19401cb9e4d0', '行路難二十篇（幷序） 第七章明般若無諍', '行路难二十篇（幷序） 第七章明般若無諍', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見般若真源本常淨，生死根際自虛微。","即此生死真般若，離斯外覓反相違。","心若分別於生死，諸苦毒難竟相追。","今若事之爲功匠，虛妄顛倒不能歸。","而此但假空言語，淨穢兩邊俱不依。","無心捨離於生死，涅槃無心即生死，生死無心般若暉。","般若無心明照用，無照無用斷言辭。","亦復不欲有諸見，即是法王無上醫。","善解於此無心藥，三有諸病盡能治。","行路難，路難遣之而復遣。","識此遣性本來空，無心終是摩訶衍。"]', '["君不见般若真源本常淨，生死根際自虛微。","即此生死真般若，離斯外覓反相違。","心若分別於生死，諸苦毒难竟相追。","今若事之爲功匠，虛妄顛倒不能归。","而此但假空言語，淨穢兩邊俱不依。","無心捨離於生死，涅槃無心即生死，生死無心般若暉。","般若無心明照用，無照無用斷言辞。","亦复不欲有諸见，即是法王無上醫。","善解於此無心藥，三有諸病尽能治。","行路难，路难遣之而复遣。","識此遣性本来空，無心終是摩訶衍。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第七章明般若無諍 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79478f29-a9ba-4676-824e-25d59edeecf9', '行路難二十篇（幷序） 第八章明本際不可得', '行路难二十篇（幷序） 第八章明本際不可得', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見本際之中無復本，無本真際無人知。","若人無知了斯際，清淨妙不爲奇。","知與無知常自爾，苦樂等同於大悲。","三界衆生乃迷騖，於其實錄是無爲。","亦復無此無爲法，強自生心是苦疲。","苦疲皆空如炎響，生平不住不分離。","能知此心無隔礙，生死虛妄不能羈。","而此一心皆悉具，八萬四千諸律儀。","亦復不墮過人法，嶮巇絕危而不危。","一切法中無有法，世人遑遽欲何爲？","行路難，路難心中無可看。","昔日謂言諸佛遠，今知貪嗔是涅槃。"]', '["君不见本際之中無复本，無本真際無人知。","若人無知了斯際，清淨妙不爲奇。","知與無知常自爾，苦乐等同於大悲。","三界衆生乃迷騖，於其實錄是無爲。","亦复無此無爲法，強自生心是苦疲。","苦疲皆空如炎响，生平不住不分離。","能知此心無隔礙，生死虛妄不能羈。","而此一心皆悉具，八万四千諸律儀。","亦复不墮過人法，嶮巇絕危而不危。","一切法中無有法，世人遑遽欲何爲？","行路难，路难心中無可看。","昔日謂言諸佛远，今知貪嗔是涅槃。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第八章明本際不可得 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65deb155-852a-4157-aa82-0364fbae8114', '行路難二十篇（幷序） 第九章明無斷煩惱', '行路难二十篇（幷序） 第九章明無斷煩惱', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見文殊妙德非爲遠，三障三毒即二空。","五分法身纏五陰，六人無知爲六通。","四倒四果何曾異，八邪八正體還同。","七覺菩提性無別，七識流浪會真宗。","一切煩惱皆空寂，諸佛法藏在心胸。","恒將法忍相隨逐，只自差舛不相逢。","諸佛如來住何所，併在貪淫愛欲中。","今勸斷貪淫愛欲，但是方便化童蒙。","貪欲本相真清淨，假說空名名亦空。","行路難，路難心中非是心。","寄語真修無念士，慎勿分別毀貪淫。"]', '["君不见文殊妙德非爲远，三障三毒即二空。","五分法身纏五陰，六人無知爲六通。","四倒四果何曾異，八邪八正體還同。","七覺菩提性無別，七識流浪會真宗。","一切煩惱皆空寂，諸佛法藏在心胸。","恒將法忍相隨逐，只自差舛不相逢。","諸佛如来住何所，併在貪淫愛欲中。","今勸斷貪淫愛欲，但是方便化童蒙。","貪欲本相真清淨，假说空名名亦空。","行路难，路难心中非是心。","寄語真修無念士，慎勿分別毀貪淫。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第九章明無斷煩惱 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0888ed-955c-45df-9a97-c7eca6afa276', '行路難二十篇（幷序） 第十章明寂滅無心常行精進', '行路难二十篇（幷序） 第十章明寂滅無心常行精進', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見寂滅性中無寂滅，真實覺中無覺和。","亦復無有無知覺，清虛寂寞離方規。","法性自爾無因致，憶想顛倒性無爲。","正使飄流遍三界，於其心中實不移。","無去無來亦無住，善達無住亦無虧。","諸佛世雄非尊大，三毒四倒亦非卑。","却尋緣心無所得，無緣心中緣復彌。","若欲速去無上道，無知三毒性能資。","三毒生於三解脫，七識還生七覺支。","倒心去來無有實，去來無急亦無遲。","覺諸煩惱觀前境，但自懲心而却推。","心本無根何有本，六塵五欲不能拘。","行路難，路難微妙甚希奇。","昔日殷勤勇精進，不知精進背無爲。"]', '["君不见寂滅性中無寂滅，真實覺中無覺和。","亦复無有無知覺，清虛寂寞離方規。","法性自爾無因致，憶想顛倒性無爲。","正使飄流遍三界，於其心中實不移。","無去無来亦無住，善達無住亦無虧。","諸佛世雄非尊大，三毒四倒亦非卑。","却尋緣心無所得，無緣心中緣复彌。","若欲速去無上道，無知三毒性能資。","三毒生於三解脫，七識還生七覺支。","倒心去来無有實，去来無急亦無遲。","覺諸煩惱观前境，但自懲心而却推。","心本無根何有本，六塵五欲不能拘。","行路难，路难微妙甚希奇。","昔日殷勤勇精進，不知精進背無爲。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十章明寂滅無心常行精進 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea51a55e-930d-48e2-854a-d90f0d26b5a3', '行路難二十篇（幷序） 第十一章明法身體用自在', '行路难二十篇（幷序） 第十一章明法身體用自在', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不角大士自觀身中法，身是如來淨法身。","虛空往還最迅速，獨脫自在不由人。","出入毛孔而無礙，愛取塵時不染塵。","現處凡情等諸聖，離斯求道更無真。","建立諸法而無法，即是真如無上真。","億劫本有而非故，於今現覺亦非新。","成就大我而無我，具足大人無有人。","聖體無明不可說，爲復方便名心神。","即此心是真常法，亦是涅槃之上珍。","願諸學人同此悟，各自守門而禁津。","行路難，路難名異理無分。","若能了於無生死，便得除消生死雲。","。"]', '["君不角大士自观身中法，身是如来淨法身。","虛空往還最迅速，独脫自在不由人。","出入毛孔而無礙，愛取塵时不染塵。","現处凡情等諸聖，離斯求道更無真。","建立諸法而無法，即是真如無上真。","億劫本有而非故，於今現覺亦非新。","成就大我而無我，具足大人無有人。","聖體無明不可说，爲复方便名心神。","即此心是真常法，亦是涅槃之上珍。","願諸学人同此悟，各自守门而禁津。","行路难，路难名異理無分。","若能了於無生死，便得除消生死云。","。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十一章明法身體用自在 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9692e0bb-b1ec-49aa-afd6-b59ac1d31341', '行路難二十篇（幷序） 第十二章明金剛解脫', '行路难二十篇（幷序） 第十二章明金剛解脫', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見金剛語句非真實，萬象森羅同一無。","而此空無爲佛母，復是真如無上珠。","世人不知求此寶，貧窮怱怱六趣奴。","不事身中法身佛，冗冗向外禮浮圖。","乍看而欲似精進，檢責身中皆併麄。","用箇麄心逞言語，不了真源由是愚。","隨情憶想而分別，五陰六賊競來誅。","不肯尋求無上道，但知虛妄取名譽。","口雖唱善還生惡，空言真實反成虛。","余今反虛持作實，亦不證實入無餘。","行路難，路難舉世皆虛妄。","十纏五陰性無知，愚人於中自生障。"]', '["君不见金剛語句非真實，万象森羅同一無。","而此空無爲佛母，复是真如無上珠。","世人不知求此寶，貧窮怱怱六趣奴。","不事身中法身佛，冗冗向外禮浮圖。","乍看而欲似精進，檢責身中皆併麄。","用箇麄心逞言語，不了真源由是愚。","隨情憶想而分別，五陰六賊競来誅。","不肯尋求無上道，但知虛妄取名譽。","口雖唱善還生惡，空言真實反成虛。","余今反虛持作實，亦不證實入無餘。","行路难，路难舉世皆虛妄。","十纏五陰性無知，愚人於中自生障。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十二章明金剛解脫 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59fa97c8-1e06-4dc0-8170-f3df329d7390', '行路難二十篇（幷序） 第十三章明寂靜無照無得', '行路难二十篇（幷序） 第十三章明寂静無照無得', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見諸法但假空施設，寂靜無門爲法門。","一切法中心爲主，余今不復得心源。","究檢心源既不得，豈知諸法併無根。","用此無根心照境，照之分明彌復惛。","即此惛心還自照，正照之理未曾存。","照之與境俱差異，是故智士不能論。","世人往往強分別，無中照見亂精魂。","若能智照亡非照，分別智照復還奔。","諸法本爾誰人作，寂靜無寂亦無喧。","故知衆生顛倒想，還是衆生無上尊。","行路難，路難捨癡而非癡。","飛禽走獸我能伏，只箇心賊獨難治。"]', '["君不见諸法但假空施設，寂静無门爲法门。","一切法中心爲主，余今不复得心源。","究檢心源既不得，豈知諸法併無根。","用此無根心照境，照之分明彌复惛。","即此惛心還自照，正照之理未曾存。","照之與境俱差異，是故智士不能論。","世人往往強分別，無中照见亂精魂。","若能智照亡非照，分別智照复還奔。","諸法本爾誰人作，寂静無寂亦無喧。","故知衆生顛倒想，還是衆生無上尊。","行路难，路难捨癡而非癡。","飞禽走獸我能伏，只箇心賊独难治。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十三章明寂靜無照無得 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b93ba4e-0c95-4eae-8efc-58a0dbeadbcf', '行路難二十篇（幷序） 第十四章明三空無性', '行路难二十篇（幷序） 第十四章明三空無性', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見諸佛聖人心無礙，爲通道化說三無。","雖說三無實無說，心爲萬境所由居。","正使顛倒造五逆，隨情所作併歸如。","抱檏澄神念無念，亦不分別滅無餘。","所以安心不擇處，了知真俗體非殊。","息慮心空不捨事，名理言行不相扶。","不依六塵心搖動，真如無作順空虛。","無去無來常不住，心神竭盡亦非無。","不壞於身隨一相，不斷貪淫而不居。","若謂無差還自縛，言其體異轉傷軀。","猶如夢幻無真實，本來非有若爲除。","行路難，路難頓爾難料理。","凡夫妄見有差殊，真實凝心無彼此。"]', '["君不见諸佛聖人心無礙，爲通道化说三無。","雖说三無實無说，心爲万境所由居。","正使顛倒造五逆，隨情所作併归如。","抱檏澄神念無念，亦不分別滅無餘。","所以安心不擇处，了知真俗體非殊。","息慮心空不捨事，名理言行不相扶。","不依六塵心搖动，真如無作順空虛。","無去無来常不住，心神竭尽亦非無。","不壞於身隨一相，不斷貪淫而不居。","若謂無差還自縛，言其體異轉傷軀。","猶如梦幻無真實，本来非有若爲除。","行路难，路难頓爾难料理。","凡夫妄见有差殊，真實凝心無彼此。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十四章明三空無性 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b725c594-b90e-49bf-bee3-ce39aed693a1', '行路難二十篇（幷序） 第十五章明空有不違', '行路难二十篇（幷序） 第十五章明空有不違', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見邪見非邊不離邊，顛倒分別亦非緣。","自心非心念非念，常來常去實無遷。","猶若金剛難沮壞，諸佛用此作金堅。","世人稱譽涅槃妙，余道生死最深玄。","即是無生之上忍，又是摩訶無礙禪。","正士由心於是定，不爲八風之所牽。","天樂之在無心戀，小小財色豈能纏。","隨逢苦樂心無變，永別憶想忘憂煎。","虛心無人無我所，任性浮沈如似顛。","實照常法知無定，知法無性號爲賢。","行路難，路難非空亦非有。","有無雙遺兩俱存，俱存無遺亦無受。"]', '["君不见邪见非邊不離邊，顛倒分別亦非緣。","自心非心念非念，常来常去實無遷。","猶若金剛难沮壞，諸佛用此作金堅。","世人稱譽涅槃妙，余道生死最深玄。","即是無生之上忍，又是摩訶無礙禪。","正士由心於是定，不爲八风之所牽。","天乐之在無心戀，小小財色豈能纏。","隨逢苦乐心無变，永別憶想忘憂煎。","虛心無人無我所，任性浮沈如似顛。","實照常法知無定，知法無性號爲賢。","行路难，路难非空亦非有。","有無雙遺兩俱存，俱存無遺亦無受。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十五章明空有不違 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c515d624-5a17-45b6-8eb2-4b672c542101', '行路難二十篇（幷序） 第十六章明魔怨', '行路难二十篇（幷序） 第十六章明魔怨', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見大道寂寞叵思尋，通融萬象盡皆深。","一切恬然無起滅，顛倒分別併從心。","智者求心無處所，茫然絶相離貪活。","了了分明何所見，猶如病眼覩空針。","若人體知顛倒想，不爲妄苦所浦沈。","世間諸法如陽焰，行者慎莫致怨嫌。","恒以空心而照，無上佛道亦能任。","行路難，路難微妙實無雙。","若識六情空非有，衆魔結賊自然降。"]', '["君不见大道寂寞叵思尋，通融万象尽皆深。","一切恬然無起滅，顛倒分別併從心。","智者求心無处所，茫然絶相離貪活。","了了分明何所见，猶如病眼覩空針。","若人體知顛倒想，不爲妄苦所浦沈。","世间諸法如陽焰，行者慎莫致怨嫌。","恒以空心而照，無上佛道亦能任。","行路难，路难微妙實無雙。","若識六情空非有，衆魔結賊自然降。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十六章明魔怨 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f01c3850-484d-4a4b-baaa-babb193d9ace', '行路難二十篇（幷序） 第十七章明法性平等', '行路难二十篇（幷序） 第十七章明法性平等', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見法性無知不可說，有漏無漏幷虛通。","雖復乖差作諸地，尋其本際盡皆同。","亦復無同可同法，亦不以空持作宗。","若欲知斯殊妙道，但自窮搜五陰叢。","如實無來亦無去，亦不的在六情中。","即是無原真法界，湛然常存無始終。","行路難，路難苦樂何未央。","時往西方無量壽，或復託化現東方。"]', '["君不见法性無知不可说，有漏無漏幷虛通。","雖复乖差作諸地，尋其本際尽皆同。","亦复無同可同法，亦不以空持作宗。","若欲知斯殊妙道，但自窮搜五陰叢。","如實無来亦無去，亦不的在六情中。","即是無原真法界，湛然常存無始終。","行路难，路难苦乐何未央。","时往西方無量壽，或复託化現东方。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十七章明法性平等 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a4c036-db09-4d3f-8d4d-62c1a09e9101', '行路難二十篇（幷序） 第十八章明不思議佛母', '行路难二十篇（幷序） 第十八章明不思議佛母', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見愛欲貪淫諸佛母，諸佛世尊貪欲兒。","從來菩提爲我匠，今使我爲衆匠師。","昔日千端外求佛，佛在衣中今始知。","無量癡心本是道，三毒四倒不思議。","虛妄行慈愍衆苦，不知衆苦是慈悲。","嗔恚無明最微妙，世間智者不能思。","昔日辛勤學知見，不知知見自無知。","四趣三塗悉非有，三障三脫不分離。","行路難，路難無有俱併忘。","了知煩惱無生相，即是如來坐道塲。"]', '["君不见愛欲貪淫諸佛母，諸佛世尊貪欲兒。","從来菩提爲我匠，今使我爲衆匠師。","昔日千端外求佛，佛在衣中今始知。","無量癡心本是道，三毒四倒不思議。","虛妄行慈愍衆苦，不知衆苦是慈悲。","嗔恚無明最微妙，世间智者不能思。","昔日辛勤学知见，不知知见自無知。","四趣三塗悉非有，三障三脫不分離。","行路难，路难無有俱併忘。","了知煩惱無生相，即是如来坐道塲。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十八章明不思議佛母 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdc6269-bb9e-4de0-92a0-3ec5e8614f74', '行路難二十篇（幷序） 第十九章明無覺精進', '行路难二十篇（幷序） 第十九章明無覺精進', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見正心修行諸佛子，以見非心故不憂。","知心非心意非意，八風傷逼豈懷愁。","隨風東西無我所，獨脫逍遙不繫舟。","設使住時終非住，走遍十方而不流。","不見我時於無我，善哉設性任沈浮。","世間妄想無真實，吾於此中何所求？","只用非心覺非學，亦復正修於不修。","若人不知如此處，不應稱名作比丘。","爲箇癡心作奴僕，愛結纏之不自由。","而此更增諸苦惱，永劫長塗三界囚。","生死相連彌復甚，盼不能得永長休。","行路難，路難無令過諸念。","無念之念乃爲真，真念無真還自炎。"]', '["君不见正心修行諸佛子，以见非心故不憂。","知心非心意非意，八风傷逼豈懷愁。","隨风东西無我所，独脫逍遙不繫舟。","設使住时終非住，走遍十方而不流。","不见我时於無我，善哉設性任沈浮。","世间妄想無真實，吾於此中何所求？","只用非心覺非学，亦复正修於不修。","若人不知如此处，不應稱名作比丘。","爲箇癡心作奴僕，愛結纏之不自由。","而此更增諸苦惱，永劫长塗三界囚。","生死相連彌复甚，盼不能得永长休。","行路难，路难無令過諸念。","無念之念乃爲真，真念無真還自炎。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第十九章明無覺精進 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc286bc-0079-474b-97f5-439ab8afc67e', '行路難二十篇（幷序） 第二十章明菩提微妙', '行路难二十篇（幷序） 第二十章明菩提微妙', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["君不見無上菩提最爲近，四大五陰皆深奧。","其實清淨妙難知，不悟此心真卒暴。","和合性中無有實，是故稱爲諸法要。","於中無妄亦無真，只用無爲作微妙。","尋其體寂不應言，假爲衆生立名號。","若知名號即非名，解了衆生知佛教。","覺知無因之正因，當得無因無果報。","善達貪愛得無生，無名去來無動搖。","不見聖果異凡情，分別聖凡還復倒。","若人無願齊無修，必定當爲世間導。","行路難，路難非穢亦非淨。","是非雙泯復還存，泯存叵測見真性。"]', '["君不见無上菩提最爲近，四大五陰皆深奧。","其實清淨妙难知，不悟此心真卒暴。","和合性中無有實，是故稱爲諸法要。","於中無妄亦無真，只用無爲作微妙。","尋其體寂不應言，假爲衆生立名號。","若知名號即非名，解了衆生知佛教。","覺知無因之正因，當得無因無果報。","善達貪愛得無生，無名去来無动搖。","不见聖果異凡情，分別聖凡還复倒。","若人無願齊無修，必定當爲世间導。","行路难，路难非穢亦非淨。","是非雙泯复還存，泯存叵測见真性。"]', '诗', 'shi', '', NULL, '行路難二十篇（幷序） 第二十章明菩提微妙 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('010dc188-bfec-414e-a2c0-653e24bb5abc', '行路易十五首 一', '行路易十五首 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["佛生具一體，生佛本地同。","觸目皆如此，無心自性中。","行路易，路易不修行。","有無心永息，只箇是無生。"]', '["佛生具一體，生佛本地同。","觸目皆如此，無心自性中。","行路易，路易不修行。","有無心永息，只箇是無生。"]', '诗', 'shi', '', NULL, '行路易十五首 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f07083-25b9-46a9-8e0c-8e3867cc8854', '行路易十五首 二', '行路易十五首 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["衆生是佛祖，佛是衆生翁。","三寶不相離，菩提皆共同。","行路易，路易真無作。","持經不動口，坐禪終日臥。"]', '["衆生是佛祖，佛是衆生翁。","三寶不相離，菩提皆共同。","行路易，路易真無作。","持經不动口，坐禪終日臥。"]', '诗', 'shi', '', NULL, '行路易十五首 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63b78f23-0a27-4a49-bec4-76f7781b1623', '行路易十五首 三', '行路易十五首 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["無生無處所，無處是無生。","若覓無生處，無生無處生。","行路易，路易坦然平。","無心真解脫，自性任縱橫。"]', '["無生無处所，無处是無生。","若覓無生处，無生無处生。","行路易，路易坦然平。","無心真解脫，自性任縱橫。"]', '诗', 'shi', '', NULL, '行路易十五首 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b498e7d7-f071-44f3-93b1-1b542d161022', '行路易十五首 四', '行路易十五首 四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["菩提無處所，無處是菩提。","若覓菩提處，終身累劫迷。","行路易，路易真不虛。","善惡無分別，此則是真如。"]', '["菩提無处所，無处是菩提。","若覓菩提处，終身累劫迷。","行路易，路易真不虛。","善惡無分別，此則是真如。"]', '诗', 'shi', '', NULL, '行路易十五首 四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d05e17-9477-44de-ae9a-8776c7266455', '行路易十五首 五', '行路易十五首 五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["有無皆解脫，累息在無生。","菩提是顛倒，生死最爲精。","行路易，路易人莫疑。","解我如此語，修道不須師。"]', '["有無皆解脫，累息在無生。","菩提是顛倒，生死最爲精。","行路易，路易人莫疑。","解我如此語，修道不須師。"]', '诗', 'shi', '', NULL, '行路易十五首 五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec893975-33a8-4e52-b2a9-204b678dd29f', '行路易十五首 六', '行路易十五首 六', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["東山水上浮，西山行不住。","北斗下閻浮，是真解脫處。","行路易，路易人不識。","半夜日頭明，不悟真疲劇（《宗鏡錄》卷六作「極」）。"]', '["东山水上浮，西山行不住。","北斗下閻浮，是真解脫处。","行路易，路易人不識。","半夜日头明，不悟真疲劇（《宗镜錄》卷六作「極」）。"]', '诗', 'shi', '', NULL, '行路易十五首 六 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd40386-22ed-4492-b25a-83320f402ad5', '行路易十五首 七', '行路易十五首 七', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["猛風不動樹，打鼓不聞聲。","日出樹無影，牛從水上行。","行路易，路易真可憐。","修道解此意，長伸兩脚眠。","。"]', '["猛风不动樹，打鼓不闻声。","日出樹無影，牛從水上行。","行路易，路易真可怜。","修道解此意，长伸兩脚眠。","。"]', '诗', 'shi', '', NULL, '行路易十五首 七 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6d94a7-01c6-4260-94aa-103e63d712b1', '行路易十五首 八', '行路易十五首 八', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["佛心與衆生，是三終不移。","虛空合真理，人我在無爲。","行路易，路易真難測。","寄語行路人，大應須努力。"]', '["佛心與衆生，是三終不移。","虛空合真理，人我在無爲。","行路易，路易真难測。","寄語行路人，大應須努力。"]', '诗', 'shi', '', NULL, '行路易十五首 八 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9473415d-ebcf-4a15-af15-1d04b47381c2', '行路易十五首 九', '行路易十五首 九', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["人道行路難，我道行路易。","入山十二年，長伸兩脚睡。","行路易，路易莫思量。","剎那心不二，終日是天堂。"]', '["人道行路难，我道行路易。","入山十二年，长伸兩脚睡。","行路易，路易莫思量。","剎那心不二，終日是天堂。"]', '诗', 'shi', '', NULL, '行路易十五首 九 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cf6638a-0d28-48d1-aae2-0503c54c112f', '行路易十五首 十', '行路易十五首 十', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["須彌芥子父，芥子須彌爺。","山海平坦地，燒冰將煮茶。","行路易，路易真寂寞。","菩提在心中，世人元不覺。"]', '["須彌芥子父，芥子須彌爺。","山海平坦地，燒冰將煮茶。","行路易，路易真寂寞。","菩提在心中，世人元不覺。"]', '诗', 'shi', '', NULL, '行路易十五首 十 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5189585a-3078-4cc5-80e7-bd6e29ac820a', '行路易十五首 十一', '行路易十五首 十一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["有無來去心永息，內外中間心總無。","欲覓如來真佛處，但看石牛生象兒。","行路易，路易須及早。","不用學多聞，無言真是道。"]', '["有無来去心永息，內外中间心總無。","欲覓如来真佛处，但看石牛生象兒。","行路易，路易須及早。","不用学多闻，無言真是道。"]', '诗', 'shi', '', NULL, '行路易十五首 十一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5913146c-d7f6-4b53-a318-f18861456349', '行路易十五首 十二', '行路易十五首 十二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["無明是無作，無作是無心。","若見無心處，楊花水底沈。","行路易，路易真無得。","講說千般論，不如少時默。"]', '["無明是無作，無作是無心。","若见無心处，楊花水底沈。","行路易，路易真無得。","講说千般論，不如少时默。"]', '诗', 'shi', '', NULL, '行路易十五首 十二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b309c0-59b1-4feb-a656-2c26466d40f2', '行路易十五首 十三', '行路易十五首 十三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["無情正是道，木石盡真如。","達時遍處是，不悟永乖疎。","行路易，路易真可樂。","剎那登正覺，不用披三教。"]', '["無情正是道，木石尽真如。","達时遍处是，不悟永乖疎。","行路易，路易真可乐。","剎那登正覺，不用披三教。"]', '诗', 'shi', '', NULL, '行路易十五首 十三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d480d67a-2acb-4d10-8385-866af9a1d80f', '行路易十五首 十四', '行路易十五首 十四', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["無心真無事，無事少人知。","無爲無處所。","無處是無爲。","行路易，路易人莫驚。","無有無爲事，空有無爲名。"]', '["無心真無事，無事少人知。","無爲無处所。","無处是無爲。","行路易，路易人莫驚。","無有無爲事，空有無爲名。"]', '诗', 'shi', '', NULL, '行路易十五首 十四 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2830202-93c5-4b8b-a748-abcc00e8b915', '行路易十五首 十五', '行路易十五首 十五', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["無我無人真出家，何須剃髮染袈裟。","欲識逍遙真解脫，但看水牛生象牙。","行路易，路易君諦聽。","無覺無菩提，無垢亦無淨。"]', '["無我無人真出家，何須剃髮染袈裟。","欲識逍遙真解脫，但看水牛生象牙。","行路易，路易君諦听。","無覺無菩提，無垢亦無淨。"]', '诗', 'shi', '', NULL, '行路易十五首 十五 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a50a2b7-d54f-453d-b259-d6d3e13d9d5f', '率題六章 第一章歎佇歸珠至今獲', '率題六章 第一章歎佇归珠至今獲', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["攜明是今日，感應在明陽。","想思深洞盡，企子實難當。","朝憶生眷戀，夕望動心傷。","若期靈樹下，度脫不相忘。","忍見孤憔悴，惧願普趨蹡。","雙飛白日頂，出氣紫雲光。","神龍左右梵，散花來芬芳。","菲菲常樂境，藹藹昇金堂。"]', '["携明是今日，感應在明陽。","想思深洞尽，企子實难當。","朝憶生眷戀，夕望动心傷。","若期靈樹下，度脫不相忘。","忍见孤憔悴，惧願普趨蹡。","雙飞白日頂，出氣紫云光。","神龙左右梵，散花来芬芳。","菲菲常乐境，藹藹昇金堂。"]', '诗', 'shi', '', NULL, '率題六章 第一章歎佇歸珠至今獲 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15afc83f-e4ae-414b-bc9a-d1fd5995f6b4', '率題六章 第二章歎高遂背元志', '率題六章 第二章歎高遂背元志', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["近背天宮樂，念苦暫羈斯。","舒散金來抱，流緇布交知。","唯仰相隨善，依令使忘疲。","同登八位境，共樂寶蓮池。","肉身變金體，妙果遂衆奇。"]', '["近背天宮乐，念苦暫羈斯。","舒散金来抱，流緇布交知。","唯仰相隨善，依令使忘疲。","同登八位境，共乐寶蓮池。","肉身变金體，妙果遂衆奇。"]', '诗', 'shi', '', NULL, '率題六章 第二章歎高遂背元志 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8945cc58-8eda-421c-8734-ebc06c409d06', '率題六章 第三章勸修無上道', '率題六章 第三章勸修無上道', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["改緇素容轉，體淨得金蘭。","從修無上道，常樂自然完。","拂拭明珠瑩，光發遍界看。"]', '["改緇素容轉，體淨得金蘭。","從修無上道，常乐自然完。","拂拭明珠瑩，光發遍界看。"]', '诗', 'shi', '', NULL, '率題六章 第三章勸修無上道 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df52f424-287f-49fa-9d18-b50f0beb0b06', '率題六章 第四章歎世人不厭苦任自纏嬰', '率題六章 第四章歎世人不厭苦任自纏嬰', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["肯入七寶車，寧歸地獄所。","刀山已傷形，劍樹方應處。","日更痛難當，年年無暫弭。","流洩三塗中，憔悴玉容毀。","不聽余今訓，爾時仙步阻。"]', '["肯入七寶车，寧归地獄所。","刀山已傷形，劍樹方應处。","日更痛难當，年年無暫弭。","流洩三塗中，憔悴玉容毀。","不听余今訓，爾时仙步阻。"]', '诗', 'shi', '', NULL, '率題六章 第四章歎世人不厭苦任自纏嬰 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128c8b6d-244b-409f-a444-0baba7f5a568', '率題六章 第五章勸請仁賢背苦就樂', '率題六章 第五章勸請仁賢背苦就乐', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["願子從爲善，名價身爲呈。","諸天散花下，飛梵來相迎。","同昇珍寶殿，處處皆光明。","共居常樂境，齊悅證無生。"]', '["願子從爲善，名價身爲呈。","諸天散花下，飞梵来相迎。","同昇珍寶殿，处处皆光明。","共居常乐境，齊悅證無生。"]', '诗', 'shi', '', NULL, '率題六章 第五章勸請仁賢背苦就樂 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fcb1c55-39b0-46fb-b135-6e95fbd92ef6', '率題六章 第六章勸同趣至真解因緣縛', '率題六章 第六章勸同趣至真解因緣縛', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["唯願趣真道，研慮蕩衆緣。","累盡超妙國，逍遙無畏天。"]', '["唯願趣真道，研慮蕩衆緣。","累尽超妙国，逍遙無畏天。"]', '诗', 'shi', '', NULL, '率題六章 第六章勸同趣至真解因緣縛 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c6c249-3a23-4405-839c-4cc311cae26b', '有沙門問大士那不出家答曰不敢住家不敢出家爾時又爲東鄉侯率題二章略說理要云', '有沙门问大士那不出家答曰不敢住家不敢出家爾时又爲东乡侯率題二章略说理要云', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["脫中如不如，縛中莫如相。","乃會三菩提，如如等無上。","法相並無雙，恒乖未曾各。","沈浮隨不隨，搖漾泊無泊。"]', '["脫中如不如，縛中莫如相。","乃會三菩提，如如等無上。","法相並無雙，恒乖未曾各。","沈浮隨不隨，搖漾泊無泊。"]', '诗', 'shi', '', NULL, '有沙門問大士那不出家答曰不敢住家不敢出家爾時又爲東鄉侯率題二章略說理要云 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9501aec-a407-4ec4-bb2d-50707cca6896', '勸諭詩三首 一', '勸諭诗三首 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["持戒如天日，能明本有軀。","照見家中寶，兼聞額上珠。","直超三有海，徑到薩雲衢。","並會等無等，齊證拘無拘。"]', '["持戒如天日，能明本有軀。","照见家中寶，兼闻額上珠。","直超三有海，徑到薩云衢。","並會等無等，齊證拘無拘。"]', '诗', 'shi', '', NULL, '勸諭詩三首 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('744b59dd-ce4a-4fa2-b21f-37ca12a858a7', '勸諭詩三首 二', '勸諭诗三首 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["破戒如船浛，沒溺大江海。","臨窮方喚佛，志操不能改。","命如風中燈，迅滅寧相待。","身死罪猶存，牽向司鼻門。","千苦俱時至，萬痛切神魂。","獨嬰燒煑炙，困劇事難論。"]', '["破戒如船浛，沒溺大江海。","臨窮方喚佛，志操不能改。","命如风中灯，迅滅寧相待。","身死罪猶存，牽向司鼻门。","千苦俱时至，万痛切神魂。","独嬰燒煑炙，困劇事难論。"]', '诗', 'shi', '', NULL, '勸諭詩三首 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e3e02f2-a4a5-4064-b437-f4046981115b', '勸諭詩三首 三', '勸諭诗三首 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["修空截三有，精進作醫王。","共弘調御法，甘雨注無方。","澤潤羣生等，慧解悉芬芳。","普會三菩室，齊證真如房。"]', '["修空截三有，精進作醫王。","共弘調御法，甘雨注無方。","澤潤羣生等，慧解悉芬芳。","普會三菩室，齊證真如房。"]', '诗', 'shi', '', NULL, '勸諭詩三首 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1df250fc-4bde-46de-8bd6-c89bf46b9f02', '率題兩章 一', '率題兩章 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["罷世還本源，離有絕名相。","栖神不二境，體一上無上。"]', '["罷世還本源，離有絕名相。","栖神不二境，體一上無上。"]', '诗', 'shi', '', NULL, '率題兩章 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ff4204-9735-4e68-b6e4-9af145fe97d8', '率題兩章 二', '率題兩章 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["性狎無彼此，心由不去歸。","逍遙空寂苑，悅竟境忘依。","（以上均見《傅大士語錄》〖復日大學圖書館藏清佚名校本〗卷三）。"]', '["性狎無彼此，心由不去归。","逍遙空寂苑，悅竟境忘依。","（以上均见《傅大士語錄》〖复日大学圖书館藏清佚名校本〗卷三）。"]', '诗', 'shi', '', NULL, '率題兩章 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfeb827-d061-465f-9347-fcbf11423f12', '三諫歌', '三諫歌', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["捨世榮，捨世榮華道理長。","努力殷勤學三諫，諫我身心還本鄉。","諫意意根莫令起，諫口口根莫說彰。","諫手手根莫鞭杖，三諫三王王自香。","（此間似脫一句）虛空自得到仙堂。","仙堂不近亦不遠，徘徊只是衆中央。","若欲行住仙堂裏，不用匍匐在他鄉。","若欲求念彌陀佛，東西南北是西方。","西方彌陀觸處是，面前背後七重行。","或黃或赤或紅白，或大或小或短長。","天蓋正是彌陀屋，木孔木穿彌陀房。","天上空中彌陀路，草木正是彌陀鄉。","日夜前後嘈嘈閙，正是彌陀口放光。","若欲禮拜彌陀佛，不用思想強干忙。","若不誑人是禮拜，若不求人是道場。","努力自使三功作，殷勤肆力種衣糧。","山河是家無盡藏，草木是人常滿倉。","泥水是人常滿庫，藤蘿是人無底囊。","多作功夫自成就，自行手脚熟嚴裝。","若欲往生安樂國，只是箇物是西方。","（見《宗鏡錄》卷二九）。"]', '["捨世榮，捨世榮华道理长。","努力殷勤学三諫，諫我身心還本乡。","諫意意根莫令起，諫口口根莫说彰。","諫手手根莫鞭杖，三諫三王王自香。","（此间似脫一句）虛空自得到仙堂。","仙堂不近亦不远，徘徊只是衆中央。","若欲行住仙堂裏，不用匍匐在他乡。","若欲求念彌陀佛，东西南北是西方。","西方彌陀觸处是，面前背後七重行。","或黄或赤或紅白，或大或小或短长。","天蓋正是彌陀屋，木孔木穿彌陀房。","天上空中彌陀路，草木正是彌陀乡。","日夜前後嘈嘈閙，正是彌陀口放光。","若欲禮拜彌陀佛，不用思想強干忙。","若不誑人是禮拜，若不求人是道場。","努力自使三功作，殷勤肆力種衣糧。","山河是家無尽藏，草木是人常满倉。","泥水是人常满庫，藤蘿是人無底囊。","多作功夫自成就，自行手脚熟嚴裝。","若欲往生安乐国，只是箇物是西方。","（见《宗镜錄》卷二九）。"]', '诗', 'shi', '', NULL, '三諫歌 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('863deda9-8806-4fa9-b38c-fbcdad2ce0ee', '歌', '歌', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["諸佛村鄉在世界，四海三田遍滿生。","佛共衆生同一體，衆生是佛之假名。","若欲見佛看三郡，田宅園林處處停。","或飛虛空中擾擾，或擲山水口轟轟。","或結羣朋往來去，或復孤單而獨行。","或使白日東西走，或使暗夜巡五更。","或烏或赤而復白，或紫或黑而黃青。","或大或小而新養，或老或少舊時生。","或身腰上有燈火，或羽翼上有琴箏。","或游虛空亂上下，或在草石亂縱橫。","或無言行自出宅，或入土抗暫寄生。","或攅木孔爲鄉貫，或遍草木或窠城。","或轉羅網爲樹巷，或臥土石作階廳。","諸佛菩薩家如是，只箇名爲舍衛城。","（同前）。"]', '["諸佛村乡在世界，四海三田遍满生。","佛共衆生同一體，衆生是佛之假名。","若欲见佛看三郡，田宅园林处处停。","或飞虛空中擾擾，或擲山水口轟轟。","或結羣朋往来去，或复孤單而独行。","或使白日东西走，或使暗夜巡五更。","或烏或赤而复白，或紫或黑而黄青。","或大或小而新養，或老或少旧时生。","或身腰上有灯火，或羽翼上有琴箏。","或游虛空亂上下，或在草石亂縱橫。","或無言行自出宅，或入土抗暫寄生。","或攅木孔爲乡貫，或遍草木或窠城。","或轉羅網爲樹巷，或臥土石作階廳。","諸佛菩薩家如是，只箇名爲舍衛城。","（同前）。"]', '诗', 'shi', '', NULL, '歌 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2789bde-e9e7-4a23-b03b-aae284e4f7c1', '頌 一', '頌 一', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["佛亦不離心，心亦不離佛。","心寂即涅槃，心能即有物。","物則變成魔，無物即見佛。","若能如是用，十八從何出？","（同前卷十九）。"]', '["佛亦不離心，心亦不離佛。","心寂即涅槃，心能即有物。","物則变成魔，無物即见佛。","若能如是用，十八從何出？","（同前卷十九）。"]', '诗', 'shi', '', NULL, '頌 一 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8eb220a-7455-4c53-9482-6b8455a3de92', '頌 二', '頌 二', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["能知此心無隔礙，生死虛妄不能覊。","而此一心皆悉具，八萬四千諸律儀。","（同前卷二九）。"]', '["能知此心無隔礙，生死虛妄不能覊。","而此一心皆悉具，八万四千諸律儀。","（同前卷二九）。"]', '诗', 'shi', '', NULL, '頌 二 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1ac9f66-72e1-4718-b937-c96706aa590f', '頌 三', '頌 三', '9ba654f6-dbfc-4d5d-9778-d48ca0516e26', '唐', '["凡地修聖道，果地習凡因。","恒行無所踐，常度無度人。"]', '["凡地修聖道，果地習凡因。","恒行無所踐，常度無度人。"]', '诗', 'shi', '', NULL, '頌 三 傅翕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15573ae8-5eb8-48b9-89a5-0c6f7256ec05', '大乘讚十首 一', '大乘讚十首 一', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["大道常在目前，雖在目前難覩。","若欲悟道真體，莫除色聲言語。","言語即是大道，不假斷除煩惱。","煩惱本來空寂，妄情遞相纏繞。","一切如影如響，不知何惡何好。","有心取相爲寶，定知見性不了。","若欲作業求佛，業是生死大兆。","生死業常隨身，黑闇獄中未曉。","悟理本來無異，覺後誰晚誰早。","法界量同太虛，衆生智心自小。","但能不起吾我，湼槃法食常飽。"]', '["大道常在目前，雖在目前难覩。","若欲悟道真體，莫除色声言語。","言語即是大道，不假斷除煩惱。","煩惱本来空寂，妄情遞相纏繞。","一切如影如响，不知何惡何好。","有心取相爲寶，定知见性不了。","若欲作業求佛，業是生死大兆。","生死業常隨身，黑闇獄中未晓。","悟理本来無異，覺後誰晚誰早。","法界量同太虛，衆生智心自小。","但能不起吾我，湼槃法食常飽。"]', '诗', 'shi', '', NULL, '大乘讚十首 一 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bd1ae9d-d808-406e-8d03-edc6a6c13892', '大乘讚十首 二', '大乘讚十首 二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["妄身臨鏡照影，影與妄身不殊。","但欲去影留身，不知身本同虛。","身本與影不異，不得一有一無。","若欲存一捨一，永與真理相踈。","更若愛聖憎凡，生死海裏沉浮。","煩惱因心有故，無心煩惱何居？","不勞分別取相，自然得道須臾。","夢時夢中造作，覺時覺境都無。","飜思覺時與夢，顛倒二見不殊。","改迷取覺求利，何異販賣商徒？","動靜兩亡常寂，自然契合真如。","若言衆生異佛，迢迢與佛常踈。","佛與衆生不二，自然究竟無餘。"]', '["妄身臨镜照影，影與妄身不殊。","但欲去影留身，不知身本同虛。","身本與影不異，不得一有一無。","若欲存一捨一，永與真理相踈。","更若愛聖憎凡，生死海裏沉浮。","煩惱因心有故，無心煩惱何居？","不勞分別取相，自然得道須臾。","梦时梦中造作，覺时覺境都無。","飜思覺时與梦，顛倒二见不殊。","改迷取覺求利，何異販賣商徒？","动静兩亡常寂，自然契合真如。","若言衆生異佛，迢迢與佛常踈。","佛與衆生不二，自然究竟無餘。"]', '诗', 'shi', '', NULL, '大乘讚十首 二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72935e51-8062-4370-8ae2-c9d4dd35a61e', '大乘讚十首 三', '大乘讚十首 三', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["法性本來常寂，蕩蕩無有邊畔。","安心取捨之閒，被他二境迴換。","斂容入定坐禪，攝境安心覺觀。","機關木人修道，何時得達彼岸？","諸法本空無著，境似浮雲會散。","忽悟本性元空，恰似熱病得汗。","無智人前莫說，打你色身星散。"]', '["法性本来常寂，蕩蕩無有邊畔。","安心取捨之閒，被他二境迴換。","斂容入定坐禪，攝境安心覺观。","機关木人修道，何时得達彼岸？","諸法本空無著，境似浮云會散。","忽悟本性元空，恰似熱病得汗。","無智人前莫说，打你色身星散。"]', '诗', 'shi', '', NULL, '大乘讚十首 三 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c1aea0-7cbb-4fe9-a31d-566002d75a3d', '大乘讚十首 四', '大乘讚十首 四', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["報你衆生直道，非有即是非無。","非有非無不二，何須對有論虛？","有無妄心立號，一破一個不居。","兩名由爾情作，無情即本真如。","若欲存情覔佛，將網山上羅魚。","徒費功夫無益，幾許枉用功夫。","不解即心即佛，真似騎驢覔驢。","一切不憎不愛，遮個煩惱須除。","除之則須除身，除身無佛無因。","無佛無因可得，自然無法無人。"]', '["報你衆生直道，非有即是非無。","非有非無不二，何須对有論虛？","有無妄心立號，一破一個不居。","兩名由爾情作，無情即本真如。","若欲存情覔佛，將網山上羅鱼。","徒費功夫無益，幾許枉用功夫。","不解即心即佛，真似騎驢覔驢。","一切不憎不愛，遮個煩惱須除。","除之則須除身，除身無佛無因。","無佛無因可得，自然無法無人。"]', '诗', 'shi', '', NULL, '大乘讚十首 四 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ad4c1f-baab-4dd4-80c9-7e5400c82f1e', '大乘讚十首 五', '大乘讚十首 五', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["大道不由行得，說行權爲凡愚。","得理返觀於行，始知枉用功夫。","未悟圓通大理，要須言行相扶。","不得執他知解，迴光返本全無。","有誰解會此說，教君向己推求。","自見昔時罪過，除却五欲瘡疣。","解脫逍遙自在，隨方賤賣風流。","誰是發心買者，亦得似我無憂。"]', '["大道不由行得，说行權爲凡愚。","得理返观於行，始知枉用功夫。","未悟圓通大理，要須言行相扶。","不得執他知解，迴光返本全無。","有誰解會此说，教君向己推求。","自见昔时罪過，除却五欲瘡疣。","解脫逍遙自在，隨方賤賣风流。","誰是發心買者，亦得似我無憂。"]', '诗', 'shi', '', NULL, '大乘讚十首 五 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008bfa52-d369-4ed2-8515-6b0b68f108c9', '大乘讚十首 六', '大乘讚十首 六', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["內見外見緫惡，佛道魔道俱錯。","被此二大波旬，便即厭苦求樂。","生死悟本體空，佛魔何處安著？","只由妄情分別，前身後身孤薄。","輪迴六道不停，結業不能除却。","所以流浪生死，皆由橫生經略。","身本虛無不實，返本是誰斟酌？","有無我自能爲，不勞妄心卜度。","衆生身同太虛，煩惱何處安著？","但無一切希求，煩惱自然消落。"]', '["內见外见緫惡，佛道魔道俱錯。","被此二大波旬，便即厭苦求乐。","生死悟本體空，佛魔何处安著？","只由妄情分別，前身後身孤薄。","輪迴六道不停，結業不能除却。","所以流浪生死，皆由橫生經略。","身本虛無不實，返本是誰斟酌？","有無我自能爲，不勞妄心卜度。","衆生身同太虛，煩惱何处安著？","但無一切希求，煩惱自然消落。"]', '诗', 'shi', '', NULL, '大乘讚十首 六 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da356ae5-1a5c-4058-9863-a41295d7e0df', '大乘讚十首 七', '大乘讚十首 七', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["可笑衆生蠢蠢，各執一般異見。","但欲傍鏊求餅，不岇返本觀麵。","麵是正邪之本，由人造作百變。","所須任意縱橫，不假偏耽愛戀。","無著即是解脫，有求又遭羅罥。","慈心一切平等，真如菩提自現。","若懷彼我二心，對面不見佛面。"]', '["可笑衆生蠢蠢，各執一般異见。","但欲傍鏊求餅，不岇返本观麵。","麵是正邪之本，由人造作百变。","所須任意縱橫，不假偏耽愛戀。","無著即是解脫，有求又遭羅罥。","慈心一切平等，真如菩提自現。","若懷彼我二心，对面不见佛面。"]', '诗', 'shi', '', NULL, '大乘讚十首 七 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c9ff872-8e5c-4a85-be75-f25e489b7270', '大乘讚十首 八', '大乘讚十首 八', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["世間幾許癡人，將道復欲求道。","廣尋諸義紛紜，自救己身不了。","專尋他文亂說，自稱至理妙好。","徒勞一生虛過，永劫沈淪生老。","濁愛纏心不捨，清淨智心自惱。","真如法界叢林，返作荆棘荒草。","但執黃葉爲金，不悟棄金求寶。","所以失念狂走，強力裝持相好。","口內誦經誦論，心裏尋常枯槁。","一朝覺本心空，具足真如不少。"]', '["世间幾許癡人，將道复欲求道。","廣尋諸義紛紜，自救己身不了。","專尋他文亂说，自稱至理妙好。","徒勞一生虛過，永劫沈淪生老。","濁愛纏心不捨，清淨智心自惱。","真如法界叢林，返作荆棘荒草。","但執黄葉爲金，不悟棄金求寶。","所以失念狂走，強力裝持相好。","口內誦經誦論，心裏尋常枯槁。","一朝覺本心空，具足真如不少。"]', '诗', 'shi', '', NULL, '大乘讚十首 八 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7348ad7c-d750-48e2-b972-96e86acdc972', '大乘讚十首 九', '大乘讚十首 九', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["聲聞心心斷惑，能斷之心是賊。","賊賊遞相除遣，何時了本語默。","口內誦經千卷，體上問經不識。","不解佛法圓通，徒勞尋行數黑。","頭陁阿練苦行，希望後身功德。","希望即是隔聖，大道何由可得？","譬如夢裏度河，船師度過河北。","忽覺牀上安眠，失却度船軌則。","船師及彼度人，兩個本不相識。","衆生迷倒羇絆，往來三界疲極。","覺悟生死如夢，一切求心自息。"]', '["声闻心心斷惑，能斷之心是賊。","賊賊遞相除遣，何时了本語默。","口內誦經千卷，體上问經不識。","不解佛法圓通，徒勞尋行數黑。","头陁阿練苦行，希望後身功德。","希望即是隔聖，大道何由可得？","譬如梦裏度河，船師度過河北。","忽覺牀上安眠，失却度船軌則。","船師及彼度人，兩個本不相識。","衆生迷倒羇絆，往来三界疲極。","覺悟生死如梦，一切求心自息。"]', '诗', 'shi', '', NULL, '大乘讚十首 九 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d080ac51-82fb-48d2-8ab3-ee4457ee3dc7', '大乘讚十首 十', '大乘讚十首 十', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["悟解即是菩提，了本無有階梯。","堪嘆凡夫軀僂，八十不能跋蹄。","徒勞一生虛過，不覺日月遷移。","向上看他師口，恰似失妳孩兒。","道俗崢嶸聚集，終日聽他死語。","不觀己身無常，心行貪如狼虎。","堪嗟二乘狹劣，要須摧伏六府。","不食酒肉五辛，邪眼看他飲咀。","更有邪行猖狂，修氣不食鹽醋。","若悟上科至真，不假分別男女。"]', '["悟解即是菩提，了本無有階梯。","堪嘆凡夫軀僂，八十不能跋蹄。","徒勞一生虛過，不覺日月遷移。","向上看他師口，恰似失妳孩兒。","道俗崢嶸聚集，終日听他死語。","不观己身無常，心行貪如狼虎。","堪嗟二乘狹劣，要須摧伏六府。","不食酒肉五辛，邪眼看他饮咀。","更有邪行猖狂，修氣不食鹽醋。","若悟上科至真，不假分別男女。"]', '诗', 'shi', '', NULL, '大乘讚十首 十 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c283829-3dc4-44e2-93f4-2ed4eb8fafb6', '十二時頌 一', '十二时頌 一', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["平旦寅，狂機內有道人身。","窮苦已經無量劫，不信常擎如意珍。","若捉物，入迷津，但有纖豪即是塵。","不住舊時無相貌，外求知識也非真。"]', '["平旦寅，狂機內有道人身。","窮苦已經無量劫，不信常擎如意珍。","若捉物，入迷津，但有纖豪即是塵。","不住旧时無相貌，外求知識也非真。"]', '诗', 'shi', '', NULL, '十二時頌 一 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec8b549-1448-460b-972c-89bf1d1d11c4', '十二時頌 二', '十二时頌 二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["日出卯，用處不須生善巧。","縱使神光照有無，起意便遭魔事撓。","若施功，終不了，日夜被他人我拗。"]', '["日出卯，用处不須生善巧。","縱使神光照有無，起意便遭魔事撓。","若施功，終不了，日夜被他人我拗。"]', '诗', 'shi', '', NULL, '十二時頌 二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb139bc-1e62-4204-862d-84410c8624be', '十二時頌 三', '十二时頌 三', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["食時辰，無明本是釋迦身。","坐臥不知元是道，只麽忙忙受苦辛。","認聲色，不覔踈親，只是他家染污人。","若擬將心求佛道，問取虛空始出塵。"]', '["食时辰，無明本是釋迦身。","坐臥不知元是道，只麽忙忙受苦辛。","認声色，不覔踈親，只是他家染污人。","若擬將心求佛道，问取虛空始出塵。"]', '诗', 'shi', '', NULL, '十二時頌 三 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51fff32f-5e38-4c28-8c62-eea52830da87', '十二時頌 四', '十二时頌 四', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["禺中巳，未了之人教不至。","假使通達祖師言，莫向心頭安了義。","只守玄，沒文字，認著依前還不是。","暫時自肯不追尋，曠劫不遭魔境使。"]', '["禺中巳，未了之人教不至。","假使通達祖師言，莫向心头安了義。","只守玄，沒文字，認著依前還不是。","暫时自肯不追尋，曠劫不遭魔境使。"]', '诗', 'shi', '', NULL, '十二時頌 四 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b97d85b9-d12d-4727-b9c9-1ae7c8f22d16', '十二時頌 五', '十二时頌 五', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["日南午，四大身中無價寶。","陽焰空華不肯拋，作意修行轉辛苦。","不曾迷，莫求悟，任你朝陽幾迴暮。","有相身中無相身，無明路上無生路。"]', '["日南午，四大身中無價寶。","陽焰空华不肯拋，作意修行轉辛苦。","不曾迷，莫求悟，任你朝陽幾迴暮。","有相身中無相身，無明路上無生路。"]', '诗', 'shi', '', NULL, '十二時頌 五 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a773625-c9a4-4660-985c-c47cc68c893e', '十二時頌 六', '十二时頌 六', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["日昳未，心地何曾安了義？","他家文字沒親踈，莫起功夫求的意。","任縱橫，絕忌諱，長在人間不居止。","運用不離聲色中，歷劫何曾暫拋棄？","（《宗鏡錄》卷十五引此首，「沒」作「有」，「居止」作「居世」，「不離」作「元來」，末句作「凡夫不了爭爲計」。","）。"]', '["日昳未，心地何曾安了義？","他家文字沒親踈，莫起功夫求的意。","任縱橫，絕忌諱，长在人间不居止。","運用不離声色中，歷劫何曾暫拋棄？","（《宗镜錄》卷十五引此首，「沒」作「有」，「居止」作「居世」，「不離」作「元来」，末句作「凡夫不了爭爲計」。","）。"]', '诗', 'shi', '', NULL, '十二時頌 六 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('388b6043-a9d1-4ecd-9061-4e442f26ed14', '十二時頌 七', '十二时頌 七', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["晡時申，學道先須不厭貧。","有相本來權積聚，無形何用要安真。","作淨潔，却勞神，莫認愚癡作近鄰。","言下不求無處所，暫時喚作出家人。","（《宗鏡錄》卷二四引末二句）。"]', '["晡时申，学道先須不厭貧。","有相本来權積聚，無形何用要安真。","作淨潔，却勞神，莫認愚癡作近鄰。","言下不求無处所，暫时喚作出家人。","（《宗镜錄》卷二四引末二句）。"]', '诗', 'shi', '', NULL, '十二時頌 七 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5c1575-0c06-4325-8a07-7651ace4d8f7', '十二時頌 八', '十二时頌 八', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["日入酉，虛幻聲音終不久。","禪悅珍羞尚不飱，誰能更飲無明酒。","沒可拋，無物守，蕩蕩逍遙不曾有。","縱你多聞達古今，也是癡狂外邊走。"]', '["日入酉，虛幻声音終不久。","禪悅珍羞尚不飱，誰能更饮無明酒。","沒可拋，無物守，蕩蕩逍遙不曾有。","縱你多闻達古今，也是癡狂外邊走。"]', '诗', 'shi', '', NULL, '十二時頌 八 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f424e6b1-0fca-47b8-88ff-40a6273fc55f', '十二時頌 九', '十二时頌 九', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["黃昏戌，狂子興功投暗室。","假使心通無量時，歷劫何曾異今日。","擬商量，却啾唧，轉使心頭黑如漆。","畫夜舒光照有無，癡人喚作波羅蜜。"]', '["黄昏戌，狂子兴功投暗室。","假使心通無量时，歷劫何曾異今日。","擬商量，却啾唧，轉使心头黑如漆。","畫夜舒光照有無，癡人喚作波羅蜜。"]', '诗', 'shi', '', NULL, '十二時頌 九 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d27b05-6a19-4da4-9b92-9c14a3b17464', '十二時頌 十', '十二时頌 十', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["人定亥，勇猛精進成懈怠。","不起纖豪修學心，無相光中常自在。","超釋迦，越祖代，心有微塵還窒閡。","廓然無事頓清閑，他家自有通人愛。"]', '["人定亥，勇猛精進成懈怠。","不起纖豪修学心，無相光中常自在。","超釋迦，越祖代，心有微塵還窒閡。","廓然無事頓清闲，他家自有通人愛。"]', '诗', 'shi', '', NULL, '十二時頌 十 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda2719e-2688-4dac-a4cf-3ea5c8e2728e', '十二時頌 十一', '十二时頌 十一', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["夜半子，心住無生即生死。","生死何曾屬有無，用時便用沒文字。","祖師言，外邊事，識取起時還不是。","作意搜求實沒蹤，生死魔來任相試。","（《宗鏡錄》卷二九引末五句，「識取起時」作「取著元來」，「沒」作「勿」。","）。"]', '["夜半子，心住無生即生死。","生死何曾屬有無，用时便用沒文字。","祖師言，外邊事，識取起时還不是。","作意搜求實沒蹤，生死魔来任相試。","（《宗镜錄》卷二九引末五句，「識取起时」作「取著元来」，「沒」作「勿」。","）。"]', '诗', 'shi', '', NULL, '十二時頌 十一 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b18a9d-355e-4e6b-a612-8abb9d55b789', '十二時頌 十二', '十二时頌 十二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["雞鳴丑，一顆圓珠明已久。","內外推尋覔揔無，境上施爲渾大有。","不見頭，又無手，世界壞時終不朽。","未了之人聽一言，只遮如今誰動口。","。"]', '["雞鳴丑，一顆圓珠明已久。","內外推尋覔揔無，境上施爲渾大有。","不见头，又無手，世界壞时終不朽。","未了之人听一言，只遮如今誰动口。","。"]', '诗', 'shi', '', NULL, '十二時頌 十二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e198497a-644a-485d-977d-f45ec6c9811f', '十四科頭 菩提煩惱不二', '十四科头 菩提煩惱不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["衆生不解修道，便欲斷除煩惱。","煩惱本來空寂，將道更欲覔道。","一念之心即是，何須別處尋討。","大道曉在目前，迷倒愚人不了。","佛性天真自然，亦無因緣修造。","不識三毒虛假，妄執浮沈生老。","昔時迷日爲晚，今日始覺非早。"]', '["衆生不解修道，便欲斷除煩惱。","煩惱本来空寂，將道更欲覔道。","一念之心即是，何須別处尋討。","大道晓在目前，迷倒愚人不了。","佛性天真自然，亦無因緣修造。","不識三毒虛假，妄執浮沈生老。","昔时迷日爲晚，今日始覺非早。"]', '诗', 'shi', '', NULL, '十四科頭 菩提煩惱不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e608dfa-2be9-4342-9370-12866b93613a', '十四科頭 持犯不二', '十四科头 持犯不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["丈夫運用無礙，不爲戒律所制。","持犯本自無生，愚人被他禁繫。","智者造作皆空，互聞觸途爲滯。","大士肉眼圓通，二科天眼有翳。","空中妄執有無，不達色心無礙。","菩薩與俗同居，清淨曾無染世。","愚人貪著湼槃，智者生死實際。","法性空無言說，緣起略無些子。","百歲無智小兒，小兒有智百歲。","（《宗鏡錄》卷八十引「大士」二句）。"]', '["丈夫運用無礙，不爲戒律所制。","持犯本自無生，愚人被他禁繫。","智者造作皆空，互闻觸途爲滯。","大士肉眼圓通，二科天眼有翳。","空中妄執有無，不達色心無礙。","菩薩與俗同居，清淨曾無染世。","愚人貪著湼槃，智者生死實際。","法性空無言说，緣起略無些子。","百歲無智小兒，小兒有智百歲。","（《宗镜錄》卷八十引「大士」二句）。"]', '诗', 'shi', '', NULL, '十四科頭 持犯不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15580aff-d1b8-4998-877e-798b941d50a8', '十四科頭 佛與衆生不二', '十四科头 佛與衆生不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["衆生與佛無殊，大智不異於愚。","何須向外求寶，身田自有明珠。","正道邪道不二，了知凡聖同途。","迷悟本無差別，湼槃生死一如。","究竟攀緣空寂，惟求意想清虛。","無有一法可得，翛然自入無餘。"]', '["衆生與佛無殊，大智不異於愚。","何須向外求寶，身田自有明珠。","正道邪道不二，了知凡聖同途。","迷悟本無差別，湼槃生死一如。","究竟攀緣空寂，惟求意想清虛。","無有一法可得，翛然自入無餘。"]', '诗', 'shi', '', NULL, '十四科頭 佛與衆生不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27df5d4e-e4fe-4449-b3e4-c057f4666417', '十四科頭 事理不二', '十四科头 事理不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["心王自在翛然，法性本無十纏。","一切無非佛事，何須攝念坐禪。","妄想本來空寂，不用斷除攀緣。","智者無心口得，自然無爭無喧。","不識無爲大道，何時得證幽玄。","佛與衆生一種，衆生即是世尊。","凡夫妄生分別，無中執有迷奔。"]', '["心王自在翛然，法性本無十纏。","一切無非佛事，何須攝念坐禪。","妄想本来空寂，不用斷除攀緣。","智者無心口得，自然無爭無喧。","不識無爲大道，何时得證幽玄。","佛與衆生一種，衆生即是世尊。","凡夫妄生分別，無中執有迷奔。"]', '诗', 'shi', '', NULL, '十四科頭 事理不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('073fcf37-b487-41c1-8148-a65779023be8', '十四科頭 靜亂不二', '十四科头 静亂不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["聲聞厭喧求靜，猶如棄麵求餅。","餅即從來是麵，造作隨人百變。","煩惱即是菩提，無心即是無境。","生死不異湼槃，貪嗔如焰如影。","智者無心求佛，愚人執邪執正。","徒勞空過一生，不見如來妙頂。","了達淫慾性空。","鑊湯鑪炭自冷。"]', '["声闻厭喧求静，猶如棄麵求餅。","餅即從来是麵，造作隨人百变。","煩惱即是菩提，無心即是無境。","生死不異湼槃，貪嗔如焰如影。","智者無心求佛，愚人執邪執正。","徒勞空過一生，不见如来妙頂。","了達淫慾性空。","鑊湯鑪炭自冷。"]', '诗', 'shi', '', NULL, '十四科頭 靜亂不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fd6dc96-7d1c-4595-a9df-c08550aeb99a', '十四科頭 善惡不二', '十四科头 善惡不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["我自身心快樂，翛然無善無惡。","法身自在無方，觸目無非正覺。","六塵本來空寂，凡夫妄生執著。","湼槃生死太平，四海阿誰厚薄？","無爲大道自然，不用將心畫度。","故菩薩散誕靈通，所作常含妙覺。","聲聞執法坐禪，如蠶吐絲自縛。","法性本來圓明，病愈何須執藥。","了知諸法平等，翛然清虛快樂。"]', '["我自身心快乐，翛然無善無惡。","法身自在無方，觸目無非正覺。","六塵本来空寂，凡夫妄生執著。","湼槃生死太平，四海阿誰厚薄？","無爲大道自然，不用將心畫度。","故菩薩散誕靈通，所作常含妙覺。","声闻執法坐禪，如蠶吐絲自縛。","法性本来圓明，病愈何須執藥。","了知諸法平等，翛然清虛快乐。"]', '诗', 'shi', '', NULL, '十四科頭 善惡不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25a4c2b0-4d93-4246-9c61-822ee22184f0', '十四科頭 色空不二', '十四科头 色空不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["法性本無青黃，衆生謾造六神。","吾我說他止觀，自意擾擾顛狂。","不識圓通妙理，何時得會真常？","自疾不能治療，却教他人藥方。","外看將爲是善。","心內猶若豺狼。","愚人畏其地獄，智者不異天堂。","對境心常不起，舉足皆是道場。","佛與衆生不二，衆生自作分張。","若欲除却三毒，迢迢不離災殃。","智者知心是佛，愚人樂往西方。"]', '["法性本無青黄，衆生謾造六神。","吾我说他止观，自意擾擾顛狂。","不識圓通妙理，何时得會真常？","自疾不能治療，却教他人藥方。","外看將爲是善。","心內猶若豺狼。","愚人畏其地獄，智者不異天堂。","对境心常不起，舉足皆是道場。","佛與衆生不二，衆生自作分張。","若欲除却三毒，迢迢不離災殃。","智者知心是佛，愚人乐往西方。"]', '诗', 'shi', '', NULL, '十四科頭 色空不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89301de0-9ced-41d7-8187-8acc3942fdca', '十四科頭 生死不二', '十四科头 生死不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["世間諸法如幻，生死猶若雷電。","法身自在圓通，出人山河無間。","顛倒妄想本空，般若無迷無亂。","三毒本自解脫，何須攝念禪觀。","只爲愚人不了，從地戒律決斷。","不識寂滅真如，何時得登彼岸？","智者無惡可斷，運用隨心合散。","法性本來空寂，不爲生死所絆。","若欲斷除煩惱，此是無明癡漢。","煩惱即是菩提，何用別求禪觀？","實際無佛無魔，心體無形無段。"]', '["世间諸法如幻，生死猶若雷電。","法身自在圓通，出人山河無间。","顛倒妄想本空，般若無迷無亂。","三毒本自解脫，何須攝念禪观。","只爲愚人不了，從地戒律決斷。","不識寂滅真如，何时得登彼岸？","智者無惡可斷，運用隨心合散。","法性本来空寂，不爲生死所絆。","若欲斷除煩惱，此是無明癡漢。","煩惱即是菩提，何用別求禪观？","實際無佛無魔，心體無形無段。"]', '诗', 'shi', '', NULL, '十四科頭 生死不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3f3894-08d6-4630-885c-9e2c3f478e20', '十四科頭 斷除不二', '十四科头 斷除不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["丈夫運用堂堂，逍遙自在無妨。","一切不能爲害，堅固猶若金剛。","不著二邊中道，翛然非斷非常。","五欲貪嗔是佛，地獄不異天堂。","愚人妄生分別，流浪生死猖狂。","智者達色無礙，聲聞無不恛惶。","法性本無瑕翳，衆生妄執青黃。","如來引接迷愚，或說地獄天堂。","彌勒身中自有，何須別處思量。","棄却真如佛像，此人即是顛狂。","聲聞心中不了，唯只趁逐言章。","言章本非真道，轉加鬭爭剛強。","心裏蚖蛇蝮蝎，螫著便即遭傷。","不解文中取義，何時得會真常？","死入無間地獄，神識枉受災殃。"]', '["丈夫運用堂堂，逍遙自在無妨。","一切不能爲害，堅固猶若金剛。","不著二邊中道，翛然非斷非常。","五欲貪嗔是佛，地獄不異天堂。","愚人妄生分別，流浪生死猖狂。","智者達色無礙，声闻無不恛惶。","法性本無瑕翳，衆生妄執青黄。","如来引接迷愚，或说地獄天堂。","彌勒身中自有，何須別处思量。","棄却真如佛像，此人即是顛狂。","声闻心中不了，唯只趁逐言章。","言章本非真道，轉加鬭爭剛強。","心裏蚖蛇蝮蝎，螫著便即遭傷。","不解文中取義，何时得會真常？","死入無间地獄，神識枉受災殃。"]', '诗', 'shi', '', NULL, '十四科頭 斷除不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18771cf-e490-4fb9-b44f-aaeb7e2f1fe2', '十四科頭 真俗不二', '十四科头 真俗不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["法師說法極好，心中不離煩惱。","口談文字化他，轉更增他生老。","真妄本來不二，凡夫棄妄覔道。","四衆雲集聽講，高座論義浩浩。","南座北座相爭，四衆爲言爲好。","雖然口談甘露，心裏尋常燥。","自己元無一錢，日夜數他珍寶。","恰似無智愚人，棄却真金擔草。"]', '["法師说法極好，心中不離煩惱。","口談文字化他，轉更增他生老。","真妄本来不二，凡夫棄妄覔道。","四衆云集听講，高座論義浩浩。","南座北座相爭，四衆爲言爲好。","雖然口談甘露，心裏尋常燥。","自己元無一錢，日夜數他珍寶。","恰似無智愚人，棄却真金擔草。"]', '诗', 'shi', '', NULL, '十四科頭 真俗不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c515906-08ae-4daa-8f26-d3d02d098db4', '十四科頭 解縛不二', '十四科头 解縛不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["律師持律自縛，自縛亦能縛他。","外作威儀恬靜，心內恰似洪波。","不駕生死船筏，如何度得愛河？","不解真宗正理，邪見言辭繁多。","有二比丘犯律，便却往問優波。","優波依律說罪，轉增比丘網羅。","方丈室中居士，維摩便即來呵。","優波默然無對，淨名說法無過。","而彼戒性如空，不在內外娑婆。","勸除生滅不肯，忽悟還同釋迦。"]', '["律師持律自縛，自縛亦能縛他。","外作威儀恬静，心內恰似洪波。","不駕生死船筏，如何度得愛河？","不解真宗正理，邪见言辞繁多。","有二比丘犯律，便却往问優波。","優波依律说罪，轉增比丘網羅。","方丈室中居士，維摩便即来呵。","優波默然無对，淨名说法無過。","而彼戒性如空，不在內外娑婆。","勸除生滅不肯，忽悟還同釋迦。"]', '诗', 'shi', '', NULL, '十四科頭 解縛不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b752ffa-470e-4944-876f-630851d556f0', '十四科頭 境照不二', '十四科头 境照不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["禪師體離無明，煩惱從何處生？","地獄天堂一相，湼槃生死空名。","齊無貪嗔可斷，亦無佛道可成。","衆生與佛平等，自然聖智惺惺。","不爲六塵所染，句句獨契無生。","正覺一念玄解，三世坦然皆平。","非法非律自制，翛然真入圓成。","絶此四句百非，如空無作無依。"]', '["禪師體離無明，煩惱從何处生？","地獄天堂一相，湼槃生死空名。","齊無貪嗔可斷，亦無佛道可成。","衆生與佛平等，自然聖智惺惺。","不爲六塵所染，句句独契無生。","正覺一念玄解，三世坦然皆平。","非法非律自制，翛然真入圓成。","絶此四句百非，如空無作無依。"]', '诗', 'shi', '', NULL, '十四科頭 境照不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('624376b9-44ac-455e-9ec3-32dc9b20ee6b', '十四科頭 運用無礙', '十四科头 運用無礙', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["我今滔滔自在，不羨公王卿宰。","四時猶若金剛，昔樂今常不改。","法寶喻於須彌，智慧廣於澎湃。","不爲八風所牽，亦無精進懈怠。","任性浮沈若顛，散誕蹤橫自在。","遮莫刀劒臨頭，我自安然不采。"]', '["我今滔滔自在，不羨公王卿宰。","四时猶若金剛，昔乐今常不改。","法寶喻於須彌，智慧廣於澎湃。","不爲八风所牽，亦無精進懈怠。","任性浮沈若顛，散誕蹤橫自在。","遮莫刀劒臨头，我自安然不采。"]', '诗', 'shi', '', NULL, '十四科頭 運用無礙 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8ee60b-7d87-4295-bb8c-69c80ded9987', '十四科頭 迷悟不二', '十四科头 迷悟不二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["迷時以空爲色，悟即以色爲空。","迷悟本無差別，色空究竟還同。","愚人喚南作北，智者達無西東。","欲覓如來妙理，常在一念之中。","陽焰本非其水，渴鹿狂趁忩忩。","自身虛假不實，將空更欲覓空。","世人迷倒至甚，如犬吠雷叿叿。","（以上皆見《景德傳燈錄》卷二九）。"]', '["迷时以空爲色，悟即以色爲空。","迷悟本無差別，色空究竟還同。","愚人喚南作北，智者達無西东。","欲覓如来妙理，常在一念之中。","陽焰本非其水，渴鹿狂趁忩忩。","自身虛假不實，將空更欲覓空。","世人迷倒至甚，如犬吠雷叿叿。","（以上皆见《景德傳灯錄》卷二九）。"]', '诗', 'shi', '', NULL, '十四科頭 迷悟不二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4908c8e4-721e-4331-bed8-d45bbc7e2f55', '偈', '偈', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["頓悟心源開寶藏，隱顯靈蹤現真相。","獨行獨坐常巍巍，百億化身無數量。","縱令畐塞滿虛空，看時不見微塵相。","可笑物空無比況，口吐明珠光晃晃。","尋常見說不思議，一語標宗言下當。","（《宗鏡錄》卷九八）。"]', '["頓悟心源开寶藏，隐显靈蹤現真相。","独行独坐常巍巍，百億化身無數量。","縱令畐塞满虛空，看时不见微塵相。","可笑物空無比況，口吐明珠光晃晃。","尋常见说不思議，一語標宗言下當。","（《宗镜錄》卷九八）。"]', '诗', 'shi', '', NULL, '偈 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3265ffd9-7c96-47f9-bc82-72bb97b6bc2e', '預言 一', '預言 一', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["五馬從南來，燕趙起三災。","□□勤修善，得見化城開。","兔子亂三州，萬惡自然收。","東弱西強阿誰愁，欲得世燕南頭。","武安川裏白鷄鳴，百姓遼亂心不寧。","四月八日起鬼兵，冀州城東起長城。","爾來君士面奄青，五月十日滅你名。","冀州城頭君子遊，折尾苟子亂中州，欲得避世黃河頭。","今年天下是亂世，但勤修善自防身。","得安樂，無憂愁，不肯看經心羅錯。","天下遼亂真可留，若得盡門斬賊頭。"]', '["五马從南来，燕趙起三災。","□□勤修善，得见化城开。","兔子亂三州，万惡自然收。","东弱西強阿誰愁，欲得世燕南头。","武安川裏白鷄鳴，百姓遼亂心不寧。","四月八日起鬼兵，冀州城东起长城。","爾来君士面奄青，五月十日滅你名。","冀州城头君子游，折尾苟子亂中州，欲得避世黄河头。","今年天下是亂世，但勤修善自防身。","得安乐，無憂愁，不肯看經心羅錯。","天下遼亂真可留，若得尽门斬賊头。"]', '诗', 'shi', '', NULL, '預言 一 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56fb19b2-e8e9-4c7e-b7e9-35a7df5410a0', '預言 二', '預言 二', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["四月八日游，鬭鷄臺上樗蒲盧。","正見笑，兵不輸，阻雉正見喚兵人人死室粟麥無□□犢合河北脫却角白血五之間遼亂推搭，聖人之間天運迎。","（此篇首有「寶公曰」三字。","中間一段難以點斷）。"]', '["四月八日游，鬭鷄台上樗蒲盧。","正见笑，兵不輸，阻雉正见喚兵人人死室粟麦無□□犢合河北脫却角白血五之间遼亂推搭，聖人之间天運迎。","（此篇首有「寶公曰」三字。","中间一段难以点斷）。"]', '诗', 'shi', '', NULL, '預言 二 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b72bfa4-ba4f-48b3-a017-96d502924e1b', '預言 三', '預言 三', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["禿人今日已定，不須卜於長安。","天坐住汝男津，百官大會千斤肫。"]', '["禿人今日已定，不須卜於长安。","天坐住汝男津，百官大會千斤肫。"]', '诗', 'shi', '', NULL, '預言 三 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f1c02bf-0a45-47b3-9e58-902c61b813db', '預言 四', '預言 四', 'ac297371-319b-4235-ae84-8a21466d9e37', '唐', '["一斗穀夜餉，一疋絹二丈，丁車大牛西南上。","若不信吾語，看先烏東飛，雉北走，空虛匡上見猪狗。","□□□□□□□，日無光，月無影，星辰遼亂入（下缺）。","（以上皆見《沙州文錄》，原題《寶公預言》，據上虞羅氏藏敦煌殘卷。","）（按：寶誌詩，《先秦漢魏晉南北朝詩·梁詩》卷三僅據《南史》、《隋書》收讖詩四則，漏收二則，即《洛陽伽藍記》所載：「大竹箭，不需羽。","東箱屋，急手作。","」《南史》卷六三《王神念傳》載其天臨中讖：「太歲龍，將無理。","蕭經霜，草應死。","餘人散，十八子。","」本書前錄諸詩偈讖言，是否出於唐前，無從確定。","如其《十二時》，《洛陽伽藍記》稱寶公「造《十二辰歌》」，但其真僞，今人頗有爭論，多傾向於非六朝時之作。","〖詳參王重民《敦煌遺書論文集》附錄〗但前錄諸作，即出依託，至遲亦應爲五代以前的作品，故錄收於此。","另《太平廣記》卷一六三引《劉賓客嘉話錄》引「兩角女子」讖一則，《全唐詩》卷八七五已收，不重錄。","）。"]', '["一斗穀夜餉，一疋絹二丈，丁车大牛西南上。","若不信吾語，看先烏东飞，雉北走，空虛匡上见猪狗。","□□□□□□□，日無光，月無影，星辰遼亂入（下缺）。","（以上皆见《沙州文錄》，原題《寶公預言》，據上虞羅氏藏敦煌殘卷。","）（按：寶誌诗，《先秦漢魏晉南北朝诗·梁诗》卷三僅據《南史》、《隋书》收讖诗四則，漏收二則，即《洛陽伽藍記》所載：「大竹箭，不需羽。","东箱屋，急手作。","」《南史》卷六三《王神念傳》載其天臨中讖：「太歲龙，將無理。","蕭經霜，草應死。","餘人散，十八子。","」本书前錄諸诗偈讖言，是否出於唐前，無從確定。","如其《十二时》，《洛陽伽藍記》稱寶公「造《十二辰歌》」，但其真僞，今人頗有爭論，多傾向於非六朝时之作。","〖詳參王重民《敦煌遺书論文集》附錄〗但前錄諸作，即出依託，至遲亦應爲五代以前的作品，故錄收於此。","另《太平廣記》卷一六三引《劉賓客嘉話錄》引「兩角女子」讖一則，《全唐诗》卷八七五已收，不重錄。","）。"]', '诗', 'shi', '', NULL, '預言 四 寶誌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21a736b9-2ee8-40c9-8207-0c0a95355b2c', '讖 一', '讖 一', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["路行跨水復逢羊，（路行者，來也。","跨水者，過海也。","稱逢羊者，洛陽也。","達摩大師從南天竺國過海而來，初到廣州，次普通八年丁未歲人梁國）獨自恓恓（《天聖廣燈錄》、《五燈會元》作「栖栖」）暗渡江。","（獨自者，無伴侶也。","恓恓者，苦恓也。","暗渡江者，梁武帝不悟大理，變容不言。","師知機不契，則潛過江向北魏國也。","）日下可憐雙象馬，（日下者，京都也。","可憐者，好。","雙象馬者，志公傳大士也。","）兩株懶桂（《天聖廣燈錄》、《五燈會元》作「二株嫩桂」）久昌昌。","（兩株者，二木也，二木是林字也。","嫩桂者，少也。","則是少林寺也。","久昌昌者，九年面壁，而出大行佛法也。","）。"]', '["路行跨水复逢羊，（路行者，来也。","跨水者，過海也。","稱逢羊者，洛陽也。","達摩大師從南天竺国過海而来，初到廣州，次普通八年丁未歲人梁国）独自恓恓（《天聖廣灯錄》、《五灯會元》作「栖栖」）暗渡江。","（独自者，無伴侶也。","恓恓者，苦恓也。","暗渡江者，梁武帝不悟大理，变容不言。","師知機不契，則潛過江向北魏国也。","）日下可怜雙象马，（日下者，京都也。","可怜者，好。","雙象马者，志公傳大士也。","）兩株懶桂（《天聖廣灯錄》、《五灯會元》作「二株嫩桂」）久昌昌。","（兩株者，二木也，二木是林字也。","嫩桂者，少也。","則是少林寺也。","久昌昌者，九年面壁，而出大行佛法也。","）。"]', '诗', 'shi', '', NULL, '讖 一 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a5373c2-2509-4546-b42c-4635bea1ae98', '讖 二', '讖 二', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["心中雖吉外頭凶，（心中者，周字也。","外頭凶者，周王無道滅佛法也）川下僧房名不中。","（川下僧房者，俗號僧房爲邑，川下邑爲邕字也。","後周文帝〖陳按：應作武帝〗姓字文，名泰邕。","不中者，後周沙汰滅佛法。","）爲遇毒龍生武子，（毒龍者，武帝父王也。","生武子者，生武帝也）忽逢小鼠寂無窮。","（小鼠者，庚子也。","周武帝庚子崩。","寂無窮者，盡滅無也）。"]', '["心中雖吉外头凶，（心中者，周字也。","外头凶者，周王無道滅佛法也）川下僧房名不中。","（川下僧房者，俗號僧房爲邑，川下邑爲邕字也。","後周文帝〖陳按：應作武帝〗姓字文，名泰邕。","不中者，後周沙汰滅佛法。","）爲遇毒龙生武子，（毒龙者，武帝父王也。","生武子者，生武帝也）忽逢小鼠寂無窮。","（小鼠者，庚子也。","周武帝庚子崩。","寂無窮者，尽滅無也）。"]', '诗', 'shi', '', NULL, '讖 二 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b0465c-a40c-439c-8ed1-3e639a9eac4a', '讖 三', '讖 三', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["路上忽逢深處水，（路上者，李字也。","深水者，淵字也。","唐高祖神堯皇帝姓李名淵也）等閑見虎又逢猪。","（等閑見虎者，寅也，唐高祖戊寅年登位也。","又逢猪者，亥也，高祖丁亥年崩）小小牛兒雖有角，（小小牛兒者，高祖武德四年九月日，有前道士太史令傳奕，先是黃巾黨其所習，遂上表廢佛法事十有一條。","大略而云：釋經是損國破家，未聞益世，請胡佛邪教退還天竺，凡是沙門放歸桑梓，則國家昌泰，李孔教行矣。","高祖納奕奏書，乃下詔問諸沙門曰：「棄父母鬚髭，去君臣花服，利在何間，益在何情？","損益二宜，請動妙釋。","」時有琳法師，上表得延五年。","高祖崩，太宗登位，再興佛法矣。","具如別傳。","言半角者，正當挃觸，而無害即是）清溪龍出總須輸。","清溪者，山名也。","龍者，琳法師護法之龍，能令傳奕等邪見之徒總須伏也。","）。"]', '["路上忽逢深处水，（路上者，李字也。","深水者，淵字也。","唐高祖神堯皇帝姓李名淵也）等闲见虎又逢猪。","（等闲见虎者，寅也，唐高祖戊寅年登位也。","又逢猪者，亥也，高祖丁亥年崩）小小牛兒雖有角，（小小牛兒者，高祖武德四年九月日，有前道士太史令傳奕，先是黄巾黨其所習，遂上表廢佛法事十有一條。","大略而云：釋經是損国破家，未闻益世，請胡佛邪教退還天竺，凡是沙门放归桑梓，則国家昌泰，李孔教行矣。","高祖納奕奏书，乃下詔问諸沙门曰：「棄父母鬚髭，去君臣花服，利在何间，益在何情？","損益二宜，請动妙釋。","」时有琳法師，上表得延五年。","高祖崩，太宗登位，再兴佛法矣。","具如別傳。","言半角者，正當挃觸，而無害即是）清溪龙出總須輸。","清溪者，山名也。","龙者，琳法師護法之龙，能令傳奕等邪见之徒總須伏也。","）。"]', '诗', 'shi', '', NULL, '讖 三 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0131c30b-8a3c-4c82-aafb-c9205da8df5f', '讖 四', '讖 四', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["震旦雖闊無別路，（震旦者，唐國也。","無別路者，唯有一心之法，讓大師化導如此也。","）要假姪（《古尊宿語錄》、《五燈會元》作「兒」）孫脚下（《天聖廣燈錄》作「上」）行。","（姪孫者，今時傳法弟子也）金雞解銜一顆米（《古尊宿語錄》、《五燈會元》作「一粒粟」，金雞者，金州也，讓師是金州人也。","一顆米者，意取道一，江西馬祖名道一。","）供養十方（《古尊宿語錄》）作「什邡」）羅漢僧。","（讓和尚付與道一，故言供養。","十方者，馬和尚是漢州十方縣羅漢寺出家也。","）。"]', '["震旦雖闊無別路，（震旦者，唐国也。","無別路者，唯有一心之法，讓大師化導如此也。","）要假姪（《古尊宿語錄》、《五灯會元》作「兒」）孫脚下（《天聖廣灯錄》作「上」）行。","（姪孫者，今时傳法弟子也）金雞解銜一顆米（《古尊宿語錄》、《五灯會元》作「一粒粟」，金雞者，金州也，讓師是金州人也。","一顆米者，意取道一，江西马祖名道一。","）供養十方（《古尊宿語錄》）作「什邡」）羅漢僧。","（讓和尚付與道一，故言供養。","十方者，马和尚是漢州十方縣羅漢寺出家也。","）。"]', '诗', 'shi', '', NULL, '讖 四 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('707d69d9-9e28-4c17-8dfe-b97e05956111', '讖 五', '讖 五', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["尊勝今藏古，（尊勝者，妙智也。","古者，可大師，本有妙高之性，性被煩惱覆之，未現了，故言藏也。","）無肱亦（《天聖廣燈錄》作「又」）有肱。","（肱者，手也，可大師求法斷臂也。","）龍來方受（《天聖廣燈錄》作「授」）寶，（龍來者，初祖西來也。","方受寶者，二傳法。","）捧物復（《天聖廣燈錄》作「奉物伏」）嫌名。","（捧者，惠也。","本名神光，復過達摩，嫌之，改名言爲惠可。","）。"]', '["尊勝今藏古，（尊勝者，妙智也。","古者，可大師，本有妙高之性，性被煩惱覆之，未現了，故言藏也。","）無肱亦（《天聖廣灯錄》作「又」）有肱。","（肱者，手也，可大師求法斷臂也。","）龙来方受（《天聖廣灯錄》作「授」）寶，（龙来者，初祖西来也。","方受寶者，二傳法。","）捧物复（《天聖廣灯錄》作「奉物伏」）嫌名。","（捧者，惠也。","本名神光，复過達摩，嫌之，改名言爲惠可。","）。"]', '诗', 'shi', '', NULL, '讖 五 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6adb4800-ac46-4db2-a39b-1f0a9b5fab26', '讖 六', '讖 六', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["初首不稱名，（後周第三主己卯之歲，有一居士，不稱姓名，故言不稱名）風狂又有聲。","（風狂者，三祖有風病。","有聲者，遠近皆知有病，故言有聲也。","）人來不喜見，（人來不喜見，患風之形狀）白寶初平平。","（白寶者，玉也。","玉邊作祭，璨字也。","三祖名璨大師。","）。"]', '["初首不稱名，（後周第三主己卯之歲，有一居士，不稱姓名，故言不稱名）风狂又有声。","（风狂者，三祖有风病。","有声者，远近皆知有病，故言有声也。","）人来不喜见，（人来不喜见，患风之形狀）白寶初平平。","（白寶者，玉也。","玉邊作祭，璨字也。","三祖名璨大師。","）。"]', '诗', 'shi', '', NULL, '讖 六 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a02c6219-0247-456c-86a7-a89fccf2d921', '讖 七', '讖 七', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["起自求無（《天聖廣燈錄》作「不」）碍，（有一沙彌，年十四，名道信，來禮拜問：「唯願和尚，教某甲解脫法門。","」故言求無碍）師傅我沒繩。","（師者，三通也。","我沒繩者，既無人縛汝，即是解脫）路上逢僧禮，（路上者，道也。","禮者，信也。","四祖大師名道信）脚下六枝分。","（脚下者，門下也。","四祖下橫出一宗，六枝者，牛頭融禪師等六祖）。"]', '["起自求無（《天聖廣灯錄》作「不」）碍，（有一沙彌，年十四，名道信，来禮拜问：「唯願和尚，教某甲解脫法门。","」故言求無碍）師傅我沒繩。","（師者，三通也。","我沒繩者，既無人縛汝，即是解脫）路上逢僧禮，（路上者，道也。","禮者，信也。","四祖大師名道信）脚下六枝分。","（脚下者，门下也。","四祖下橫出一宗，六枝者，牛头融禪師等六祖）。"]', '诗', 'shi', '', NULL, '讖 七 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4edd0f-ff45-4a38-9c02-28a532562ac8', '讖 八', '讖 八', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["三四全無我，（三四者，七也。","五祖七歲遇道信大師，無人我出家也）隔水受心燈。","（隔水者，五祖於蘄州蘄水得傳四祖心印，故言受心燈。","）尊號過諸量，（過量者，弘字也）逢嗔不起曾（《天聖廣燈錄》作「從嗔不起增」。","不起者，忍字也）。"]', '["三四全無我，（三四者，七也。","五祖七歲遇道信大師，無人我出家也）隔水受心灯。","（隔水者，五祖於蘄州蘄水得傳四祖心印，故言受心灯。","）尊號過諸量，（過量者，弘字也）逢嗔不起曾（《天聖廣灯錄》作「從嗔不起增」。","不起者，忍字也）。"]', '诗', 'shi', '', NULL, '讖 八 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3941802a-6574-41ed-8061-3e2a6f5a3ba0', '讖 九', '讖 九', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["捧（《天聖廣燈錄》作「奉」）物何曾捧，（捧者，惠字）言懃又不懃。","（懃者，能也。","六祖名能）唯書四句偈，（唯書四句偈者，神秀和尚呈四句偈，□能和尚亦呈四句偈，故言四句偈）將（《天聖廣燈錄》作「爲」）對瑞田人。","（瑞田人者，神秀和尚南陽嘉禾縣瑞田人）心裏能藏事，（能藏者懷，則懷信也）說向漢江濱。","（說向者，說法也。","漢江濱者，馬大師漢州人也。","馬大師求佛心印，讓和尚說向道一也）湖波探水月，（湖波者，曹溪也。","探水月者，得也。","讓大師於六祖身邊得傳心印）將照二三人。","（二三者，六。","讓大師傳法弟子六人，言六人者，一道一得心，二智遠得眼，三常浩得眉，四神照得鼻，五坦然得耳，六嚴峻得耳，是爲六人也）。"]', '["捧（《天聖廣灯錄》作「奉」）物何曾捧，（捧者，惠字）言懃又不懃。","（懃者，能也。","六祖名能）唯书四句偈，（唯书四句偈者，神秀和尚呈四句偈，□能和尚亦呈四句偈，故言四句偈）將（《天聖廣灯錄》作「爲」）对瑞田人。","（瑞田人者，神秀和尚南陽嘉禾縣瑞田人）心裏能藏事，（能藏者懷，則懷信也）说向漢江濱。","（说向者，说法也。","漢江濱者，马大師漢州人也。","马大師求佛心印，讓和尚说向道一也）湖波探水月，（湖波者，曹溪也。","探水月者，得也。","讓大師於六祖身邊得傳心印）將照二三人。","（二三者，六。","讓大師傳法弟子六人，言六人者，一道一得心，二智远得眼，三常浩得眉，四神照得鼻，五坦然得耳，六嚴峻得耳，是爲六人也）。"]', '诗', 'shi', '', NULL, '讖 九 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3c2e56-9703-44ea-89fd-193b381fbde1', '讖 十', '讖 十', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["領得[彌勒]（珍勤）（從《天聖廣燈錄》改）語，（領得者，馬大師於讓大師處領語也）離鄉日日敷。","（離鄉者，南方也。","日日者，昌字也。","敷者，演也。","馬大師歸至洪州南昌寺，敷演大教是也）移梁來（《天聖廣燈錄》作「來梁移」）近路，（移梁者，梁都也。","近路者，深州觀察使姓路，遂請大師自虔州南康縣，移入洪州開元寺，故言來近路）余算脚天徒。","（余者，我字也。","從馬大師二十年外，契道者千萬，遍行天下，故言脚天徒）。"]', '["領得[彌勒]（珍勤）（從《天聖廣灯錄》改）語，（領得者，马大師於讓大師处領語也）離乡日日敷。","（離乡者，南方也。","日日者，昌字也。","敷者，演也。","马大師归至洪州南昌寺，敷演大教是也）移梁来（《天聖廣灯錄》作「来梁移」）近路，（移梁者，梁都也。","近路者，深州观察使姓路，遂請大師自虔州南康縣，移入洪州开元寺，故言来近路）余算脚天徒。","（余者，我字也。","從马大師二十年外，契道者千万，遍行天下，故言脚天徒）。"]', '诗', 'shi', '', NULL, '讖 十 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412cdf1c-72cc-4697-8edb-2d0d555f97dc', '讖 十一', '讖 十一', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["艮地生玄旨，（艮地者，東北也。","神秀和尚從五祖下傳一枝法，在北自爲立宗旨也）通尊媚亦尊。","（通尊者，謚號大通禪師也。","媚者，秀也。","亦尊者，三帝所尊敬，故亦尊也）比肩三九（《天聖廣燈錄》作「吼」）族，（比肩者，同學也。","三九族者，十二人也。","秀大師同學十二人）足下一有分。","（從秀和尚足下各分宗旨，南北有異）。"]', '["艮地生玄旨，（艮地者，东北也。","神秀和尚從五祖下傳一枝法，在北自爲立宗旨也）通尊媚亦尊。","（通尊者，謚號大通禪師也。","媚者，秀也。","亦尊者，三帝所尊敬，故亦尊也）比肩三九（《天聖廣灯錄》作「吼」）族，（比肩者，同学也。","三九族者，十二人也。","秀大師同学十二人）足下一有分。","（從秀和尚足下各分宗旨，南北有異）。"]', '诗', 'shi', '', NULL, '讖 十一 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab09ee3d-4568-43c9-8d55-011f6f616ba3', '讖 十二', '讖 十二', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["靈集媿天恩，（靈者，神。","集者，會也。","媿者，荷也。","天恩者，澤也。","神會大師住洛京荷澤寺）生{牙丿=丶}二六人。","（生{牙丿=丶}者，師資也。","二六者，會大師弟子十二人也）法中無氣味，（法中者，佛法也。","會大師傳佛知見，甚深法也。","無氣味者，緣北宗秀大師弟子普寂，於京盛行，通其經教。","當此之時，曹溪宗旨，於彼未而行，故言無氣味也）石上有功勳。","（石上者，秀大師弟子，磨却南宗碑，神秀欲爲六代，何其天之不從，乃得會大師重立實錄，故有功勳）。"]', '["靈集媿天恩，（靈者，神。","集者，會也。","媿者，荷也。","天恩者，澤也。","神會大師住洛京荷澤寺）生{牙丿=丶}二六人。","（生{牙丿=丶}者，師資也。","二六者，會大師弟子十二人也）法中無氣味，（法中者，佛法也。","會大師傳佛知见，甚深法也。","無氣味者，緣北宗秀大師弟子普寂，於京盛行，通其經教。","當此之时，曹溪宗旨，於彼未而行，故言無氣味也）石上有功勳。","（石上者，秀大師弟子，磨却南宗碑，神秀欲爲六代，何其天之不從，乃得會大師重立實錄，故有功勳）。"]', '诗', 'shi', '', NULL, '讖 十二 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c145f6ac-d13b-4175-8a5e-1dd39b8f857f', '讖 十三', '讖 十三', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["本是大蟲勇，（印宗法師本是小乘，喻如大蟲，不是師子）迴（《天聖廣燈錄》作「翻」）成師子談。","（迴者，傳也。","迴小作大，印宗法師禮六祖便悟上乘，是成師子吼）官家封馬嶺，（封者，印也。","馬嶺者，宗也。","印宗曾爲講經法師也）同詳三十三。","（同詳者，同學也。","六祖弟子祥岑等三十三人，祥禪師住於峽山）。"]', '["本是大蟲勇，（印宗法師本是小乘，喻如大蟲，不是師子）迴（《天聖廣灯錄》作「翻」）成師子談。","（迴者，傳也。","迴小作大，印宗法師禮六祖便悟上乘，是成師子吼）官家封马嶺，（封者，印也。","马嶺者，宗也。","印宗曾爲講經法師也）同詳三十三。","（同詳者，同学也。","六祖弟子祥岑等三十三人，祥禪師住於峽山）。"]', '诗', 'shi', '', NULL, '讖 十三 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad958aa-3e94-4300-9495-21691b214772', '讖 十四', '讖 十四', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["八（《天聖廣燈錄》作「九」）女出人倫，（八女者，安字也。","出人倫者，爲國師也。","）八箇絕婚姻。","（個箇者，安字。","絕婚姻者，安徒難爲紹繼之）杇床（《天聖廣燈錄》作「將」）添六脚，（杇床者，老字也。","六脚者，則天、中宗，騰騰坦然圓寂，百五十五年住世，破竈墮和尚六住嵩山，是爲六脚也）心祖衆中尊。","（心祖者，姓也。","安和尚頓悟禪理爲國師，故衆中尊也）。"]', '["八（《天聖廣灯錄》作「九」）女出人倫，（八女者，安字也。","出人倫者，爲国師也。","）八箇絕婚姻。","（個箇者，安字。","絕婚姻者，安徒难爲紹繼之）杇床（《天聖廣灯錄》作「將」）添六脚，（杇床者，老字也。","六脚者，則天、中宗，腾腾坦然圓寂，百五十五年住世，破竈墮和尚六住嵩山，是爲六脚也）心祖衆中尊。","（心祖者，姓也。","安和尚頓悟禪理爲国師，故衆中尊也）。"]', '诗', 'shi', '', NULL, '讖 十四 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a99a4ae-a07a-4ac5-8a32-b3e363b6a64f', '讖 十五', '讖 十五', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["走戊與朝鄰，（走戊者，越字，忠國師是越州人也。","與朝鄰者，爲國師）鵝烏子出身。","（鵝者，鵝州也，今越州是。","烏者，鳴鶴縣也，今諸暨縣是，國師生此縣也）二天雖有感，（二天者，肅宗、代宗二帝也。","有感者，帝禮爲師也）三化寂無塵。","（三化寂無塵者，二帝與國師俱寂也）。"]', '["走戊與朝鄰，（走戊者，越字，忠国師是越州人也。","與朝鄰者，爲国師）鵝烏子出身。","（鵝者，鵝州也，今越州是。","烏者，鳴鹤縣也，今諸暨縣是，国師生此縣也）二天雖有感，（二天者，肅宗、代宗二帝也。","有感者，帝禮爲師也）三化寂無塵。","（三化寂無塵者，二帝與国師俱寂也）。"]', '诗', 'shi', '', NULL, '讖 十五 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cedbcd1e-ef76-404d-84e9-ad02c0afb413', '讖 十六', '讖 十六', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["說小何曾小（《天聖廣燈錄》作「說少何曾少」，希字是也）言流又不流。","（遷字是也）草若除其首，（石頭無草）三四繼門修。","（傳法弟子人數，準其傳法人數，應云十七繼門修也。","○以上十七首，均見《祖堂集》卷二。","《五燈會元》卷一錄其一、其二、其四三首。","《古尊宿語錄》卷一引二首）。"]', '["说小何曾小（《天聖廣灯錄》作「说少何曾少」，希字是也）言流又不流。","（遷字是也）草若除其首，（石头無草）三四繼门修。","（傳法弟子人數，準其傳法人數，應云十七繼门修也。","○以上十七首，均见《祖堂集》卷二。","《五灯會元》卷一錄其一、其二、其四三首。","《古尊宿語錄》卷一引二首）。"]', '诗', 'shi', '', NULL, '讖 十六 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef055837-558d-4f08-af0a-c5b72c5ed4f8', '讖 十七', '讖 十七', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["八月商尊飛有聲，巨福來羣（《天聖廣燈錄》作「祥」）鳥不驚。","懷抱一鷄來赴（《天聖廣燈錄》作「重起」）會，手把龍蛇在兩楹。"]', '["八月商尊飞有声，巨福来羣（《天聖廣灯錄》作「祥」）鸟不驚。","懷抱一鷄来赴（《天聖廣灯錄》作「重起」）會，手把龙蛇在兩楹。"]', '诗', 'shi', '', NULL, '讖 十七 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2306a7eb-8c7f-4fcb-b65c-6247c12f98c0', '讖 十八', '讖 十八', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["寄公席[帽]（脫）（從《天聖廣燈錄》改）權時脫，蚊子之蟲慚小（《天聖廣燈錄》作「足去」）形。","東海象歸披右服（《天聖廣燈錄》作「石脹」），二處蒙恩總不輕。"]', '["寄公席[帽]（脫）（從《天聖廣灯錄》改）權时脫，蚊子之蟲慚小（《天聖廣灯錄》作「足去」）形。","东海象归披右服（《天聖廣灯錄》作「石脹」），二处蒙恩總不轻。"]', '诗', 'shi', '', NULL, '讖 十八 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1804d776-fc19-4b6c-a1fa-135cb1390bae', '讖 十九', '讖 十九', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["日月幷行君（《天聖廣燈錄》作「若」）不動，即無冠子上山行。","更惠一峯添翠岫，玉教人識始知名。"]', '["日月幷行君（《天聖廣灯錄》作「若」）不动，即無冠子上山行。","更惠一峯添翠岫，玉教人識始知名。"]', '诗', 'shi', '', NULL, '讖 十九 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec8f2545-295b-4df9-bfba-9ec50dadf563', '讖 二十', '讖 二十', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["高峰（《天聖廣燈錄》作「嶺」）逢人又脫衣，小蛇雖毒不能爲。","可中井底看（《天聖廣燈錄》作「着」）天近，小是沙彌善大機。","大浪雖高不足知，百年凡木長乾枝。","一鳥南飛却歸北，二人東往却（《天聖廣燈錄》作「復」）還西。"]', '["高峰（《天聖廣灯錄》作「嶺」）逢人又脫衣，小蛇雖毒不能爲。","可中井底看（《天聖廣灯錄》作「着」）天近，小是沙彌善大機。","大浪雖高不足知，百年凡木长乾枝。","一鸟南飞却归北，二人东往却（《天聖廣灯錄》作「复」）還西。"]', '诗', 'shi', '', NULL, '讖 二十 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f652893d-7934-403e-b2db-cf2c896f27ff', '讖 二十一', '讖 二十一', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["可憐明月獨當天，四箇龍兒各自遷。","東西南北奔波去，日頭平上照無邊。"]', '["可怜明月独當天，四箇龙兒各自遷。","东西南北奔波去，日头平上照無邊。"]', '诗', 'shi', '', NULL, '讖 二十一 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d18f30-9148-4d79-8c47-f01b864415cc', '讖 二十二', '讖 二十二', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["鳥來上高堂欲興（《天聖廣燈錄》作「驚」），白雲入地色還青。","天上金龍日月明，東陽海水清不清。","首捧朱（《天聖廣燈錄》作「珠」）輪重復輕，雖無心眼轉惺惺（《天聖廣燈錄》作「醒醒」）。","不見（《天聖廣燈錄》作「具」）耳目善觀聽，身體元無空有形。","不說姓字但驗（《天聖廣燈錄》作「籤」）名，意尋書卷錯開（《天聖廣燈錄》作「看」）經。","口談（《天聖廣燈錄》作「說」）恩幸心無情，或去或來身不停。","（以上七首見《卍續藏經》本《祖庭事苑》卷八，原注：「未見注八首。","」「路上忽逢深處水」一首已見《祖堂集》。","《天聖廣燈錄》卷六收二十三首，缺「初首不稱名」一首，各首均無注）（按：以上諸讖，云爲菩提達磨所作，顯爲依托。","其作者，應爲南宗禪僧，較大的可能爲南嶽懷讓、馬祖道一一系的禪僧。","諸讖中所述事，以石頭希遷、馬祖道一爲最遲，因知作者應爲德宗以後人。","《祖堂集》成書於南唐間，諸讖僞托之下限，疑不遲於唐末。","）。"]', '["鸟来上高堂欲兴（《天聖廣灯錄》作「驚」），白云入地色還青。","天上金龙日月明，东陽海水清不清。","首捧朱（《天聖廣灯錄》作「珠」）輪重复轻，雖無心眼轉惺惺（《天聖廣灯錄》作「醒醒」）。","不见（《天聖廣灯錄》作「具」）耳目善观听，身體元無空有形。","不说姓字但驗（《天聖廣灯錄》作「籤」）名，意尋书卷錯开（《天聖廣灯錄》作「看」）經。","口談（《天聖廣灯錄》作「说」）恩幸心無情，或去或来身不停。","（以上七首见《卍續藏經》本《祖庭事苑》卷八，原注：「未见注八首。","」「路上忽逢深处水」一首已见《祖堂集》。","《天聖廣灯錄》卷六收二十三首，缺「初首不稱名」一首，各首均無注）（按：以上諸讖，云爲菩提達磨所作，显爲依托。","其作者，應爲南宗禪僧，較大的可能爲南嶽懷讓、马祖道一一系的禪僧。","諸讖中所述事，以石头希遷、马祖道一爲最遲，因知作者應爲德宗以後人。","《祖堂集》成书於南唐间，諸讖僞托之下限，疑不遲於唐末。","）。"]', '诗', 'shi', '', NULL, '讖 二十二 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7735c90-b3e9-428a-b956-6e41b7a6c598', '付法頌', '付法頌', '9c4cca9c-4e4c-4818-b8e9-423b3753edb1', '唐', '["吾本來唐國（《景德傳燈錄》作「茲土」），傳教（《景德傳燈錄》作「法」）救迷情。","一花開五葉，結果自然成。","（《南宗頓教最上大乘摩訶般若波羅密經六祖慧能大師於韶州大梵寺施法壇經》）（按：此首亦出唐人依託。","）。"]', '["吾本来唐国（《景德傳灯錄》作「茲土」），傳教（《景德傳灯錄》作「法」）救迷情。","一花开五葉，結果自然成。","（《南宗頓教最上大乘摩訶般若波羅密經六祖慧能大師於韶州大梵寺施法壇經》）（按：此首亦出唐人依託。","）。"]', '诗', 'shi', '', NULL, '付法頌 菩提達摩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7fc8cc-92b9-4071-b316-3395b4c6b1be', '黑兒賦', '黑兒賦', '8602ce78-2fd8-46d9-acb7-b8dec8962400', '唐', '["世有非常人，實惟彼玄士。","稟茲至緇色，內外皆相似。","臥如驪[馬]（牛）（司義祖校記云：「似應作『驪馬』」。","今從《事文類聚》改）𩥇，立似烏牛跱。","忿如鸜鵒鬭，樂似鸕鷀喜。","（下缺。","見中華書局校排本《初學記》卷十九。","宋祝穆《事文類聚後集》卷十八作「朱彥時賦黑兒詩」）（按：彥時時代不明，要爲開元前人。","《新唐書·宰相世系表》有朱彥時，約中唐人，非是。","嚴可均輯《先唐文》收入彥時此篇及劉思真《醜婦賦》，並無確據。","王重民先生《敦煌變文研究》〖刊《中華文史論叢》一九八一年第二輯〗以爲初唐時作，或得其實。","）。"]', '["世有非常人，實惟彼玄士。","稟茲至緇色，內外皆相似。","臥如驪[马]（牛）（司義祖校記云：「似應作『驪马』」。","今從《事文類聚》改）𩥇，立似烏牛跱。","忿如鸜鵒鬭，乐似鸕鷀喜。","（下缺。","见中华书局校排本《初学記》卷十九。","宋祝穆《事文類聚後集》卷十八作「朱彥时賦黑兒诗」）（按：彥时时代不明，要爲开元前人。","《新唐书·宰相世系表》有朱彥时，約中唐人，非是。","嚴可均輯《先唐文》收入彥时此篇及劉思真《醜婦賦》，並無確據。","王重民先生《敦煌变文研究》〖刊《中华文史論叢》一九八一年第二輯〗以爲初唐时作，或得其實。","）。"]', '诗', 'shi', '', NULL, '黑兒賦 朱彥時 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3529d886-454b-44cd-adb6-24c31bd82609', '寶金篇', '寶金篇', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["三十二相眼爲先，次觀頭面要方圓。","相馬不看先代本，一似愚人信口傳。","眼似垂鈴紫色鮮，滿廂凸出不驚然。","白縷貫晴行五百，斑如撒豆勿同看。","面若側墼如鐮背，鼻如金盞可藏拳。","口叉須深牙齒遠，舌如垂劍色如蓮。","口無黑黶須長命，唇似垂廂蓋一般。","食槽寬淨顋無肉，咽尖平而筋有攔。","耳如楊葉裁杉竹，嚥骨高而軟不堅。","八肉分而彎左右，龍會高在上古傳。","項長如鳳須彎曲，鬃毛茸細要如綿。","鬐高膊濶搶風小，臆高胸濶脚前寬。","膝要高而圓似椈，骨細筋麄節要攢。","蹄要圓實須卓立，身形棄闡要平寬。","筋骨彎而須堅密，排鞍肉厚穩金鞍。","三峯穩壓須藏骨，臥如猿落重如山。","鵝鼻曲直須停穩，尾似流星散不連。","膏筋大小須勻壯，下節攢筋緊一錢。","羊髭有距如雞距，能奔解走可行千。","已前貴相三十二，萬中難選一俱全。"]', '["三十二相眼爲先，次观头面要方圓。","相马不看先代本，一似愚人信口傳。","眼似垂鈴紫色鲜，满廂凸出不驚然。","白縷貫晴行五百，斑如撒豆勿同看。","面若側墼如鐮背，鼻如金盞可藏拳。","口叉須深牙齒远，舌如垂劍色如蓮。","口無黑黶須长命，唇似垂廂蓋一般。","食槽寬淨顋無肉，咽尖平而筋有攔。","耳如楊葉裁杉竹，嚥骨高而軟不堅。","八肉分而彎左右，龙會高在上古傳。","項长如鳳須彎曲，鬃毛茸細要如綿。","鬐高膊濶搶风小，臆高胸濶脚前寬。","膝要高而圓似椈，骨細筋麄節要攢。","蹄要圓實須卓立，身形棄闡要平寬。","筋骨彎而須堅密，排鞍肉厚穩金鞍。","三峯穩壓須藏骨，臥如猿落重如山。","鵝鼻曲直須停穩，尾似流星散不連。","膏筋大小須勻壯，下節攢筋緊一錢。","羊髭有距如雞距，能奔解走可行千。","已前貴相三十二，万中难選一俱全。"]', '诗', 'shi', '', NULL, '寶金篇 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51714459-b0b0-4fa2-af10-920c59be3a29', '寶金歌', '寶金歌', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["三十二相眼爲珍，次觀頭面要停勻。","相馬不看先代本，亦似盲人信步行。","眼似垂鈴紫色浸，睛如徹豆要分明。","白縷貫晴行五百，瞳生五彩壽多齡。","鼻紋有字須長壽，如火如公四十春。","壽旋頂門高過眼，鬃毛茸細萬絲分。","面如剝兔腮無肉，鼻如金盞食槽橫。","耳如楊葉根一握，頂長如鳳似雞鳴。","口叉須深牙齒遠，舌如垂劍色蓮形。","口無黑靨須長命，唇似垂箱兩合停。","四大三高兼二小，雙長兩短一灣平。","瘦見肉而肥見骨，視而不懼聽無驚。","八肉彎而分耳後，龍會高而上古聞。","牝騮不欲偏多驟，驊驂蹄嚙善能奔。","首鈎項曲三峯穩，筋麄骨細四蹄輕。","鬐高臆廣平弓手，胸寬膊濶小搶風，頭長腰短雙鳧大，腹垂臁小逆毛生。","踠停寸緊蹄堅實，膝高節近骨筋分。","肋骨彎而須緊密，排鞍肉厚穩鞍輪。","腎代小藏如吊殻，裏囊垂大若懸鈴。","燕骨隱微三山小，胯似琵琶後犬蹲。","尾似流星須放細，鵝鼻曲直汗溝深。","骨筋大小須勻壯，身形棄闡要寬平。","已上毛骨皆是駿，還將駑逸細推尋。","腰凹脊弓焉致遠，麄蹄捺踠豈能奔。","白首黑身須可忌，銀鬃玉項不須欽。","破臉孤蹄真未吉，耳白腰花實是凶。","流鼻繡項休呼美，沙睛環眼莫高稱。","面短骨橫真可惡，眼深無肉不堪親。","槽微口淺多無食，腿粗蹄大實無行。","毛殊旋廣休誇貴，寸長踠軟莫稱駿。","背直尾高休言美，耳大頭肥不足欽。","羊睛象目遙無力，猪胯駞腰不善奔。","龍顱突目天然快，獐頭鹿耳號騅風。","孔中筋現非常相，目有重瞳勿視輕。","溺而似犬真難得，耳毫一尺值千金。","初產無毛稱龍子，骨角雙生亦號龍。","耳微一寸行千里，溺過前足半前程。","羊鬚有距馳三百，距如雞爪日千程。","已前貴相分明載，古典流傳萬世遵。","（自「還將」至「不善奔」一十九句皆惡相，前後皆善相）。"]', '["三十二相眼爲珍，次观头面要停勻。","相马不看先代本，亦似盲人信步行。","眼似垂鈴紫色浸，睛如徹豆要分明。","白縷貫晴行五百，瞳生五彩壽多齡。","鼻紋有字須长壽，如火如公四十春。","壽旋頂门高過眼，鬃毛茸細万絲分。","面如剝兔腮無肉，鼻如金盞食槽橫。","耳如楊葉根一握，頂长如鳳似雞鳴。","口叉須深牙齒远，舌如垂劍色蓮形。","口無黑靨須长命，唇似垂箱兩合停。","四大三高兼二小，雙长兩短一灣平。","瘦见肉而肥见骨，視而不懼听無驚。","八肉彎而分耳後，龙會高而上古闻。","牝騮不欲偏多驟，驊驂蹄嚙善能奔。","首鈎項曲三峯穩，筋麄骨細四蹄轻。","鬐高臆廣平弓手，胸寬膊濶小搶风，头长腰短雙鳧大，腹垂臁小逆毛生。","踠停寸緊蹄堅實，膝高節近骨筋分。","肋骨彎而須緊密，排鞍肉厚穩鞍輪。","腎代小藏如吊殻，裏囊垂大若懸鈴。","燕骨隐微三山小，胯似琵琶後犬蹲。","尾似流星須放細，鵝鼻曲直汗溝深。","骨筋大小須勻壯，身形棄闡要寬平。","已上毛骨皆是駿，還將駑逸細推尋。","腰凹脊弓焉致远，麄蹄捺踠豈能奔。","白首黑身須可忌，銀鬃玉項不須欽。","破臉孤蹄真未吉，耳白腰花實是凶。","流鼻繡項休呼美，沙睛环眼莫高稱。","面短骨橫真可惡，眼深無肉不堪親。","槽微口淺多無食，腿粗蹄大實無行。","毛殊旋廣休誇貴，寸长踠軟莫稱駿。","背直尾高休言美，耳大头肥不足欽。","羊睛象目遙無力，猪胯駞腰不善奔。","龙顱突目天然快，獐头鹿耳號騅风。","孔中筋現非常相，目有重瞳勿視轻。","溺而似犬真难得，耳毫一尺值千金。","初產無毛稱龙子，骨角雙生亦號龙。","耳微一寸行千里，溺過前足半前程。","羊鬚有距驰三百，距如雞爪日千程。","已前貴相分明載，古典流傳万世遵。","（自「還將」至「不善奔」一十九句皆惡相，前後皆善相）。"]', '诗', 'shi', '', NULL, '寶金歌 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de3e99b-3726-4ba3-85fe-01d7a6888898', '王良百一歌 略相 一', '王良百一歌 略相 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["耳小根一握，頭長鼻要寬。","能行三百里，解立四蹄攢。"]', '["耳小根一握，头长鼻要寬。","能行三百里，解立四蹄攢。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b69f6004-2e2d-41e3-98ce-4f57568cd280', '王良百一歌 略相 二', '王良百一歌 略相 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["臆前雖濶備，眼曠腹須平。","項長筋骨促，尾骨短爲精。"]', '["臆前雖濶備，眼曠腹須平。","項长筋骨促，尾骨短爲精。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5992961-c420-47c6-9a09-cd023cde8097', '王良百一歌 略相 三', '王良百一歌 略相 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["鹿耳天然快，獐頭第一強。","蹄輕腰又短，伯樂亦稱良。"]', '["鹿耳天然快，獐头第一強。","蹄轻腰又短，伯乐亦稱良。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8abf892e-01dd-4a24-9f0b-a1212df6b561', '王良百一歌 略相 四', '王良百一歌 略相 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["鼻上紋王字，目中青暈侵。","雖然有筋骨，更要汗溝深。"]', '["鼻上紋王字，目中青暈侵。","雖然有筋骨，更要汗溝深。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d1cdbc-36e6-4968-b8f9-16b3012be156', '王良百一歌 略相 五', '王良百一歌 略相 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["初生無毛者，伯樂號龍駒。","七朝方始起，千匹也應無。"]', '["初生無毛者，伯乐號龙駒。","七朝方始起，千匹也應無。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043cfa29-1433-4dfd-ac54-7fdb96203a58', '王良百一歌 略相 六', '王良百一歌 略相 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["近者雖似小，遠望却成高。","要知深有力，腹上逆生毛。"]', '["近者雖似小，远望却成高。","要知深有力，腹上逆生毛。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af0a2c4-6d1b-4617-beb6-66f7fcbb846a', '王良百一歌 略相 七', '王良百一歌 略相 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["蹄大蹄又軟，腹濶更腰長。","行時無步驟，何必問孫陽。","。"]', '["蹄大蹄又軟，腹濶更腰长。","行时無步驟，何必问孫陽。","。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9618b0b6-d79a-4fb7-9c58-87443790764b', '王良百一歌 略相 八', '王良百一歌 略相 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["口淺不能食，眼深多咬人。","猪膝難任重，焉堪致遠行。"]', '["口淺不能食，眼深多咬人。","猪膝难任重，焉堪致远行。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0a5cc3-0c60-47b9-bb8a-c93d44f1ead8', '王良百一歌 略相 九', '王良百一歌 略相 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["要知有壽馬，唇慢口方停。","好是如羊目，驆良壽亦長。"]', '["要知有壽马，唇慢口方停。","好是如羊目，驆良壽亦长。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32b5c61f-73e0-4dda-a54f-0f39378c59fe', '王良百一歌 略相 十', '王良百一歌 略相 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["不在如龍狀，追風號古來。","目前毛骨駿，未可比駑駘。"]', '["不在如龙狀，追风號古来。","目前毛骨駿，未可比駑駘。"]', '诗', 'shi', '', NULL, '王良百一歌 略相 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed6946d1-c246-4b8d-96fa-2c43238c4846', '王良百一歌 毛病 一', '王良百一歌 毛病 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["項上如生旋，有之不用誇。","環緣不利長，金以號螣蛇。"]', '["項上如生旋，有之不用誇。","环緣不利长，金以號螣蛇。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e424f822-a3b4-4e22-aa02-634a0492c07c', '王良百一歌 毛病 二', '王良百一歌 毛病 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["後有喪門旋，前兼有挾屍。","即君不用蓄，無事亦須疑。"]', '["後有喪门旋，前兼有挾屍。","即君不用蓄，無事亦須疑。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd90799-fef7-45bd-9620-6fe241b00182', '王良百一歌 毛病 三', '王良百一歌 毛病 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["牛額並銜禍，非常害長多。","古人如是說，比事不須歌。"]', '["牛額並銜禍，非常害长多。","古人如是说，比事不須歌。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77e880f-7143-4a03-81b9-b1004bce1b95', '王良百一歌 毛病 四', '王良百一歌 毛病 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["帶劍渾小事，喪門不可當。","滴淚如入口，有福也須防。"]', '["带劍渾小事，喪门不可當。","滴泪如入口，有福也須防。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72fb02c0-8e23-4a15-826d-60e9fa207e99', '王良百一歌 毛病 五', '王良百一歌 毛病 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["黑色耳金白，從來號孝頭。","假饒千里走，奉勸不須留。"]', '["黑色耳金白，從来號孝头。","假饒千里走，奉勸不須留。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6155ebdc-e45e-45c4-bb4f-474f813ac7b4', '王良百一歌 毛病 六', '王良百一歌 毛病 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["背上毛生旋，驢騾亦有之。","只惟鞍貼下，比者是駞屍。"]', '["背上毛生旋，驢騾亦有之。","只惟鞍貼下，比者是駞屍。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d869fae-eccf-4521-bea5-da8f197f69c3', '王良百一歌 毛病 七', '王良百一歌 毛病 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["銜禍口邊衝，時間禍必逢。","古人稱是病，焉敢不言凶。"]', '["銜禍口邊衝，时间禍必逢。","古人稱是病，焉敢不言凶。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e41276-9b6d-4439-94e5-74896af30f24', '王良百一歌 毛病 八', '王良百一歌 毛病 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["眼下毛生旋，遙看似淚痕。","假饒福也病，無禍亦妨人。"]', '["眼下毛生旋，遙看似泪痕。","假饒福也病，無禍亦妨人。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa26ae1-0607-4481-916c-e672b8d406a1', '王良百一歌 毛病 九', '王良百一歌 毛病 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["毛病深知害，妨人在不占。","大都如此類，無禍也宜嫌。"]', '["毛病深知害，妨人在不占。","大都如此類，無禍也宜嫌。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa9c19d-1c6a-4475-8bcf-f1160651e70d', '王良百一歌 毛病 十', '王良百一歌 毛病 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["擔耳駞鬃項，雖然毛病殊。","更若兼鰲尾，有實不如無。"]', '["擔耳駞鬃項，雖然毛病殊。","更若兼鰲尾，有實不如無。"]', '诗', 'shi', '', NULL, '王良百一歌 毛病 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89366072-7de9-42e6-a57b-a4f54eab9474', '王良百一歌 雜忌 一', '王良百一歌 杂忌 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["騎來未得飲，汗解是爲強。","卸鞍面向北，此事最招殃。","。"]', '["騎来未得饮，汗解是爲強。","卸鞍面向北，此事最招殃。","。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3eb187-7ac2-4941-abca-cef64b4a1364', '王良百一歌 雜忌 二', '王良百一歌 杂忌 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["欲出須知此，籠頭莫掛垂。","雖然無大患，驚懼事防爲。"]', '["欲出須知此，籠头莫掛垂。","雖然無大患，驚懼事防爲。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e828b6aa-6fa8-45cf-a8e7-2d005cb31736', '王良百一歌 雜忌 三', '王良百一歌 杂忌 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["面北朝朝餧，形軀漸漸傷。","其中忽有患，有患悔難當。"]', '["面北朝朝餧，形軀漸漸傷。","其中忽有患，有患悔难當。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc62e2b1-935c-4a91-a93b-3ac4a1dd0617', '王良百一歌 雜忌 四', '王良百一歌 杂忌 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["遠來亦忌飽，出去不妨饑。","向水莫許驟，偏傷肺與脾。"]', '["远来亦忌飽，出去不妨饑。","向水莫許驟，偏傷肺與脾。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0072dc82-8975-4501-a3e4-6e178ff3f8a8', '王良百一歌 雜忌 五', '王良百一歌 杂忌 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["濁水休教飲，多饒毛色焦。","時間雖不覺，日內不生臕。"]', '["濁水休教饮，多饒毛色焦。","时间雖不覺，日內不生臕。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f892c65f-84eb-4112-a7e9-72abce990c7c', '王良百一歌 雜忌 六', '王良百一歌 杂忌 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["偏怕腥膻物，仍嫌土作槽。","鼠穿成大穢，更忌艸中毛。"]', '["偏怕腥膻物，仍嫌土作槽。","鼠穿成大穢，更忌艸中毛。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb87dda5-938c-4304-8824-457e952802fc', '王良百一歌 雜忌 七', '王良百一歌 杂忌 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["上山猶許驟，不嶺不宜騎。","必定傷筋骨，能令日漸羸。"]', '["上山猶許驟，不嶺不宜騎。","必定傷筋骨，能令日漸羸。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96db3a9b-6e83-40f2-87b4-6df8e3ee8dc2', '王良百一歌 雜忌 八', '王良百一歌 杂忌 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["近學新醫者，還知此事難。","將鍼宜刺淺，方便更須端。"]', '["近学新醫者，還知此事难。","將鍼宜刺淺，方便更須端。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b7383b-5e67-432b-8171-e31cb4fea802', '王良百一歌 雜忌 九', '王良百一歌 杂忌 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["凡鍼六脈血，不在昔令多。","移時古不止，傷損返如何。"]', '["凡鍼六脈血，不在昔令多。","移时古不止，傷損返如何。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03864b0f-a57b-4d40-a1d8-3408eca5df0d', '王良百一歌 雜忌 十', '王良百一歌 杂忌 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["有病何妨療，無傷血莫鍼。","近來愚學者，此意未知深。"]', '["有病何妨療，無傷血莫鍼。","近来愚学者，此意未知深。"]', '诗', 'shi', '', NULL, '王良百一歌 雜忌 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f93e1c-c6d5-47ca-91a3-44fae4af9c7a', '王良百一歌 眼病 一', '王良百一歌 眼病 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["一切眼昏瘴，皆因熱所傷。","莫令肝臟冷，淚出轉難當。"]', '["一切眼昏瘴，皆因熱所傷。","莫令肝臟冷，泪出轉难當。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421b95fd-a46c-4e7a-a386-0492fe7ee6eb', '王良百一歌 眼病 二', '王良百一歌 眼病 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["黃風有赤脉，白翳忌侵睛。","須抽眼脈血，救療有功能。"]', '["黄风有赤脉，白翳忌侵睛。","須抽眼脈血，救療有功能。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b4dc81-5fb8-4851-8c49-336a6832cb3f', '王良百一歌 眼病 三', '王良百一歌 眼病 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["烏風起肝臟，忽患便青盲。","便是通神妙，除非解損睛。"]', '["烏风起肝臟，忽患便青盲。","便是通神妙，除非解損睛。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd853d8-fd8a-43b8-9aa0-3ee5b95c5e7b', '王良百一歌 眼病 四', '王良百一歌 眼病 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["有瘴多須淚，無令冷藥多。","細辛並地骨，犀角決明和。"]', '["有瘴多須泪，無令冷藥多。","細辛並地骨，犀角決明和。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98268969-86c2-4e40-8f07-5dfad64df7c3', '王良百一歌 眼病 五', '王良百一歌 眼病 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["外瘴須磨點，黃連最能駈。","烏魚骨頗妙，輒莫用珍珠。"]', '["外瘴須磨点，黄連最能駈。","烏鱼骨頗妙，輒莫用珍珠。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a845547a-8528-4169-9e6a-a19aa733d861', '王良百一歌 眼病 六', '王良百一歌 眼病 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["欲療先令暖，仍須使子肝。","防風圓蔚好，去淚得睛寬。","。"]', '["欲療先令暖，仍須使子肝。","防风圓蔚好，去泪得睛寬。","。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e670020e-ba28-44be-b4c5-78c9ee4e2a2c', '王良百一歌 眼病 七', '王良百一歌 眼病 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["不可全憑藥，時聞亦用鍼。","頻抽口鼻血，腦熱勿令侵。"]', '["不可全憑藥，时闻亦用鍼。","頻抽口鼻血，腦熱勿令侵。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd323c16-70f2-4a6f-aaea-b4547e47dc57', '王良百一歌 眼病 八', '王良百一歌 眼病 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["肝病眼睛病，眼昏肝有風。","發來時生暈，嚾烙抵神功。"]', '["肝病眼睛病，眼昏肝有风。","發来时生暈，嚾烙抵神功。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f75ae4c-0d45-4625-a665-15fc22638d9a', '王良百一歌 眼病 九', '王良百一歌 眼病 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["環睛難爲病，侵睛多即驚。","月中騎亦懼，雲內更同盲。"]', '["环睛难爲病，侵睛多即驚。","月中騎亦懼，云內更同盲。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1009f351-eef9-4247-a401-ebc4b75594ff', '王良百一歌 眼病 十', '王良百一歌 眼病 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["卒熱傳肝肺，尫羸也易推。","奈何雙目暗，得較也何時。"]', '["卒熱傳肝肺，尫羸也易推。","奈何雙目暗，得較也何时。"]', '诗', 'shi', '', NULL, '王良百一歌 眼病 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46fe0067-ea7d-46ce-a6d7-a99ae57c5913', '王良百一歌 醫候 一', '王良百一歌 醫候 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["欲知看口色，春季忌於青。","若似秋時候，醫之必得寧。"]', '["欲知看口色，春季忌於青。","若似秋时候，醫之必得寧。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f79189c-1b0a-418d-8c02-dfa14cc896bf', '王良百一歌 醫候 二', '王良百一歌 醫候 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["夏病不食草，口中赤色深。","莫將爲熱療，熱療病難尋。"]', '["夏病不食草，口中赤色深。","莫將爲熱療，熱療病难尋。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40bf18c1-57b8-4df7-be9d-b0ae9605eb50', '王良百一歌 醫候 三', '王良百一歌 醫候 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["秋病口中白，時時喘息粗。","於中帶黑色，肝肺恐應無。"]', '["秋病口中白，时时喘息粗。","於中带黑色，肝肺恐應無。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04dad83a-7100-4b09-bab0-692c78d21427', '王良百一歌 醫候 四', '王良百一歌 醫候 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["冬季口中黑，醫之不必痊。","臥蠶雖有色，而退也無緣。"]', '["冬季口中黑，醫之不必痊。","臥蠶雖有色，而退也無緣。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49953297-ee11-4ffd-aad8-f2575795d920', '王良百一歌 醫候 五', '王良百一歌 醫候 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["大抵怕青黑，兼憂喘息粗。","神功也不救，遲治氣全無。"]', '["大抵怕青黑，兼憂喘息粗。","神功也不救，遲治氣全無。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d0d79b8-ac40-42c5-b61e-5deec1da314b', '王良百一歌 醫候 六', '王良百一歌 醫候 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["肺病多方療，心傷鶻骨抽。","目前雖得效，已後發無休。"]', '["肺病多方療，心傷鶻骨抽。","目前雖得效，已後發無休。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81cb28ea-36a9-4de8-acb9-3f161773ceba', '王良百一歌 醫候 七', '王良百一歌 醫候 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["鼻內出膿血，如加氣轉抽。","豈堪連背硬，何用更開喉。"]', '["鼻內出膿血，如加氣轉抽。","豈堪連背硬，何用更开喉。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45041b04-fb15-4f49-99ea-c2d4dfae1995', '王良百一歌 醫候 八', '王良百一歌 醫候 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["肺病休疑冷，猩膻不可爲。","但將凉藥療，莫使小猪脂。"]', '["肺病休疑冷，猩膻不可爲。","但將凉藥療，莫使小猪脂。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c961af19-c4a4-4a9e-a902-2f11aaa16026', '王良百一歌 醫候 九', '王良百一歌 醫候 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["天門還治肺，地骨也醫肝。","心熱黃芩妙，人參性不寒。"]', '["天门還治肺，地骨也醫肝。","心熱黄芩妙，人參性不寒。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73759799-65e0-4b93-a7e7-e2c1f277db2d', '王良百一歌 醫候 十', '王良百一歌 醫候 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["前面熱未退，腰胯却行遲。","是熱須醫熱，少將冷藥醫。"]', '["前面熱未退，腰胯却行遲。","是熱須醫熱，少將冷藥醫。"]', '诗', 'shi', '', NULL, '王良百一歌 醫候 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ea3b5a-92bf-4f00-bc1e-b247801b3e46', '王良百一歌 起臥', '王良百一歌 起臥', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330eac82-0473-45f5-a4be-c24524bd2f6e', '王良百一歌 起臥 一', '王良百一歌 起臥 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["脾寒令肉顫，胃冷吐清涎。","但鍼脾上穴，暖胃藥爲先。"]', '["脾寒令肉顫，胃冷吐清涎。","但鍼脾上穴，暖胃藥爲先。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0fba154-a861-4a22-9878-d7f84c293bb6', '王良百一歌 起臥 二', '王良百一歌 起臥 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["擈尾褰唇痛，起臥四蹄攤。","頻頻覤膁上，冷熱氣相干。"]', '["擈尾褰唇痛，起臥四蹄攤。","頻頻覤膁上，冷熱氣相干。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1cfb8f-2cda-4a85-9650-a3bd4f3c577c', '王良百一歌 起臥 三', '王良百一歌 起臥 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["起臥無時度，將身似狗蹲。","腸中如糞結，巴豆最爲珍。"]', '["起臥無时度，將身似狗蹲。","腸中如糞結，巴豆最爲珍。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad4a6c1-c305-48f3-93bb-bb527f648290', '王良百一歌 起臥 四', '王良百一歌 起臥 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["若作如斯候，切在細推尋。","如逢腎脈上，多應腸入陰。"]', '["若作如斯候，切在細推尋。","如逢腎脈上，多應腸入陰。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3117f15a-664f-4f31-96d2-5d42afdfe7d4', '王良百一歌 起臥 五', '王良百一歌 起臥 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["識得尋常病，便須用橘皮。","檳榔爲第一，蔥油最相宜。"]', '["識得尋常病，便須用橘皮。","檳榔爲第一，蔥油最相宜。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('137054a7-f569-4240-8ea6-a853b6654d86', '王良百一歌 起臥 六', '王良百一歌 起臥 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["止痛當歸妙，牽牛芍藥和。","生薑宜剩使，滑石勿令多。"]', '["止痛當归妙，牽牛芍藥和。","生薑宜剩使，滑石勿令多。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a621bbf-52b9-4408-b401-d21cbcb0a593', '王良百一歌 起臥 七', '王良百一歌 起臥 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["治脾人間妙，鍼脾第一功。","目前兼惡急，氣脈當時通。"]', '["治脾人间妙，鍼脾第一功。","目前兼惡急，氣脈當时通。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a310ed1b-454d-4981-840d-215126255338', '王良百一歌 起臥 八', '王良百一歌 起臥 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["尿血還緣熱，風虛結澁爲。","秦艽能治療，通利大黃奇。"]', '["尿血還緣熱，风虛結澁爲。","秦艽能治療，通利大黄奇。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8206a58-28ef-44d6-bc2a-9b621bbc0621', '王良百一歌 起臥 九', '王良百一歌 起臥 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["忽傷糞如水，赤黃氣息腥。","饒醫能用藥，口色怕微青。"]', '["忽傷糞如水，赤黄氣息腥。","饒醫能用藥，口色怕微青。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e680b0e-b103-448c-9321-48f33b65a796', '王良百一歌 起臥 十', '王良百一歌 起臥 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["若還退草料，腹中虛氣鳴。","大似腸黃候，脾家氣不勻。"]', '["若還退草料，腹中虛氣鳴。","大似腸黄候，脾家氣不勻。"]', '诗', 'shi', '', NULL, '王良百一歌 起臥 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c182d225-0293-4293-b0f8-4d93dc39f7b7', '王良百一歌 療風 一', '王良百一歌 療风 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["有傷即爲急，無傷呼爲慢。","先鍼喉脈血，亦須先由汗。"]', '["有傷即爲急，無傷呼爲慢。","先鍼喉脈血，亦須先由汗。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d4ae75b-206e-45a3-aed9-21d4e98398a8', '王良百一歌 療風 二', '王良百一歌 療风 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["尾揭遍身硬，耳腎閃骨生。","此風從後得，暖處勿吹驚。"]', '["尾揭遍身硬，耳腎閃骨生。","此风從後得，暖处勿吹驚。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5d5b67-7f40-4eef-a99d-29f727d94e9a', '王良百一歌 療風 三', '王良百一歌 療风 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["病見從前得，斯須便過關。","大風烙最妙，入口下應難。"]', '["病见從前得，斯須便過关。","大风烙最妙，入口下應难。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c8e5a83-826f-4885-8e2a-6f225d9c2617', '王良百一歌 療風 四', '王良百一歌 療风 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["四脚難移動，一邊汗出微。","口中時吐沫，見此莫生疑。"]', '["四脚难移动，一邊汗出微。","口中时吐沫，见此莫生疑。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a91409-09e1-463e-9234-f1f4584809d1', '王良百一歌 療風 五', '王良百一歌 療风 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["不獨如斯狀，忽然後脚遲。","盡知呼脾冷，卒急也難醫。","。"]', '["不独如斯狀，忽然後脚遲。","尽知呼脾冷，卒急也难醫。","。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5229e7-9f61-40b4-b2ed-b4e005d0ea89', '王良百一歌 療風 六', '王良百一歌 療风 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["是藥皆治病，唯風卻要虵。","防風並半夏，最急是天麻。"]', '["是藥皆治病，唯风卻要虵。","防风並半夏，最急是天麻。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b9073a5-0fe0-4563-880c-020f323ff612', '王良百一歌 療風 七', '王良百一歌 療风 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["治療皆憑藥，就中風也難。","七朝疑似退，火烙大無端。"]', '["治療皆憑藥，就中风也难。","七朝疑似退，火烙大無端。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36187f9c-79bd-4b91-9342-db084cd63da7', '王良百一歌 療風 八', '王良百一歌 療风 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["歇汗風饒痒，爲瘡急㿋多。","肺風多揩擦，疥癩即相和。"]', '["歇汗风饒痒，爲瘡急㿋多。","肺风多揩擦，疥癩即相和。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff880ee6-94ad-41c1-af90-020b4f9264e0', '王良百一歌 療風 九', '王良百一歌 療风 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["花蛇及乾蝎，亦療腦旋風。","烏頭勿單使，麻黃更要芎。"]', '["花蛇及乾蝎，亦療腦旋风。","烏头勿單使，麻黄更要芎。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2f50cf-5bec-4368-936c-5496a6474c7a', '王良百一歌 療風 十', '王良百一歌 療风 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["有風切忌驚，角耳最爲精。","漢椒並附子，相合耳中傾。"]', '["有风切忌驚，角耳最爲精。","漢椒並附子，相合耳中傾。"]', '诗', 'shi', '', NULL, '王良百一歌 療風 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbea1bd-500a-4b38-a953-69dbda6587e8', '王良百一歌 筋骨 一', '王良百一歌 筋骨 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["膊痛緣騎苦，蹄傷敗血攻。","痛時鍼且妙，蹄損火能通。"]', '["膊痛緣騎苦，蹄傷敗血攻。","痛时鍼且妙，蹄損火能通。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959876ec-ce4c-40f0-aa1f-aef151bc7f5b', '王良百一歌 筋骨 二', '王良百一歌 筋骨 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["膝骨難任痛，行時脚失多。","無端鍼脈血，得效也蹉跎。"]', '["膝骨难任痛，行时脚失多。","無端鍼脈血，得效也蹉跎。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd967ec-c5b7-452d-b491-ed701cbfff7c', '王良百一歌 筋骨 三', '王良百一歌 筋骨 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["子骨連蹄痛，多應是物傷。","烙蹄蹄不發，漸漸骨開張。"]', '["子骨連蹄痛，多應是物傷。","烙蹄蹄不發，漸漸骨开張。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a087378c-7575-43b6-94f4-ee293a3aeec5', '王良百一歌 筋骨 四', '王良百一歌 筋骨 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["失節莫交頻，鹿節黃水成。","假饒用火烙，滑石鎮長盈。"]', '["失節莫交頻，鹿節黄水成。","假饒用火烙，滑石鎮长盈。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c377b21-3435-4dcc-81a9-fa0dd26adbe7', '王良百一歌 筋骨 五', '王良百一歌 筋骨 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["但是筋骨痛，皆因傷損爲。","於中硯子骨，末後不通醫。"]', '["但是筋骨痛，皆因傷損爲。","於中硯子骨，末後不通醫。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de74ac7d-866f-466d-8bcc-d527a325a5aa', '王良百一歌 筋骨 六', '王良百一歌 筋骨 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["食槽脹雖烙，多緣腑病生。","胃翻加止沫，何藥效能成。"]', '["食槽脹雖烙，多緣腑病生。","胃翻加止沫，何藥效能成。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31701e52-5212-4341-9be4-fbede55f3998', '王良百一歌 筋骨 七', '王良百一歌 筋骨 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["小胯骨若痛，牽連雁翅疼。","從鍼須得穴，用藥更持鋒。"]', '["小胯骨若痛，牽連雁翅疼。","從鍼須得穴，用藥更持鋒。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbfcd7c-be87-43cf-b728-65ab1d3349ae', '王良百一歌 筋骨 八', '王良百一歌 筋骨 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["曲池鵝鼻骨，脹時不在鍼。","芸臺並紫葛，巴豆最功深。"]', '["曲池鵝鼻骨，脹时不在鍼。","芸台並紫葛，巴豆最功深。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7cfb19-bfe0-49b4-a598-1868caf1288d', '王良百一歌 筋骨 九', '王良百一歌 筋骨 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["附骨侵於膝，走驟多饒失。","火烙意還粗，藥消爲第一。"]', '["附骨侵於膝，走驟多饒失。","火烙意還粗，藥消爲第一。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700dbc34-8f7b-45b9-9064-8b2e25e52113', '王良百一歌 筋骨 十', '王良百一歌 筋骨 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["筋脹用猪腦，冷藥用蛇牀。","細辛並藁木，米醋及生薑。","。"]', '["筋脹用猪腦，冷藥用蛇牀。","細辛並藁木，米醋及生薑。","。"]', '诗', 'shi', '', NULL, '王良百一歌 筋骨 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5932f85-936b-4915-a1ea-322760fe7b7d', '王良百一歌 療黃 一', '王良百一歌 療黄 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["頭悶忽啣韁，此即是心黃。","先須用火烙，時下得安康。"]', '["头悶忽啣韁，此即是心黄。","先須用火烙，时下得安康。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea91169d-376c-48b0-a598-7321265f38dc', '王良百一歌 療黃 二', '王良百一歌 療黄 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["胸黃忽腫硬，未可用鍼鍼。","須使消黃藥，無令痛所侵。"]', '["胸黄忽腫硬，未可用鍼鍼。","須使消黄藥，無令痛所侵。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec61c3ef-a19a-4cd1-88cb-6d34ec9cccca', '王良百一歌 療黃 三', '王良百一歌 療黄 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["偏次黃雖少，還緣積熱成。","嘗聞連五臟，根向肺中生。"]', '["偏次黄雖少，還緣積熱成。","嘗闻連五臟，根向肺中生。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('919f7776-d31c-45d9-8ebd-f701dcd1e56a', '王良百一歌 療黃 四', '王良百一歌 療黄 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["喉內若生黃，此病實難當。","藥鍼但少效，向裏結成囊。"]', '["喉內若生黄，此病實难當。","藥鍼但少效，向裏結成囊。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('562ad68e-9307-46bc-8235-ff2acb1c237e', '王良百一歌 療黃 五', '王良百一歌 療黄 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["急慢腸黃候，患時俱一般。","慢時一月多，急則當時間。"]', '["急慢腸黄候，患时俱一般。","慢时一月多，急則當时间。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611f7248-0fa8-4b11-a757-51cbcfa64e61', '王良百一歌 療黃 六', '王良百一歌 療黄 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["腎黃腎脈腫，積冷致如然。","還須熁腰上，以此出頑涎。"]', '["腎黄腎脈腫，積冷致如然。","還須熁腰上，以此出頑涎。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb59d25-e4bf-4d48-b6a7-17e9dd4b111b', '王良百一歌 療黃 七', '王良百一歌 療黄 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["水黃連帶脈，虛腫在皮膚。","先用火鍼治，消時膿出餘。"]', '["水黄連带脈，虛腫在皮膚。","先用火鍼治，消时膿出餘。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('874e0f98-98c5-4e7e-86a9-50119c7226ba', '王良百一歌 療黃 八', '王良百一歌 療黄 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["膁黃不用鍼，塗藥妙能深。","涓石並葶藶，橘皮使蔚金。"]', '["膁黄不用鍼，塗藥妙能深。","涓石並葶藶，橘皮使蔚金。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2276c6fe-5210-4043-8ddc-932352d5e257', '王良百一歌 療黃 九', '王良百一歌 療黄 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["騾馬緣風熱，因此作妳黃。","塗藥教駒匝，切恐結成囊。"]', '["騾马緣风熱，因此作妳黄。","塗藥教駒匝，切恐結成囊。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46bd0d68-dbc5-4b66-a531-e53265368475', '王良百一歌 療黃 十', '王良百一歌 療黄 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["一切黃虛腫，多緣積熱生。","宜抽喉脉血，諸毒不能成。"]', '["一切黄虛腫，多緣積熱生。","宜抽喉脉血，諸毒不能成。"]', '诗', 'shi', '', NULL, '王良百一歌 療黃 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19c4eafe-10a3-4793-a2dc-3074e8b095d7', '王良百一歌 瘡痍 一', '王良百一歌 瘡痍 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["竹節療膊瘡，骨鑽亦難當。","若塗先用洗，欲使洗鹽湯。"]', '["竹節療膊瘡，骨鑽亦难當。","若塗先用洗，欲使洗鹽湯。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e3b3ec6-2d93-4a9f-bce1-df2e26b7cce3', '王良百一歌 瘡痍 二', '王良百一歌 瘡痍 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["貼瘡須用藥，艾炙且令焦。","乾姜將入內，根出始方消。"]', '["貼瘡須用藥，艾炙且令焦。","乾姜將入內，根出始方消。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11a6c3fa-3444-4d48-9ae5-a8f01cb05a81', '王良百一歌 瘡痍 三', '王良百一歌 瘡痍 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["疳瘡生眼畔，疳血化爲蟲。","即漸侵於腦，和睛變作膿。"]', '["疳瘡生眼畔，疳血化爲蟲。","即漸侵於腦，和睛变作膿。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f0496c-8501-4c3d-bdaa-269667cbea87', '王良百一歌 瘡痍 四', '王良百一歌 瘡痍 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["口內忽生涎，心臟熱如然。","有瘡須用藥，包藥使綿纏。","。"]', '["口內忽生涎，心臟熱如然。","有瘡須用藥，包藥使綿纏。","。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57a0651-27a5-451f-9216-5d40d515da71', '王良百一歌 瘡痍 五', '王良百一歌 瘡痍 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["肺毒若生瘡，醫之要肺涼。","貼藥雖宜洗，可用甘草湯。"]', '["肺毒若生瘡，醫之要肺涼。","貼藥雖宜洗，可用甘草湯。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2331dc-0727-462c-a002-733c2cba6628', '王良百一歌 瘡痍 六', '王良百一歌 瘡痍 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["斷踠緣風血，燥蹄亦一般。","麝香葶藶子，貫衆及黃丹。"]', '["斷踠緣风血，燥蹄亦一般。","麝香葶藶子，貫衆及黄丹。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d0c11af-52d3-4895-9018-3a2e546b3110', '王良百一歌 瘡痍 七', '王良百一歌 瘡痍 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["冷病緣草結，膿多瘡口寒。","乳香幷附子，貼此始應看。"]', '["冷病緣草結，膿多瘡口寒。","乳香幷附子，貼此始應看。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be38a1d-1c6e-4eee-941a-c71ae8b536f3', '王良百一歌 瘡痍 八', '王良百一歌 瘡痍 八', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["疥癬深秋旺，爪瘡盛夏多。","都緣風血聚，忙療莫蹉跎。"]', '["疥癬深秋旺，爪瘡盛夏多。","都緣风血聚，忙療莫蹉跎。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 八 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2acc028-83a0-4cfb-ac02-5e364ef3e564', '王良百一歌 瘡痍 九', '王良百一歌 瘡痍 九', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["血躁連蹄腫，筋風血作膿。","蕪荑鶴風妙，能殺此般蟲。"]', '["血躁連蹄腫，筋风血作膿。","蕪荑鹤风妙，能殺此般蟲。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 九 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('701bb829-860d-4b88-b54f-a6733e11a3b2', '王良百一歌 瘡痍 十', '王良百一歌 瘡痍 十', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["一切破損瘡，勿令口自傷。","㿉瘡難治療，客風須是防。"]', '["一切破損瘡，勿令口自傷。","㿉瘡难治療，客风須是防。"]', '诗', 'shi', '', NULL, '王良百一歌 瘡痍 十 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4ff2a6-30a1-4a77-82a9-48f9bdbcff82', '王良百一歌 齒歲 一', '王良百一歌 齒歲 一', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["齒有數般蒼，教伊識不妨。","莫言爲小事，識得大賢良。"]', '["齒有數般蒼，教伊識不妨。","莫言爲小事，識得大賢良。"]', '诗', 'shi', '', NULL, '王良百一歌 齒歲 一 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5222910-66e0-4dc1-b3d9-f6512576f315', '王良百一歌 齒歲 二', '王良百一歌 齒歲 二', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["黑白一齊全，生來始八年。","中間初似破，十二歲無偏。"]', '["黑白一齊全，生来始八年。","中间初似破，十二歲無偏。"]', '诗', 'shi', '', NULL, '王良百一歌 齒歲 二 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42db40f4-5a08-48aa-82ca-07a6a8b7759c', '王良百一歌 齒歲 三', '王良百一歌 齒歲 三', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["齒如十二月，𮪃牙象四時。","二十四氣足，伯樂視爲規。"]', '["齒如十二月，𮪃牙象四时。","二十四氣足，伯乐視爲規。"]', '诗', 'shi', '', NULL, '王良百一歌 齒歲 三 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc562ff-3230-4dd0-8441-de65c3142459', '王良百一歌 齒歲 四', '王良百一歌 齒歲 四', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["四齒不曾退，年已只似駒。","但看邊畔者，咬得臼還殊。"]', '["四齒不曾退，年已只似駒。","但看邊畔者，咬得臼還殊。"]', '诗', 'shi', '', NULL, '王良百一歌 齒歲 四 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a57e4a-870a-440e-823f-563ff15c2093', '王良百一歌 齒歲 五', '王良百一歌 齒歲 五', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["向南馬齒口，野放咬山多。","區臼雖先破，莫言齒歲過。"]', '["向南马齒口，野放咬山多。","區臼雖先破，莫言齒歲過。"]', '诗', 'shi', '', NULL, '王良百一歌 齒歲 五 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d97365e-0e91-4a20-b139-26b5f9292588', '王良百一歌 齒歲 六', '王良百一歌 齒歲 六', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["黃區將欲盡，黑白以全無。","上下齒更展，十二歲應餘。"]', '["黄區將欲尽，黑白以全無。","上下齒更展，十二歲應餘。"]', '诗', 'shi', '', NULL, '王良百一歌 齒歲 六 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b2d4b5-b251-469b-8a78-e946cd340e8a', '王良百一歌 齒歲 七', '王良百一歌 齒歲 七', '8612f763-3ae7-40b5-b741-eca869ade8ad', '唐', '["𮪃牙初出肉，俗言五六春。","至老或不生，須憑區臼真。","（以上均見宛委山堂本《說郛》弓一○七徐成《相馬書》）（〖1〗《舊唐書·經籍志》子部農家類著錄：「《相馬經》，又二卷，徐成等撰。","」）（〖2〗《新唐書·藝文志》子部農家類著錄：「徐成等《相馬經》二卷。","」〖3〗《太平御覽》卷八九六引《伯樂相馬經》云：「江淮津督徐成字子長，兄弟蒙寵於府君，治馬方以報，千金不傳，號《淮津方》。","」〖4〗今人王毓瑚《中國農學書錄》云：「據現有的線索推測，〖徐成〗極可能是唐代人。","《說郛》收的有一種徐咸的《相馬書》，『咸』、『成』二字字形相近，或者就是此書。","」今按：《鄭堂讀書記補逸》謂徐咸爲宋人，今人編《中國叢書綜錄》從之。","核以文獻，尚無明證。","《說郛》收此書於陸龜蒙《耒耜經》、傅肱《蟹譜》之間，卷首署「代郡徐咸」，不言時代。","「代郡」非宋時地名。","兩《唐志》既已著錄此書，其時代當在開元以前。","《伯樂相馬經》見載於《隋書·經籍志》五行類，《舊唐志》錄此書於隋諸葛穎之前，據此二證，頗疑成爲隋前人。","但《隋志》不錄此書，至《舊唐志》始見收，終不能排除其爲唐人的可能性。","今收入先宋詩，以俟考定。","）。"]', '["𮪃牙初出肉，俗言五六春。","至老或不生，須憑區臼真。","（以上均见宛委山堂本《说郛》弓一○七徐成《相马书》）（〖1〗《旧唐书·經籍志》子部農家類著錄：「《相马經》，又二卷，徐成等撰。","」）（〖2〗《新唐书·藝文志》子部農家類著錄：「徐成等《相马經》二卷。","」〖3〗《太平御覽》卷八九六引《伯乐相马經》云：「江淮津督徐成字子长，兄弟蒙寵於府君，治马方以報，千金不傳，號《淮津方》。","」〖4〗今人王毓瑚《中国農学书錄》云：「據現有的線索推測，〖徐成〗極可能是唐代人。","《说郛》收的有一種徐咸的《相马书》，『咸』、『成』二字字形相近，或者就是此书。","」今按：《鄭堂读书記補逸》謂徐咸爲宋人，今人編《中国叢书綜錄》從之。","核以文獻，尚無明證。","《说郛》收此书於陸龟蒙《耒耜經》、傅肱《蟹譜》之间，卷首署「代郡徐咸」，不言时代。","「代郡」非宋时地名。","兩《唐志》既已著錄此书，其时代當在开元以前。","《伯乐相马經》见載於《隋书·經籍志》五行類，《旧唐志》錄此书於隋諸葛穎之前，據此二證，頗疑成爲隋前人。","但《隋志》不錄此书，至《旧唐志》始见收，終不能排除其爲唐人的可能性。","今收入先宋诗，以俟考定。","）。"]', '诗', 'shi', '', NULL, '王良百一歌 齒歲 七 徐成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8715e4-abc8-4c5b-897b-f692d7c26561', '還丹歌', '還丹歌', 'be48b37b-76b4-45c7-86dc-45550f937fca', '唐', '["北方正氣爲河車，東方甲乙爲金砂。","兩情含養歸一體，朱省調養生金華。","金華生出天地寶，人會此言真正道。","子稱虎，卯爲龍，龍虎相生自合同。","龍居震位當其八，虎數元生在一宮。","採有日，取有時，世人用之而不知。","收取氣候若差錯，萬般工力徒勞施。","至神至聖極容易，先向宮中求鼎器。","溫養火候審陰陽，安排鑪室須擇地。","不得地，莫妄爲，切須隱密審護持。","保守莫洩天地機，此藥變化不思議。","陽真砂，陰真汞，時人求之莫妄動。","無質生質是還丹，凡汞凡砂不勞弄。","（見《道藏·洞真部·玉訣類》陳摶《陰真君還丹歌注》）（按：陰真君即陰長生，爲漢時神仙，詳《太平廣記》卷八引《引仙傳》。","此首當發依託。","宋董逌《廣川書跋》卷八載李貽孫書陰真人詩，當即此首，知其應爲中唐以前之作。","）。"]', '["北方正氣爲河车，东方甲乙爲金砂。","兩情含養归一體，朱省調養生金华。","金华生出天地寶，人會此言真正道。","子稱虎，卯爲龙，龙虎相生自合同。","龙居震位當其八，虎數元生在一宮。","採有日，取有时，世人用之而不知。","收取氣候若差錯，万般工力徒勞施。","至神至聖極容易，先向宮中求鼎器。","溫養火候審陰陽，安排鑪室須擇地。","不得地，莫妄爲，切須隐密審護持。","保守莫洩天地機，此藥变化不思議。","陽真砂，陰真汞，时人求之莫妄动。","無質生質是還丹，凡汞凡砂不勞弄。","（见《道藏·洞真部·玉訣類》陳摶《陰真君還丹歌注》）（按：陰真君即陰长生，爲漢时神仙，詳《太平廣記》卷八引《引仙傳》。","此首當發依託。","宋董逌《廣川书跋》卷八載李貽孫书陰真人诗，當即此首，知其應爲中唐以前之作。","）。"]', '诗', 'shi', '', NULL, '還丹歌 陰真君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42d3e232-2dd1-4d79-b2df-16d1f7b3c2fc', '登天台', '登天台', '122bd022-490d-4f4c-a481-6df092b3d4de', '唐', '["高就山上山，山中白雲閑。","瀑布低頭看，青天舉手扳。","石橋橫海外，風笛落人間。","不見紅塵客，時時鶴往還。","（見《四庫珍本初集》本《天台集·拾遺》）（按：葛諦晉前神仙，見《太平廣記》卷七十一引《神仙傳》。","此首五律顯爲齊梁以後人依託。","）。"]', '["高就山上山，山中白云闲。","瀑布低头看，青天舉手扳。","石橋橫海外，风笛落人间。","不见紅塵客，时时鹤往還。","（见《四庫珍本初集》本《天台集·拾遺》）（按：葛諦晉前神仙，见《太平廣記》卷七十一引《神仙傳》。","此首五律显爲齊梁以後人依託。","）。"]', '诗', 'shi', '', NULL, '登天台 葛玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e2fcde-729e-4660-94b3-0269a3931e48', '醜婦賦', '醜婦賦', '77d8c3b3-5eb7-40ff-bcad-aebc37e054a0', '唐', '["人皆得令室，我命獨何[咎]（吝）（從安刻本改）。","不遇姜任德，正值醜惡婦。","才質陋且儉，姿容劇嫫母。","鹿頭獼猴面，推額復出口。","折頞靨樓鼻，兩眼䫜（一交切）如臼。","膚如老桑皮，耳如側兩手。","頭如研米槌，髮如掘掃帚。","惡觀醜儀容，不媚似鋪首。","闇鈍拙梳髻，刻畫又更醜。","妝頰如狗舐，額上獨偏厚。","朱脣如踏血，畫眉如鼠負。","傅粉堆頤下，面中不徧有。","領如鹽豉囊，袖如常拭釜。","履中如和泥，爪甲長有垢。","脚皸可容箸，熟視今人嘔。","（見《初學記》卷十九）。"]', '["人皆得令室，我命独何[咎]（吝）（從安刻本改）。","不遇姜任德，正值醜惡婦。","才質陋且儉，姿容劇嫫母。","鹿头獼猴面，推額复出口。","折頞靨楼鼻，兩眼䫜（一交切）如臼。","膚如老桑皮，耳如側兩手。","头如研米槌，髮如掘掃帚。","惡观醜儀容，不媚似鋪首。","闇鈍拙梳髻，刻畫又更醜。","妝頰如狗舐，額上独偏厚。","朱脣如踏血，畫眉如鼠負。","傅粉堆頤下，面中不徧有。","領如鹽豉囊，袖如常拭釜。","履中如和泥，爪甲长有垢。","脚皸可容箸，熟視今人嘔。","（见《初学記》卷十九）。"]', '诗', 'shi', '', NULL, '醜婦賦 劉思真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ec552d-9a14-42b5-9c1b-882a209febfc', '失父零丁', '失父零丁', 'a7ddee0b-4978-42d9-bc86-892f84b9dc47', '唐', '["敬白諸君行路者，敢告重罪自爲積。","惡致災交天困我，今月七日失阿爹。","念此酷毒可痛傷，當以重幣（重）用相賞，請爲諸君說事狀。","我父軀體與衆異，脊背傴僂捲如胾。","脣吻參差不相值，此其庶形何能備。","請復重陳其面目，鴟頭鵠頸獦狗啄，眼淚鼻涕相追逐，吻中含納無牙齒，食不能嚼左右蹉。","[□]似西域[□]駱駞。","請復重陳其形骸，爲人雖長甚細材。","面目芒蒼如死灰，眼眶臼陷如（米）羹柸。","（見《太平御覽》卷五九八）（按：戴良時代不明，或作東漢人，非，詳王重民《敦煌變文研究》。","今從王說收入並據以校改。","）。"]', '["敬白諸君行路者，敢告重罪自爲積。","惡致災交天困我，今月七日失阿爹。","念此酷毒可痛傷，當以重幣（重）用相賞，請爲諸君说事狀。","我父軀體與衆異，脊背傴僂捲如胾。","脣吻參差不相值，此其庶形何能備。","請复重陳其面目，鴟头鵠頸獦狗啄，眼泪鼻涕相追逐，吻中含納無牙齒，食不能嚼左右蹉。","[□]似西域[□]駱駞。","請复重陳其形骸，爲人雖长甚細材。","面目芒蒼如死灰，眼眶臼陷如（米）羹柸。","（见《太平御覽》卷五九八）（按：戴良时代不明，或作东漢人，非，詳王重民《敦煌变文研究》。","今從王说收入並據以校改。","）。"]', '诗', 'shi', '', NULL, '失父零丁 戴良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58909ec2-1a14-4d5d-bff1-513eba0c8500', '道藏歌詩 一', '道藏歌诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["王龜七寶林，唱讚願同舟。","丹景曜目精，令我心踟蹰。"]', '["王龟七寶林，唱讚願同舟。","丹景曜目精，令我心踟蹰。"]', '诗', 'shi', '', NULL, '道藏歌詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b292c341-f1ca-4b6d-9644-5e34d428298d', '道藏歌詩 二', '道藏歌诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["解帶天皇寢，停駕高上兵。","玉真造角節，翊衞自相扶。"]', '["解带天皇寢，停駕高上兵。","玉真造角節，翊衞自相扶。"]', '诗', 'shi', '', NULL, '道藏歌詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b866a9-e9fc-4003-90d5-14b056387175', '道藏歌詩 三', '道藏歌诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉皇命真王，飛軒浪天陔。","諸天驩且悅，瓊音自瑲淒。"]', '["玉皇命真王，飞軒浪天陔。","諸天驩且悅，瓊音自瑲淒。"]', '诗', 'shi', '', NULL, '道藏歌詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14220335-3b8a-4b92-9a1d-2e912e6b6837', '道藏歌詩 四', '道藏歌诗 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["重萌鬱以赫，朱風引鳴鳩。","既忘榮曜契，何不寶僊居。"]', '["重萌鬱以赫，朱风引鳴鳩。","既忘榮曜契，何不寶僊居。"]', '诗', 'shi', '', NULL, '道藏歌詩 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71bb8c79-4c82-4075-9f04-85b174d35f17', '道藏歌詩 五', '道藏歌诗 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不見九靈母，北真道相遒。","九龍運東井，天馬發西嵎。"]', '["不见九靈母，北真道相遒。","九龙運东井，天马發西嵎。"]', '诗', 'shi', '', NULL, '道藏歌詩 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9d4a02d-8489-41a9-8ba7-5a60844cbf0f', '道藏歌詩 六', '道藏歌诗 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["仰翕長庚井，練胎反嬰孩。","太一保命籍，南陵拔夜居。"]', '["仰翕长庚井，練胎反嬰孩。","太一保命籍，南陵拔夜居。"]', '诗', 'shi', '', NULL, '道藏歌詩 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf9f092-4958-47da-9118-01deaa408056', '道藏歌詩 七', '道藏歌诗 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["同歡舞雲華，衆真欣誰喻。","丹景曜目精，令我心踟蹰。"]', '["同歡舞云华，衆真欣誰喻。","丹景曜目精，令我心踟蹰。"]', '诗', 'shi', '', NULL, '道藏歌詩 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07465a39-0eb9-498a-9be3-56cef9a47097', '道藏歌詩 八', '道藏歌诗 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["日月粲華暉，迴光照真符。","憶兆不同劫，千載莫之尤。","。"]', '["日月粲华暉，迴光照真符。","憶兆不同劫，千載莫之尤。","。"]', '诗', 'shi', '', NULL, '道藏歌詩 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10624b0f-b0b8-45f5-868d-790b04532fff', '道藏歌詩 九', '道藏歌诗 九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["白帝行炁道當新，名書紫府得其篇，西龜定錄位真人。","（以上均見吳械《韻補》卷一）。"]', '["白帝行炁道當新，名书紫府得其篇，西龟定錄位真人。","（以上均见吳械《韻補》卷一）。"]', '诗', 'shi', '', NULL, '道藏歌詩 九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3d3d49-beeb-40c6-883c-4fb24649d787', '道藏歌詩 十', '道藏歌诗 十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["遊雲落太陽，飈景淩三天。","千秋似清旦，萬歲猶日半。"]', '["游云落太陽，飈景淩三天。","千秋似清旦，万歲猶日半。"]', '诗', 'shi', '', NULL, '道藏歌詩 十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b0d0b8-fde2-48e7-bd13-cf2146486432', '道藏歌詩 十一', '道藏歌诗 十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玄挺（一作「庭」）自嘉會，金書東華名。","賢安密所戒，相期陽洛汧。","（按：《孟東野詩集》卷九《列仙文·方諸青童君》末四句與此首相似，詳附按。","）。"]', '["玄挺（一作「庭」）自嘉會，金书东华名。","賢安密所戒，相期陽洛汧。","（按：《孟东野诗集》卷九《列仙文·方諸青童君》末四句與此首相似，詳附按。","）。"]', '诗', 'shi', '', NULL, '道藏歌詩 十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fee5465-7172-46a7-852a-cec4c4d5097c', '道藏歌詩 十二', '道藏歌诗 十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["觀見學仙客，蹊路放炎煙。","陽光不復朗，陰精不復明。"]', '["观见学仙客，蹊路放炎煙。","陽光不复朗，陰精不复明。"]', '诗', 'shi', '', NULL, '道藏歌詩 十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18bd4469-8ec7-440b-a29c-01d8df9eab6f', '道藏歌詩 十三', '道藏歌诗 十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["終劫復[始]（姑）劫，愈覺靈顏新。","道林蔚天京，下光諸地仙。"]', '["終劫复[始]（姑）劫，愈覺靈顏新。","道林蔚天京，下光諸地仙。"]', '诗', 'shi', '', NULL, '道藏歌詩 十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14287657-2afd-4311-9c73-2b65c198477b', '道藏歌詩 十四', '道藏歌诗 十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["推校千精，熱馘雷震。","五帝秉鉞，神公吐煙。"]', '["推校千精，熱馘雷震。","五帝秉鉞，神公吐煙。"]', '诗', 'shi', '', NULL, '道藏歌詩 十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475efa5f-b081-4db5-b001-9c79c2610b59', '道藏歌詩 十五', '道藏歌诗 十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["徘徊二元際，內觀自纏綿。","靈胎運九霞，永保億萬椿。"]', '["徘徊二元際，內观自纏綿。","靈胎運九霞，永保億万椿。"]', '诗', 'shi', '', NULL, '道藏歌詩 十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce9c2699-5059-42de-9d9b-6afb91533b3d', '道藏歌詩 十六', '道藏歌诗 十六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["齊（一作「躋」）景西那東，肆歡（一作「觀」）善因緣。","常融無地官，皆是聖皇臣。"]', '["齊（一作「躋」）景西那东，肆歡（一作「观」）善因緣。","常融無地官，皆是聖皇臣。"]', '诗', 'shi', '', NULL, '道藏歌詩 十六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba6022f-3d81-4e85-8d8c-d67247a0cadd', '道藏歌詩 十七', '道藏歌诗 十七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["今日慶元吉，億（一作「憶」）曾狀曲泉。","法師及弟子，至德自然勳。"]', '["今日慶元吉，億（一作「憶」）曾狀曲泉。","法師及弟子，至德自然勳。"]', '诗', 'shi', '', NULL, '道藏歌詩 十七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0739211-f934-428f-8626-e2153b61cd8d', '道藏歌詩 十八', '道藏歌诗 十八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["白鵠揮輕翮，神虬奮綠鱗。","羣仙嚴軒駕，玉女散華煙。"]', '["白鵠揮轻翮，神虬奮綠鱗。","羣仙嚴軒駕，玉女散华煙。"]', '诗', 'shi', '', NULL, '道藏歌詩 十八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c79a006-0634-440f-bfa7-761bd18f9cf5', '道藏歌詩 十九', '道藏歌诗 十九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["策駕玄中漢，轡素扶希（一作「桑」）林。","妙微渾混遘，長扇回五煙。"]', '["策駕玄中漢，轡素扶希（一作「桑」）林。","妙微渾混遘，长扇回五煙。"]', '诗', 'shi', '', NULL, '道藏歌詩 十九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd5f822-d8cb-4e04-98fc-d8b964655c58', '道藏歌詩 二十', '道藏歌诗 二十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["逍遙聚無散，身生水火先。","大運會開度，彌劫爲一齡。"]', '["逍遙聚無散，身生水火先。","大運會开度，彌劫爲一齡。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc9d1d2-b622-469e-82a3-bd4b18bca0a7', '道藏歌詩 二十一', '道藏歌诗 二十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["冥化自有數，我真法自然。","妙曲發空洞，宮商結仙靈。"]', '["冥化自有數，我真法自然。","妙曲發空洞，宮商結仙靈。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307ec42b-3977-45cc-be3c-79d8df12567f', '道藏歌詩 二十二', '道藏歌诗 二十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["今日度（一作「慶」）元吉，憶曾狀曲泉。","萬神同斯和，億劫豈知淪。"]', '["今日度（一作「慶」）元吉，憶曾狀曲泉。","万神同斯和，億劫豈知淪。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38199282-1126-486d-a95e-162d1c035e2e', '道藏歌詩 二十三', '道藏歌诗 二十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["椿齡會足衰，劫往豈足遼。","虛刀揮至空，鄙滯五神愁。","。"]', '["椿齡會足衰，劫往豈足遼。","虛刀揮至空，鄙滯五神愁。","。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7155ad9-af52-43f4-a11e-68137234be85', '道藏歌詩 二十四', '道藏歌诗 二十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["迴舞太空嶺，六氣運重幽。","我際豈能尋，使爾終不彫。"]', '["迴舞太空嶺，六氣運重幽。","我際豈能尋，使爾終不彫。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a09e46-026c-4bb2-b86e-b65e423f5312', '道藏歌詩 二十五', '道藏歌诗 二十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["仙童掇朱實，神女獻玉瓜。","浴身丹浥池，濯髮甘泉波。"]', '["仙童掇朱實，神女獻玉瓜。","浴身丹浥池，濯髮甘泉波。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b99f70-6e70-40c6-bdc3-d3b0ed6b7c7c', '道藏歌詩 二十六', '道藏歌诗 二十六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["宴景玉京上，遊輪蹲玄都。","逍遙大明中，長燈煥翠羅。"]', '["宴景玉京上，游輪蹲玄都。","逍遙大明中，长灯煥翠羅。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f9eeac-f8eb-45d8-89cf-e0f23edebfce', '道藏歌詩 二十七', '道藏歌诗 二十七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["乞免五難中，制召諸天魔。","靈嶽不崩陷，福地更鍊胎。"]', '["乞免五难中，制召諸天魔。","靈嶽不崩陷，福地更鍊胎。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3160eef4-4932-4540-b125-7ecea07ef69a', '道藏歌詩 二十八', '道藏歌诗 二十八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["運役自然氣，於是息三徒。","一暢萬劫感，慶賀西玉那。"]', '["運役自然氣，於是息三徒。","一暢万劫感，慶賀西玉那。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8ea27b3-9af7-42fa-9db2-2682ee5ff8be', '道藏歌詩 二十九', '道藏歌诗 二十九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["五道息對魂，九幽罷三途。","不聞孤魂聲，但聞興樂歌。"]', '["五道息对魂，九幽罷三途。","不闻孤魂声，但闻兴乐歌。"]', '诗', 'shi', '', NULL, '道藏歌詩 二十九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0182af-152c-466e-9e3a-c7124a1e5088', '道藏歌詩 三十', '道藏歌诗 三十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["榮秀椿却期，乘運應靈圖。","兜術開大有，一慶享祚多。"]', '["榮秀椿却期，乘運應靈圖。","兜術开大有，一慶享祚多。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ec33fb-e25e-449d-8edf-1e7f8c517189', '道藏歌詩 三十一', '道藏歌诗 三十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["下看榮竟子，篤似蛙與蟆。","顧盼慶濁中，憂患自相羅。"]', '["下看榮竟子，篤似蛙與蟆。","顧盼慶濁中，憂患自相羅。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256cd6b8-93ef-4de7-af4e-94aa7c3d09a6', '道藏歌詩 三十二', '道藏歌诗 三十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["靜心念至真，隨運順離羅。","感應理常通，神適逮自徂。"]', '["静心念至真，隨運順離羅。","感應理常通，神適逮自徂。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d301345-1f6f-4ade-9bde-de53b5cf3cf3', '道藏歌詩 三十三', '道藏歌诗 三十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["彈璈北寒臺，七靈曜紫霄。","濟濟羣仙舉，紛紛塵中羅。"]', '["彈璈北寒台，七靈曜紫霄。","濟濟羣仙舉，紛紛塵中羅。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b7cdbac-24f0-4255-924b-e0f628b63f4f', '道藏歌詩 三十四', '道藏歌诗 三十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["太虛感靈會，命我生成章。","諸天普欣悅，一切稽首恭。"]', '["太虛感靈會，命我生成章。","諸天普欣悅，一切稽首恭。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed730795-2dc7-4b97-89a8-e959ccf148f3', '道藏歌詩 三十五', '道藏歌诗 三十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["開度飛玄真，凝化輪空洞。","帝真始明精，號曰字元陽。"]', '["开度飞玄真，凝化輪空洞。","帝真始明精，號曰字元陽。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09070f1-7226-4f9c-9adf-1af79a9c8ac1', '道藏歌詩 三十六', '道藏歌诗 三十六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["綠蓋協晨霞，青軿擲空峒。","右揖東林帝，上朝太虛皇。","（按：嘉慶刊張伯魁《崆峒山志》收此詩，似即引自《韻補》。","）。"]', '["綠蓋協晨霞，青軿擲空峒。","右揖东林帝，上朝太虛皇。","（按：嘉慶刊張伯魁《崆峒山志》收此诗，似即引自《韻補》。","）。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14389ebf-016b-496c-a6e8-bdc397e616a8', '道藏歌詩 三十七', '道藏歌诗 三十七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鬱鬱對啓明，圓華煥三沖。","飈粲麗九天，天綠繞丹房。"]', '["鬱鬱对啓明，圓华煥三沖。","飈粲丽九天，天綠繞丹房。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78505336-65b1-4ff0-9dbb-65720d2d9a57', '道藏歌詩 三十八', '道藏歌诗 三十八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["斬滅六天，嚴整北酆。","束精縛妖，受事玉皇。"]', '["斬滅六天，嚴整北酆。","束精縛妖，受事玉皇。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e20aec42-8984-4997-93c5-fe5c55aac26c', '道藏歌詩 三十九', '道藏歌诗 三十九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["停蓋濯碧溪，采秀月支峯。","咀嚼三靈華，吐吸九神芒。"]', '["停蓋濯碧溪，采秀月支峯。","咀嚼三靈华，吐吸九神芒。"]', '诗', 'shi', '', NULL, '道藏歌詩 三十九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b05d9e-2afe-498a-8b25-883ae9252d96', '道藏歌詩 四十', '道藏歌诗 四十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["靈章癊玄方，仰感旋曜精。","詵詵繁茂萌，重德必克昌。"]', '["靈章癊玄方，仰感旋曜精。","詵詵繁茂萌，重德必克昌。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc684f19-c317-48b4-baa7-38c15cebde82', '道藏歌詩 四十一', '道藏歌诗 四十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["攜袂明真館，仰期天上皇。","北鈞唱羽人，玉女粲賢衆。"]', '["携袂明真館，仰期天上皇。","北鈞唱羽人，玉女粲賢衆。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8de7bf60-66e6-43fd-b641-829b8fd8c404', '道藏歌詩 四十二', '道藏歌诗 四十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["引領囂庭內，開心機穢衝。","一靜安居苦，試去視滄浪。"]', '["引領囂庭內，开心機穢衝。","一静安居苦，試去視滄浪。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0715ff-0670-4356-8761-43157a479715', '道藏歌詩 四十三', '道藏歌诗 四十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["淵響啓靈扉，七門扇羽章。","陽臺大洞野，幽逸英芝充。"]', '["淵响啓靈扉，七门扇羽章。","陽台大洞野，幽逸英芝充。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1758a2c-ed74-4ab5-b05d-cf9069d01978', '道藏歌詩 四十四', '道藏歌诗 四十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["神暢（一作「粲」）感寂庭，嘿思徹九重。","靈歌理冥運，百和結成章。"]', '["神暢（一作「粲」）感寂庭，嘿思徹九重。","靈歌理冥運，百和結成章。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f62b17a0-32e3-4cba-b9bc-8e4b5bb9c55f', '道藏歌詩 四十五', '道藏歌诗 四十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["霄軿縱橫舞，紫蓋託朱方。","風塵有憂哀，隕我白鬢翁。"]', '["霄軿縱橫舞，紫蓋託朱方。","风塵有憂哀，隕我白鬢翁。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a4d48f6-ad9c-44db-8096-a10a0e97041c', '道藏歌詩 四十六', '道藏歌诗 四十六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["司命保算，丹書南昌。","解技七元，腐骨更蓊。"]', '["司命保算，丹书南昌。","解技七元，腐骨更蓊。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c49c7f-68f7-4e79-923d-2606420bfc60', '道藏歌詩 四十七', '道藏歌诗 四十七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["提攜高上賓。","反我素靈房。","道場靈沫內，高歌登太虛。"]', '["提携高上賓。","反我素靈房。","道場靈沫內，高歌登太虛。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faa58d77-e318-4ac5-89ca-0f55da955bdd', '道藏歌詩 四十八', '道藏歌诗 四十八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉臺敷朱霄，綠霞高有墉。","體矯萬津波，神生攝十方。"]', '["玉台敷朱霄，綠霞高有墉。","體矯万津波，神生攝十方。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7b58ed-5516-4203-9045-616165bb24c3', '道藏歌詩 四十九', '道藏歌诗 四十九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["但聞仙道貴，不聞鬼道隆。","謠謌參天炁，賈生元正章。","（以上四十首均見同書卷二）。"]', '["但闻仙道貴，不闻鬼道隆。","謠謌參天炁，賈生元正章。","（以上四十首均见同书卷二）。"]', '诗', 'shi', '', NULL, '道藏歌詩 四十九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd54224b-a4ad-4ede-b8b7-9586209db85c', '道藏歌詩 五十', '道藏歌诗 五十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["提攜宴玉賓，契駕乘煙騁。","黃籙命玉符，公子運我上。"]', '["提携宴玉賓，契駕乘煙騁。","黄籙命玉符，公子運我上。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c6dd2be-842f-4398-b003-f075d66e3122', '道藏歌詩 五十一', '道藏歌诗 五十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉虛範玄象，高會通冥想。","三曜無停暉，明真煥雲芒。"]', '["玉虛範玄象，高會通冥想。","三曜無停暉，明真煥云芒。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('903d3885-84ff-4999-b1b2-6293bc54df5c', '道藏歌詩 五十二', '道藏歌诗 五十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["解散七玄祖，更法無中影。","七化反自然，帝一同玄饗。","（以上見同書卷三）。"]', '["解散七玄祖，更法無中影。","七化反自然，帝一同玄饗。","（以上见同书卷三）。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf3af95-ee98-43ac-99b5-dac26ef3a962', '道藏歌詩 五十三', '道藏歌诗 五十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["飛輪藹太宗，無形亦無跡。","縱路任飛輪，蕭蕭起界外。"]', '["飞輪藹太宗，無形亦無跡。","縱路任飞輪，蕭蕭起界外。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1d69ad-3ce8-483d-9e35-07ec6eb7af86', '道藏歌詩 五十四', '道藏歌诗 五十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["清明重霄上，合期慶雲際。","玉條流逸響，從容靈妙話。","。"]', '["清明重霄上，合期慶云際。","玉條流逸响，從容靈妙話。","。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15b92e9-c4bb-4fd2-a06e-f5d5ce43d754', '道藏歌詩 五十五', '道藏歌诗 五十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夕遊蓬萊島，期對華景宴。","神仙結丹藻，流暉寄文翰。"]', '["夕游蓬萊島，期对华景宴。","神仙結丹藻，流暉寄文翰。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12158fef-4b4e-4498-a12e-3ebdd57d32f6', '道藏歌詩 五十六', '道藏歌诗 五十六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["風雲隱宛微，講論五嶽匠。","硨磲精流璃，琥珀金剛鏡。"]', '["风云隐宛微，講論五嶽匠。","硨磲精流璃，琥珀金剛镜。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c8f276-cadf-4876-96d7-6c08439d6fce', '道藏歌詩 五十七', '道藏歌诗 五十七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["絳衣表羣會，生始似久夢。","德隱沖內迹，至寂不覺當。","（當，去聲。","）（以上見同書卷四）。"]', '["絳衣表羣會，生始似久梦。","德隐沖內迹，至寂不覺當。","（當，去声。","）（以上见同书卷四）。"]', '诗', 'shi', '', NULL, '道藏歌詩 五十七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e030b0-21e4-4635-ab11-730ead3869b0', '道藏元君詩', '道藏元君诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["彼雲泛靈輿，倏忽適下土。","崆峒滅玄雲，至感不容冶。","（同前卷三）。"]', '["彼云泛靈輿，倏忽適下土。","崆峒滅玄云，至感不容冶。","（同前卷三）。"]', '诗', 'shi', '', NULL, '道藏元君詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a135c3a-c9e8-4725-ba8f-1f4cf222c526', '道藏元始歌', '道藏元始歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["黃庭戊己無流源，徹通五藏十二綸。","（見同書卷二）。"]', '["黄庭戊己無流源，徹通五藏十二綸。","（见同书卷二）。"]', '诗', 'shi', '', NULL, '道藏元始歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5f8373-7a10-4dfc-ab56-84f897d0aad0', '道藏左夫人歌', '道藏左夫人歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["騰躍雲景轅，浮觀霞上空。","霄軿縱橫舞，紫蓋記靈方。"]', '["腾躍云景轅，浮观霞上空。","霄軿縱橫舞，紫蓋記靈方。"]', '诗', 'shi', '', NULL, '道藏左夫人歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82bf2d22-9aff-487e-b38d-95cb863e5e03', '道藏中嶽仙人歌', '道藏中嶽仙人歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["徘徊玄嶽巓，翻焉御飛龍。","齊騰八紘外，翺翔閶闔房。","（見同書卷一。","以上所錄《韻補》中詩，均以中華書局影宋本爲底本，校以《連筠簃叢書》本、影印文淵閣《四庫全書》本）（〖1〗《韻補》卷首書目釋《道藏》歌詩云：「當是魏晉時人所作。","其文詞非儒家所急，取其韻古也。","多陽聲，與《黃庭》同。","」今人逯欽立《先秦漢魏晉南北朝詩後記》云：「《韻補》引用的《道藏》歌詩，其中就有唐孟郊作的《列仙文·方諸青童歌》，……爲此，《韻補》所用道歌，本書一概不取。","」今按：以孟郊詩與吳棫所錄對校，二十字中有八字不同，故前仍錄出。","據逯先生所云，《韻補》諸詩雖不能斷定爲魏）（晉間人作，但爲宋以前人作，殆無疑義。","宋代道家著作中常見的「坎離交媾、嬰兒姹女、道家修養之術」〖《四庫全書總目》卷一四七《金丹詩訣》提要語〗，諸詩中皆未見，即爲一證。","今收入先宋詩。","）。"]', '["徘徊玄嶽巓，翻焉御飞龙。","齊腾八紘外，翺翔閶闔房。","（见同书卷一。","以上所錄《韻補》中诗，均以中华书局影宋本爲底本，校以《連筠簃叢书》本、影印文淵閣《四庫全书》本）（〖1〗《韻補》卷首书目釋《道藏》歌诗云：「當是魏晉时人所作。","其文词非儒家所急，取其韻古也。","多陽声，與《黄庭》同。","」今人逯欽立《先秦漢魏晉南北朝诗後記》云：「《韻補》引用的《道藏》歌诗，其中就有唐孟郊作的《列仙文·方諸青童歌》，……爲此，《韻補》所用道歌，本书一概不取。","」今按：以孟郊诗與吳棫所錄对校，二十字中有八字不同，故前仍錄出。","據逯先生所云，《韻補》諸诗雖不能斷定爲魏）（晉间人作，但爲宋以前人作，殆無疑義。","宋代道家著作中常见的「坎離交媾、嬰兒姹女、道家修養之術」〖《四庫全书總目》卷一四七《金丹诗訣》提要語〗，諸诗中皆未见，即爲一證。","今收入先宋诗。","）。"]', '诗', 'shi', '', NULL, '道藏中嶽仙人歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d725f8-2606-4251-aeea-9724de9df7f1', '疊韻詩', '叠韻诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["看河水漠瀝，望野草蒼黃。","露停君子樹，霜宿女姓薑。"]', '["看河水漠瀝，望野草蒼黄。","露停君子樹，霜宿女姓薑。"]', '诗', 'shi', '', NULL, '疊韻詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb1491c-491d-4853-8575-961ef77e824b', '疊連韻詩', '叠連韻诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["羈客意盤桓，流淚下闌干。","雖對琴觴樂，煩情仍未歡。"]', '["羈客意盤桓，流泪下闌干。","雖对琴觴乐，煩情仍未歡。"]', '诗', 'shi', '', NULL, '疊連韻詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3dc6672-f8b7-4c5e-85b4-6115fdcd2f35', '擲韻詩 一', '擲韻诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不知羞，不敢留。","但好去，莫相慮。","孤客驚，百愁生。","飯蔬簟食樂道，忘饑陋巷不疲。"]', '["不知羞，不敢留。","但好去，莫相慮。","孤客驚，百愁生。","飯蔬簟食乐道，忘饑陋巷不疲。"]', '诗', 'shi', '', NULL, '擲韻詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502c868d-cbca-4f6c-8f96-3e4b817c33ce', '擲韻詩 二', '擲韻诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不知羞，不肯留。","集麗城，夜啼聲。","出長安，過上蘭。","指楊都，越江湖。","念邯鄲，忘朝飡。","但好去，莫相慮。"]', '["不知羞，不肯留。","集丽城，夜啼声。","出长安，過上蘭。","指楊都，越江湖。","念邯鄲，忘朝飡。","但好去，莫相慮。"]', '诗', 'shi', '', NULL, '擲韻詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a38c7e-05c4-4690-b97a-9e46a2636760', '重字韻詩', '重字韻诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["望野草青青，臨河水活活。","斜峰纜舟行，曲浦浮積沫。"]', '["望野草青青，臨河水活活。","斜峰纜舟行，曲浦浮積沫。"]', '诗', 'shi', '', NULL, '重字韻詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3f4693-80bf-48f2-9df4-3cbc01849dde', '同音韻詩', '同音韻诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["今朝是何夕，良人誰觀覿。","中心實憐愛，夜寐不安席。","（以上六首均見《文鏡秘府論校注》天卷《八種韻》）（按：《八種韻》節凡引詩九首，除梁蕭繹、唐王昌齡、李白各一首外，餘六首作者不詳。","王利器《文鏡秘府論校注》引任學良《文鏡秘府論校注》稿本云：「本節曾引王昌齡李白詩，疑係元兢《腦髓》之文，皎然《詩議》不致有此種瑣屑聲）（韻之論也。","」然兢爲高宗時人，安得引及李、王之詩。","其說未諦。","諸詩爲六朝至盛唐間作品，殆無可疑。","）。"]', '["今朝是何夕，良人誰观覿。","中心實怜愛，夜寐不安席。","（以上六首均见《文镜秘府論校注》天卷《八種韻》）（按：《八種韻》節凡引诗九首，除梁蕭繹、唐王昌齡、李白各一首外，餘六首作者不詳。","王利器《文镜秘府論校注》引任学良《文镜秘府論校注》稿本云：「本節曾引王昌齡李白诗，疑係元兢《腦髓》之文，皎然《诗議》不致有此種瑣屑声）（韻之論也。","」然兢爲高宗时人，安得引及李、王之诗。","其说未諦。","諸诗爲六朝至盛唐间作品，殆無可疑。","）。"]', '诗', 'shi', '', NULL, '同音韻詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e74dce-4eab-4d89-acb2-94eab68d48ca', '同音韻詩 一', '同音韻诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["斟清酒，拍青琴。"]', '["斟清酒，拍青琴。"]', '诗', 'shi', '', NULL, '同音韻詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7258972a-1911-49a4-85e3-a6e8d1fed4a7', '同音韻詩 二', '同音韻诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["尋往信，訪來音。"]', '["尋往信，訪来音。"]', '诗', 'shi', '', NULL, '同音韻詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029cbb44-64b5-4770-99a0-ad41a63954a4', '同音韻詩 三', '同音韻诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["春可樂，秋可哀。"]', '["春可乐，秋可哀。"]', '诗', 'shi', '', NULL, '同音韻詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9df20e65-8a1a-41e7-988b-bc2b82bb623d', '同音韻詩 四', '同音韻诗 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["朝燃獸炭，夜秉魚燈。"]', '["朝燃獸炭，夜秉鱼灯。"]', '诗', 'shi', '', NULL, '同音韻詩 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a0772a5-a3db-4398-bd98-7a2cdf2ac4a4', '同音韻詩 五', '同音韻诗 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["宋臘已歌，秦姬欲笑。"]', '["宋臘已歌，秦姬欲笑。"]', '诗', 'shi', '', NULL, '同音韻詩 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('345d328e-453f-4f87-94a3-b8d0f056a606', '同音韻詩 六', '同音韻诗 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["霧開山有媚，雲閉日無光。"]', '["霧开山有媚，云閉日無光。"]', '诗', 'shi', '', NULL, '同音韻詩 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5822dd-6382-4636-9c21-52acf9717137', '同音韻詩 七', '同音韻诗 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["燥塵籠野白，寒樹染村黃。"]', '["燥塵籠野白，寒樹染村黄。"]', '诗', 'shi', '', NULL, '同音韻詩 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac076d86-70e7-421b-a7be-b68640f10ac3', '同音韻詩 八', '同音韻诗 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["素琴奏乎五三拍，綠酒傾乎一兩巵。"]', '["素琴奏乎五三拍，綠酒傾乎一兩巵。"]', '诗', 'shi', '', NULL, '同音韻詩 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f9c98e6-1b77-48de-926f-4f0337471602', '同音韻詩 九', '同音韻诗 九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["嗟余薄德從役至他鄉，筋力疲頓無意入長楊。"]', '["嗟余薄德從役至他乡，筋力疲頓無意入长楊。"]', '诗', 'shi', '', NULL, '同音韻詩 九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc88b584-01c7-4a6a-b5fa-70c9482079da', '的名對詩', '的名对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["送酒東南去，迎琴西北來。"]', '["送酒东南去，迎琴西北来。"]', '诗', 'shi', '', NULL, '的名對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde2f5fb-3253-43b7-9da9-585c9b590c44', '異類對詩', '異類对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["風織池間樹（一作「字」），蟲穿草（一作「葉」）上文。"]', '["风织池间樹（一作「字」），蟲穿草（一作「葉」）上文。"]', '诗', 'shi', '', NULL, '異類對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('619105ea-3d88-461c-82c2-b7247387d5e9', '雙聲對詩', '雙声对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["秋露香佳菊，春風馥麗蘭。"]', '["秋露香佳菊，春风馥丽蘭。"]', '诗', 'shi', '', NULL, '雙聲對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('928d9205-6d68-4354-b227-8abe964cd822', '雙擬樹詩', '雙擬樹诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["議月眉欺月，論花頰勝花。"]', '["議月眉欺月，論花頰勝花。"]', '诗', 'shi', '', NULL, '雙擬樹詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73749e33-ee46-46df-82fa-f9f2c894d63e', '隔句對詩', '隔句对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["相思復相憶，夜夜淚沾衣。","空歎復空泣，朝朝君未歸。","（以上五題均見《詩人玉屑》卷七引李淑《詩苑類格》引上官儀語引。","又見《文鏡秘府論》東卷《二十九種對》。","疑即出上官儀《筆札華梁》）。"]', '["相思复相憶，夜夜泪沾衣。","空歎复空泣，朝朝君未归。","（以上五題均见《诗人玉屑》卷七引李淑《诗苑類格》引上官儀語引。","又见《文镜秘府論》东卷《二十九種对》。","疑即出上官儀《笔札华梁》）。"]', '诗', 'shi', '', NULL, '隔句對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5359fd69-703e-4c06-903a-de5fc2a7a54b', '句 一', '句 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["風花無定影，露竹有餘清。"]', '["风花無定影，露竹有餘清。"]', '诗', 'shi', '', NULL, '句 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970ea295-f7f8-451e-9337-aa51dac9cdb0', '句 二', '句 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["映浦樹疑浮，入雲峰似滅（一作「截」）（以上二聯爲形似體）。"]', '["映浦樹疑浮，入云峰似滅（一作「截」）（以上二聯爲形似體）。"]', '诗', 'shi', '', NULL, '句 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac810f9-f0cf-4e19-85cb-8377c9c6a50c', '句 三', '句 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["四鄰不相識，自然成掩扉。","（此爲情理體）。"]', '["四鄰不相識，自然成掩扉。","（此爲情理體）。"]', '诗', 'shi', '', NULL, '句 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9308e866-f87c-4475-9db4-f9f49054588e', '句 四', '句 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["隱隱山分地，滄滄海接天。","（此爲直置體）。"]', '["隐隐山分地，滄滄海接天。","（此爲直置體）。"]', '诗', 'shi', '', NULL, '句 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c968c06f-355e-403a-8eff-44e5cc82343a', '句 五', '句 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["侵雲蹀征騎，帶月倚雕弓。"]', '["侵云蹀征騎，带月倚雕弓。"]', '诗', 'shi', '', NULL, '句 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e32ce692-8103-4ccc-8214-e16a9dd2d82a', '句 六', '句 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["舒（一作「野」）桃臨遠騎，垂柳映連營。","（以上聯爲映帶體）。"]', '["舒（一作「野」）桃臨远騎，垂柳映連營。","（以上聯爲映带體）。"]', '诗', 'shi', '', NULL, '句 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('293f8e92-6682-444f-acc2-ed235211efef', '句 七', '句 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月光隨浪動，山影逐波流。","（此爲飛動體）。"]', '["月光隨浪动，山影逐波流。","（此爲飞动體）。"]', '诗', 'shi', '', NULL, '句 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8b29a5-2df7-4851-b2dd-8e02b58606f8', '句 八', '句 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["歌前日照梁，舞處塵生襪。"]', '["歌前日照梁，舞处塵生襪。"]', '诗', 'shi', '', NULL, '句 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9223911-bed2-44f3-aa99-4016fe82ee1f', '句 九', '句 九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["泛色松煙舉，凝花菊露滋。","（以上二聯爲婉轉體）。"]', '["泛色松煙舉，凝花菊露滋。","（以上二聯爲婉轉體）。"]', '诗', 'shi', '', NULL, '句 九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3322284-c3e8-41ea-98b3-7f2c21bb12a7', '句 十', '句 十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["寒葭凝露色，落葉動秋聲。","（此爲清切體）。"]', '["寒葭凝露色，落葉动秋声。","（此爲清切體）。"]', '诗', 'shi', '', NULL, '句 十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('120d035d-c0b3-4ab5-bd40-62d9ed302149', '句 十一', '句 十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["青田未矯翰，丹穴欲乘風（一作「鳳」）。"]', '["青田未矯翰，丹穴欲乘风（一作「鳳」）。"]', '诗', 'shi', '', NULL, '句 十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50cd5366-e2ab-4f61-a73c-86d790602461', '句 十二', '句 十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["曲沼疏秋蓋，長林卷夏帷。"]', '["曲沼疏秋蓋，长林卷夏帷。"]', '诗', 'shi', '', NULL, '句 十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2cbd220-6b72-448f-8f26-36ac394f7f8b', '句 十三', '句 十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["積翠徹（王利器疑當作「澈」）深潭，舒丹明淺瀨。","（以上三聯爲菁華體）（以上十三聯均見《文鏡秘府論》地卷《十體》引崔融《唐朝新定詩格》）（按：《十體》節共引詩二十一題，今可查知作者之作凡八題，分屬宋鮑照、齊王融、梁戴暠、陳江總、隋楊廣、孔德紹、虞世基、唐崔信明。","不知作者之作凡十三聯，當爲六朝至初唐人所作，惜已無從甄辨。","）。"]', '["積翠徹（王利器疑當作「澈」）深潭，舒丹明淺瀨。","（以上三聯爲菁华體）（以上十三聯均见《文镜秘府論》地卷《十體》引崔融《唐朝新定诗格》）（按：《十體》節共引诗二十一題，今可查知作者之作凡八題，分屬宋鲍照、齊王融、梁戴暠、陳江總、隋楊廣、孔德紹、虞世基、唐崔信明。","不知作者之作凡十三聯，當爲六朝至初唐人所作，惜已無從甄辨。","）。"]', '诗', 'shi', '', NULL, '句 十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f650e7dd-ed7a-4754-9760-2d76fad50f3e', '繁說病詩', '繁说病诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["從風似飛絮，照日類繁英。","拂巖如寫鏡，封林若耀瓊。"]', '["從风似飞絮，照日類繁英。","拂巖如寫镜，封林若耀瓊。"]', '诗', 'shi', '', NULL, '繁說病詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27aaa47b-8c35-4d28-88d4-960dfc6729f3', '齟齬病詩 一', '齟齬病诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["霧生極野碧，日下遠山紅。"]', '["霧生極野碧，日下远山紅。"]', '诗', 'shi', '', NULL, '齟齬病詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b8c59a5-ea78-4c2d-81cc-a223cfc34648', '齟齬病詩 二', '齟齬病诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["晨風驚疊樹，曉月落危峰。"]', '["晨风驚叠樹，晓月落危峰。"]', '诗', 'shi', '', NULL, '齟齬病詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('621e6d38-af51-4744-a046-1f50efb4db84', '叢木病詩', '叢木病诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["庭梢桂林樹，檐度蒼梧雲。","櫂唱喧難辨，樵歌近易聞。","（以上三題均見《文鏡秘府論》西卷《文二十八種病》引崔融《唐朝新定詩格》引）。"]', '["庭梢桂林樹，檐度蒼梧云。","櫂唱喧难辨，樵歌近易闻。","（以上三題均见《文镜秘府論》西卷《文二十八種病》引崔融《唐朝新定诗格》引）。"]', '诗', 'shi', '', NULL, '叢木病詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94bf1153-a982-4c6f-a389-792a3b2aef46', '切側對詩', '切側对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["浮鐘宵響徹，飛鏡曉光斜。"]', '["浮鐘宵响徹，飞镜晓光斜。"]', '诗', 'shi', '', NULL, '切側對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('346fd993-a1c5-4421-93b7-4e64d61be451', '雙聲側對詩 一', '雙声側对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["花明金谷樹，葉映首山薇。"]', '["花明金谷樹，葉映首山薇。"]', '诗', 'shi', '', NULL, '雙聲側對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b54fec18-fbf3-4786-8526-41d9261e045c', '雙聲側對詩 二', '雙声側对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["翠微分雉堞，丹氣隱簷楹。"]', '["翠微分雉堞，丹氣隐簷楹。"]', '诗', 'shi', '', NULL, '雙聲側對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1770c1b7-32cf-46bb-9e69-07bbc9692949', '疊韻側對詩 一', '叠韻側对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["平生披黼帳，窈窕步花庭。"]', '["平生披黼帳，窈窕步花庭。"]', '诗', 'shi', '', NULL, '疊韻側對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc1b8bf-6127-42ae-bdd7-40d6ade57a61', '疊韻側對詩 二', '叠韻側对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["自得優遊趣，寧知聖政隆。","（以上三題均見《文鏡秘腐論》東卷《二十九種對》引崔融《唐朝新定詩格》）。"]', '["自得優游趣，寧知聖政隆。","（以上三題均见《文镜秘腐論》东卷《二十九種对》引崔融《唐朝新定诗格》）。"]', '诗', 'shi', '', NULL, '疊韻側對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('810f0b71-ecc2-43a4-a7ae-9f1c242c1372', '聲對詩 一', '声对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["彤騶初驚路，白簡未含霜。"]', '["彤騶初驚路，白簡未含霜。"]', '诗', 'shi', '', NULL, '聲對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce6bfe31-1fe1-4bc0-94a2-58b8696f00f2', '聲對詩 二', '声对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["初禪韻高柳，密蔦掛深松。"]', '["初禪韻高柳，密蔦掛深松。"]', '诗', 'shi', '', NULL, '聲對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54d1923c-3b9f-4388-a96d-043b68a51785', '字側對詩 一', '字側对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["忘懷接英彥，申勸引桂酒。"]', '["忘懷接英彥，申勸引桂酒。"]', '诗', 'shi', '', NULL, '字側對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfdc2fdc-0219-452f-a411-28d228bd88bc', '字側對詩 二', '字側对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉雞清五洛，瑞雉映三秦。"]', '["玉雞清五洛，瑞雉映三秦。"]', '诗', 'shi', '', NULL, '字側對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d5e5be3-a65f-4447-b13a-a5a757bb1739', '字側對詩 三', '字側对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["桓山分羽翼，荆樹折枝條。"]', '["桓山分羽翼，荆樹折枝條。"]', '诗', 'shi', '', NULL, '字側對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96f8ce59-1ad1-40b8-b06c-a4003f39687f', '字對詩 一', '字对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山椒架寒霧，池篠韻涼飆。"]', '["山椒架寒霧，池篠韻涼飆。"]', '诗', 'shi', '', NULL, '字對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812ba249-29ea-4bda-b7c8-7aa1127ed6ba', '字對詩 二', '字对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["何用金扉敞，終醉石崇家。"]', '["何用金扉敞，終醉石崇家。"]', '诗', 'shi', '', NULL, '字對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3373cecf-89a5-46db-825a-ccb5378a5651', '字對詩 三', '字对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["原風振平楚，野雪被長菅。","（均見《文鏡秘府論》東卷《二十九種對》，似出元兢《詩髓腦》）。"]', '["原风振平楚，野雪被长菅。","（均见《文镜秘府論》东卷《二十九種对》，似出元兢《诗髓腦》）。"]', '诗', 'shi', '', NULL, '字對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d290e3-a1c7-496a-90a7-111a46268782', '句 一', '句 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夜聞木葉落，疑是洞庭秋。"]', '["夜闻木葉落，疑是洞庭秋。"]', '诗', 'shi', '', NULL, '句 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('614c29a5-edde-427e-87b2-63e3edbf0ec6', '句 二', '句 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["竹聲先知秋。"]', '["竹声先知秋。"]', '诗', 'shi', '', NULL, '句 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d421b8-c1b1-442e-ba30-8d5baf4c5349', '句 三', '句 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["綠（一作「流」）水溢金塘。"]', '["綠（一作「流」）水溢金塘。"]', '诗', 'shi', '', NULL, '句 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1bfd98c-2bfc-42ce-8d48-1a7175f01045', '詩', '诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["明月下山頭，天河橫戍樓。","白雲千萬里，滄江朝夕流。","浦沙望如雪，松風聽似秋。","不覺煙霞曙，花鳥亂芳洲。","（以上均見《文鏡秘府論》南卷《論文意》引王昌齡《詩格》）。"]', '["明月下山头，天河橫戍楼。","白云千万里，滄江朝夕流。","浦沙望如雪，松风听似秋。","不覺煙霞曙，花鸟亂芳洲。","（以上均见《文镜秘府論》南卷《論文意》引王昌齡《诗格》）。"]', '诗', 'shi', '', NULL, '詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('749613d9-61a0-42bd-8bd1-38372b77d48d', '平頭詩 一', '平头诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["芳時淑氣清，提壺臺上傾。"]', '["芳时淑氣清，提壺台上傾。"]', '诗', 'shi', '', NULL, '平頭詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc990d6-76ef-4f35-95b2-05d83ea28b63', '平頭詩 二', '平头诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山方翻類矩，波圓更若規。","樹表看猿掛，林側望熊馳。"]', '["山方翻類矩，波圓更若規。","樹表看猿掛，林側望熊驰。"]', '诗', 'shi', '', NULL, '平頭詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71737b09-cd08-4ae3-8bfb-14b52349bcf4', '平頭詩 三', '平头诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["朝雲晦初景，丹池晚飛雪。","飄枝聚還散，吹楊凝且滅。"]', '["朝云晦初景，丹池晚飞雪。","飄枝聚還散，吹楊凝且滅。"]', '诗', 'shi', '', NULL, '平頭詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7bbefbc-965e-43fd-8487-9920d79623ef', '上尾詩 一', '上尾诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["可憐雙飛鳧，俱來下建章。","一個今依是，拂翮獨先翔。"]', '["可怜雙飞鳧，俱来下建章。","一個今依是，拂翮独先翔。"]', '诗', 'shi', '', NULL, '上尾詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf07bc94-035c-450d-b690-d09e0bb2d0f6', '上尾詩 二', '上尾诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蕩子別倡樓，秋庭夜月華。","桂葉侵雲長，輕光逐漢斜。","。"]', '["蕩子別倡楼，秋庭夜月华。","桂葉侵云长，轻光逐漢斜。","。"]', '诗', 'shi', '', NULL, '上尾詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cdf1d37-9178-44ad-b196-5a0a651ec80e', '蜂腰詩', '蜂腰诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["徐步金門出，言尋上苑春。"]', '["徐步金门出，言尋上苑春。"]', '诗', 'shi', '', NULL, '蜂腰詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891f30a0-695f-4e65-b7d4-c934db04dcb6', '鶴膝詩 一', '鹤膝诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["撥櫂金陵渚，遵流背城闕。","浪蹙飛船影，山掛垂輪月。"]', '["撥櫂金陵渚，遵流背城闕。","浪蹙飞船影，山掛垂輪月。"]', '诗', 'shi', '', NULL, '鶴膝詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288df86b-aace-4ab5-bbc4-734b38a79861', '鶴膝詩 二', '鹤膝诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["陟野看陽春，登樓望初節。","綠池始沾裳，弱蘭未央結。"]', '["陟野看陽春，登楼望初節。","綠池始沾裳，弱蘭未央結。"]', '诗', 'shi', '', NULL, '鶴膝詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e7698e2-72e9-4d4a-bc79-a4a2277de9e3', '大韻詩', '大韻诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["遊魚牽細藻，鳴琴哢好音。","誰知遲暮節，悲吟傷寸心。"]', '["游鱼牽細藻，鳴琴哢好音。","誰知遲暮節，悲吟傷寸心。"]', '诗', 'shi', '', NULL, '大韻詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56287b18-0829-4cfd-ba5d-5124ace1a910', '小韻詩 一', '小韻诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["搴簾出戶望，霜花朝瀁日。","晨鶯傍杼飛，早燕挑（一作「排」）軒出。"]', '["搴簾出戶望，霜花朝瀁日。","晨鶯傍杼飞，早燕挑（一作「排」）軒出。"]', '诗', 'shi', '', NULL, '小韻詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a7142b4-e78b-4a69-8488-4227d8ebc086', '小韻詩 二', '小韻诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夜中無與悟（一作「語」），獨寤撫躬歎。","唯慚一片月，流彩照南端。"]', '["夜中無與悟（一作「語」），独寤撫躬歎。","唯慚一片月，流彩照南端。"]', '诗', 'shi', '', NULL, '小韻詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0242629-b2a0-45c0-a7a5-de81f9bee1b6', '傍紐詩 一', '傍紐诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["魚遊見風月，獸走畏傷蹄。"]', '["鱼游见风月，獸走畏傷蹄。"]', '诗', 'shi', '', NULL, '傍紐詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('326fafae-5bd1-4820-bc84-4f37e478f321', '傍紐詩 二', '傍紐诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["元生愛皓月，阮氏願清風。","取樂情無已，賞玩未能同。"]', '["元生愛皓月，阮氏願清风。","取乐情無已，賞玩未能同。"]', '诗', 'shi', '', NULL, '傍紐詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e5e770e-232e-4fa1-bb48-7317ecd0f7a0', '傍紐詩 三', '傍紐诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雲生遮麗月，波動亂遊魚。","涼風便入體，寒氣漸鑽膚。"]', '["云生遮丽月，波动亂游鱼。","涼风便入體，寒氣漸鑽膚。"]', '诗', 'shi', '', NULL, '傍紐詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844571c6-89df-4060-873a-54bc2d47c492', '正紐詩 一', '正紐诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["撫琴起和曲，疊管泛鳴驅（王利器云：「疑當作『謳』」）。","停軒未忍去，白日小踟蹰。","。"]', '["撫琴起和曲，叠管泛鳴驱（王利器云：「疑當作『謳』」）。","停軒未忍去，白日小踟蹰。","。"]', '诗', 'shi', '', NULL, '正紐詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc3e24f-bfe2-4e00-8ee4-be5df1b82659', '正紐詩 二', '正紐诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["心中肝如割，腹（一作「腸」）裏氣便燋。","逢風迴無信，早雁轉成遙。"]', '["心中肝如割，腹（一作「腸」）裏氣便燋。","逢风迴無信，早雁轉成遙。"]', '诗', 'shi', '', NULL, '正紐詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('336ac529-8750-4084-88df-8a576df986d1', '春詩 一', '春诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["沼萍遍水纈，榆莢滿枝錢。"]', '["沼萍遍水纈，榆莢满枝錢。"]', '诗', 'shi', '', NULL, '春詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57aa97e-e1c6-4a0b-a748-dd5b4670a256', '春詩 二', '春诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["斜雲朝列陳，迴娥夜抱弦。","（二聯爲水渾病）。"]', '["斜云朝列陳，迴娥夜抱弦。","（二聯爲水渾病）。"]', '诗', 'shi', '', NULL, '春詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5dd8ebf-dfcf-4077-a9d7-fb5690692a2e', '閨怨詩 一', '閨怨诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["塵暗離後鏡，帶永別前腰。"]', '["塵暗離後镜，带永別前腰。"]', '诗', 'shi', '', NULL, '閨怨詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da11e559-7b9b-4051-8920-1cc901652d8e', '閨怨詩 二', '閨怨诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["怨心千過絕，啼眼百迴垂。","（二聯爲火滅病）。"]', '["怨心千過絕，啼眼百迴垂。","（二聯爲火滅病）。"]', '诗', 'shi', '', NULL, '閨怨詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d93a549-cc6a-43d0-850c-68101b65457a', '秋詩 一', '秋诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["金風晨泛菊，玉露宵沾蘭（一作「懸珠」）。"]', '["金风晨泛菊，玉露宵沾蘭（一作「懸珠」）。"]', '诗', 'shi', '', NULL, '秋詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b70640-cf37-4e98-b66b-2b7a205c604c', '秋詩 二', '秋诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉輪夜進轍，金車晝滅途。","（二聯爲木枯病）。"]', '["玉輪夜進轍，金车晝滅途。","（二聯爲木枯病）。"]', '诗', 'shi', '', NULL, '秋詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e07bd050-ad50-4cd8-9e8b-f40964c39f40', '寒詩 一', '寒诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["獸炭陵晨送，魚燈徹宵燃。"]', '["獸炭陵晨送，鱼灯徹宵燃。"]', '诗', 'shi', '', NULL, '寒詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('166e3b3f-ba29-4ca4-8b8c-2b5e53dcf0b3', '寒詩 二', '寒诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["狐裘朝除冷，褻褥夜排寒。","（二聯爲金缺病）。"]', '["狐裘朝除冷，褻褥夜排寒。","（二聯爲金缺病）。"]', '诗', 'shi', '', NULL, '寒詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('549adcf4-e5ef-4894-9e2b-4dab53c4dccf', '述懷詩 一', '述懷诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鳴琴四五弄，桂酒復盈杯。"]', '["鳴琴四五弄，桂酒复盈杯。"]', '诗', 'shi', '', NULL, '述懷詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b43c429-a3c4-40d9-8914-64ce148bd449', '述懷詩 二', '述懷诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夜夜憐琴酒，優遊足暢情。","（二聯爲闕偶病）。"]', '["夜夜怜琴酒，優游足暢情。","（二聯爲闕偶病）。"]', '诗', 'shi', '', NULL, '述懷詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a87876-8e41-47d4-abf0-fe73a20c66f9', '缺偶詩', '缺偶诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蘇秦時刺股，勤學我便耽。"]', '["蘇秦时刺股，勤学我便耽。"]', '诗', 'shi', '', NULL, '缺偶詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4f5d46-c052-4ded-8e5f-dcb427a908f9', '不缺偶詩', '不缺偶诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["刺股君稱麗，懸頭我未能。"]', '["刺股君稱丽，懸头我未能。"]', '诗', 'shi', '', NULL, '不缺偶詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('388d397a-1317-4662-8e12-0d32219020e3', '對酒詩 一', '对酒诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["清觴酒恒滿，綠酒會盈杯。"]', '["清觴酒恒满，綠酒會盈杯。"]', '诗', 'shi', '', NULL, '對酒詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1bcd338-1fe3-4b4f-aaf3-766b713cc41a', '對酒詩 二', '对酒诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["滿酌余當進，彌甌我自傾。"]', '["满酌余當進，彌甌我自傾。"]', '诗', 'shi', '', NULL, '對酒詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b7cfc2-bbf3-44e6-9dea-68c2d7491fce', '詩', '诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["遠岫開翠雰，遙山卷青靄。","（以上三聯爲繁說病）。"]', '["远岫开翠雰，遙山卷青靄。","（以上三聯爲繁说病）。"]', '诗', 'shi', '', NULL, '詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b767e380-cf46-4284-b12f-b71f6a72014e', '不犯支離詩', '不犯支離诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["春人對春酒，新樹間新花。"]', '["春人对春酒，新樹间新花。"]', '诗', 'shi', '', NULL, '不犯支離詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9190bb9e-83e2-4994-a15a-8b2e0805fca8', '犯支離詩', '犯支離诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["人人皆偃息，唯我獨從戎。"]', '["人人皆偃息，唯我独從戎。"]', '诗', 'shi', '', NULL, '犯支離詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f064bae4-f724-4551-afe3-adee6c9a2b7f', '犯相濫詩', '犯相濫诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉繩耿長漢，金波麗碧空。","星光暗雲裏，月影碎簾中。"]', '["玉繩耿长漢，金波丽碧空。","星光暗云裏，月影碎簾中。"]', '诗', 'shi', '', NULL, '犯相濫詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('339d7d1c-0f1d-41d9-80ae-df6d53579f14', '詠月詩', '詠月诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉鉤千丈掛，金波萬里遙。","蚌虧輪影滅，蓂落桂陰銷。","入風花氣馥，出樹鳥聲嬌。","獨使高樓婦，空度可憐宵。"]', '["玉鉤千丈掛，金波万里遙。","蚌虧輪影滅，蓂落桂陰銷。","入风花氣馥，出樹鸟声嬌。","独使高楼婦，空度可怜宵。"]', '诗', 'shi', '', NULL, '詠月詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da8444f-2257-4a2b-bd7f-0b31f7c0b3f4', '詠春詩', '詠春诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["何處覓消愁？春園可暫遊。","菊黃堪泛酒，梅紅可插頭。","（以上二首爲落節詩）。"]', '["何处覓消愁？春园可暫游。","菊黄堪泛酒，梅紅可插头。","（以上二首爲落節诗）。"]', '诗', 'shi', '', NULL, '詠春詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e00273-5e23-4322-8d48-ce5fa44712ae', '憶友詩', '憶友诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["思君不可見，徒令年鬢秋。","獨驚積寒暑，迢遰阻風牛。","奧余慕樵隱，蕭然重一丘。","（此爲雜亂詩）。"]', '["思君不可见，徒令年鬢秋。","独驚積寒暑，迢遰阻风牛。","奧余慕樵隐，蕭然重一丘。","（此爲杂亂诗）。"]', '诗', 'shi', '', NULL, '憶友詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e472ac9c-835d-4e10-9eb6-246ce361ab8f', '秋詩', '秋诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["熠燿庭中度，蟋蟀傍窗吟。","條間垂白露，菊上帶黃金。"]', '["熠燿庭中度，蟋蟀傍窗吟。","條间垂白露，菊上带黄金。"]', '诗', 'shi', '', NULL, '秋詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f995887-e270-4c39-b4c2-18fe37938dcb', '詠秋詩', '詠秋诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["熠燿流寒火，蟋蟀動秋音。","凝露如懸玉，攢菊似披金。"]', '["熠燿流寒火，蟋蟀动秋音。","凝露如懸玉，攢菊似披金。"]', '诗', 'shi', '', NULL, '詠秋詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2966f277-55d3-4dcf-b9d4-e9f304cb9f32', '句 一', '句 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["渭濱迎宰相。"]', '["渭濱迎宰相。"]', '诗', 'shi', '', NULL, '句 一 無名氏 shi');
